/* ================= data/cn/huadong/shaoxing/sx_01_spots.js ================= */
/* 绍兴 分册01：景点圣地（鲁迅故里/水乡/名山/名人故迹） */
window.SX_SPOTS = window.SX_SPOTS || [];
window.SX_SPOTS.push(
  /* ---- 旧档原条目 ---- */
  { id: 'shaoxing_luxun', name: '鲁迅故里', icon: '🏠', price: 0, desc: '百草园到三味书屋，课本里的场景实景重现。免费预约，乌篷船码头就在门口，"跟着课本游绍兴"。' },
  { id: 'shaoxing_shen', name: '沈园', icon: '🌸', price: 40, desc: '陆游与唐琬《钗头凤》的爱情悲剧现场。两阕词刻在壁上相对而立，"伤心桥下春波绿"。' },
  { id: 'shaoxing_bazi', name: '八字桥·书圣故里', icon: '🌉', price: 0, desc: '宋代八字桥是"最早的立交桥"。书圣故里墨香满巷，王羲之题扇桥、蔡元培故居一路串起。' },
  { id: 'shaoxing_lanting', name: '兰亭', icon: '🖌️', price: 40, desc: '王羲之《兰亭集序》诞生地，"天下第一行书"的现场。曲水流觞的溪水仍在，可以体验仿古"飞花传觞"。' },
  { id: 'shaoxing_donghu', name: '东湖', icon: '🛶', price: 50, desc: '千年采石场变成的悬崖水潭，"江南小三峡"。乌篷船钻进仙桃洞，船工脚手并划的绝技。' },
  { id: 'shaoxing_kuaizige', name: '安昌古镇', icon: '🏮', price: 0, desc: '腊肠挂满河沿的"年味古镇"。腊月风情节，扯白糖拉成丝，社戏在河对面咿呀唱。' },
  { id: 'shaoxing_wupeng', name: '仓桥直街', icon: '🏮', price: 0, desc: '联合国遗产保护奖的老街，臭豆腐与黄酒铺并存。雨后青石板发光，"最绍兴的生活切片"。' },
  /* ---- 新增：名山陵庙 ---- */
  { id: 'sxp_dayuling', name: '大禹陵', icon: '🏛️', price: 60, desc: '会稽山下大禹陵，传说大禹会诸侯崩葬于此。登高可见“大禹陵”巨碑与石像，禹庙红墙古柏，祭禹大典庄严如仪。' },
  { id: 'sxp_huijishan', name: '会稽山', icon: '🌄', price: 0, desc: '会稽山是绍兴的“靠山”：大禹在此会诸侯，秦皇东巡曾登顶望海。云雾中的山脉静卧城南，阳明洞天藏一段心学源流。' },
  { id: 'sxp_xianglufeng', name: '香炉峰', icon: '⛰️', price: 15, desc: '会稽山东侧孤峰，形似香炉故名。晨起爬山的人影一串串，到顶能望见整座绍兴城，炉峰禅寺香火缭绕。' },
  { id: 'sxp_keyan', name: '柯岩·鉴湖·鲁镇', icon: '🏞️', price: 130, desc: '柯岩云骨奇石、鉴湖乌篷与鲁镇水街连成一票。穿行鲁迅小说里的街市，社戏台上鼓点一响，恍如走进《社戏》那晚。' },
  { id: 'sxp_xianheng', name: '咸亨酒店', icon: '🍶', price: 0, desc: '鲁迅笔下“咸亨”真的开了上百年。曲尺柜台前一碟茴香豆、一碗太雕酒，穿长衫的孔乙己铜像就立在门口。' },
  { id: 'sxp_fushan', name: '府山·越王台', icon: '🏯', price: 0, desc: '卧龙山即府山，越王勾践在此建台练兵，“卧薪尝胆”的出处。山上有飞翼楼望古城，范蠡种过兰的山坡是越城龙脉。' },
  { id: 'sxp_guxuan', name: '古轩亭口·秋瑾纪念碑', icon: '🕊️', price: 0, desc: '秋瑾从容就义的轩亭口，如今立着纪念碑与风雨亭。那句“秋风秋雨愁煞人”刻在石上，游人路过总会放慢脚步。' },
  { id: 'sxp_qingteng', name: '青藤书屋', icon: '🎨', price: 0, desc: '明代大才子徐渭的书屋小到转不开身，却“青藤书屋”名满天下。天池边那株青藤是他手植，五百年的泼墨气还在墙头。' },
  { id: 'sxp_huangjiuxiaozhen', name: '东浦·黄酒小镇', icon: '🏮', price: 0, desc: '鉴湖边的水乡东浦，黄酒从这里发源。酒坊沿河而设，冬酿时节蒸米香飘半条街，可看老师傅踩曲、开耙。' },
  { id: 'sxp_huangjiubowu', name: '中国黄酒博物馆', icon: '🍶', price: 0, desc: '黄酒博物馆藏着一坛坛老酒，地下酒窖阴凉昏暗。在这里看懂绍兴人说的“生个女儿就埋一坛酒”，还能呷一口年份原浆。' },
  { id: 'sxp_yingenmen', name: '迎恩门水街', icon: '⛩️', price: 0, desc: '明清迎恩门城楼下的水街，入夜灯笼亮起，坐船过廊桥看两岸酒旗。本地人饭后散步，“小桥流水夜绍兴”的样板。' },
  /* ---- 新增：名人士迹 ---- */
  { id: 'sxp_datong', name: '大通学堂', icon: '🏫', price: 0, desc: '光复会创办的体操学堂，徐锡麟、秋瑾曾在此训练志士。教室里的旧课桌安安静静，却曾酝酿过一场推翻帝制的起事。' },
  { id: 'sxp_zhouenlai', name: '周恩来祖居', icon: '🏡', price: 0, desc: '百岁堂坐落在劳动路老宅，是周恩来祖辈生活之地。堂前的水井照过周家孩子的脸，图片展里读得出这位绍兴人的乡愁。' },
  { id: 'sxp_caiyuan', name: '蔡元培故居', icon: '🎓', price: 0, desc: '笔飞弄里的老台门，北大校长蔡元培就出生在此。展厅的墨迹与手稿很多，一位“学界泰斗”从水乡石板路走向了世界。' },
  { id: 'sxp_jinghu', name: '镜湖·梅山湿地', icon: '🌾', price: 0, desc: '镜湖新区的水上森林，芦苇荡里白鹭起落。木栈道从荷塘穿过，春秋天骑车露营的人最多，是绍兴人的“城市绿肺”。' },
  /* ---- 新增：市域延伸（诸暨/新昌/嵊州） ---- */
  { id: 'sxp_xishi', name: '西施故里（诸暨）', icon: '🌺', price: 0, desc: '诸暨苎萝山下，西施浣纱的江边立着她的汉白玉像。越女如水的传说从这儿流了千年，郑旦与范蠡的故事一并讲给你听。' },
  { id: 'sxp_wuxie', name: '五泄飞瀑（诸暨）', icon: '💦', price: 80, desc: '诸暨五泄瀑布分五级跌落山间，夏天水汽扑面。步行或乘船进峡谷，一路看第五泄轰然坠潭，第四泄斜飘如练。' },
  { id: 'sxp_dafo', name: '新昌大佛寺', icon: '🙏', price: 100, desc: '新昌大佛寺凿于南朝，江南第一大佛坐像高达十六米，衣纹层层如流水。石城古刹暮鼓晨钟，石窟里安静得能听见呼吸。' },
  { id: 'sxp_yueju', name: '越剧小镇（嵊州）', icon: '🎭', price: 0, desc: '嵊州是越剧的娘家，小镇里戏台、展馆与练功房连成一片。姑娘们水袖轻扬唱起婉转的吴语腔，声音绵软得像剡溪水。' }
);

/* ================= data/cn/huadong/shaoxing/sx_02_gifts.js ================= */
/* 绍兴 分册02：特色周边（黄酒美食/水乡手信/名人文创/体验住宿） */
window.SX_GIFTS = window.SX_GIFTS || [];
window.SX_GIFTS.push(
  /* ---- 旧档原条目（souvenirs） ---- */
  { id: 'shaoxing_huangjiu', name: '绍兴黄酒', icon: '🍶', tag: '食', type: '饮品', price: 60, desc: '女儿红、花雕、加饭酒，黄酒界的"泰山北斗"。鉴湖水酿的酒加冰或烫饮皆宜，"越陈越香"。' },
  { id: 'shaoxing_choudoufu', name: '臭豆腐', icon: '🧆', tag: '食', type: '美食', price: 10, desc: '苋菜梗卤浸的"黑色经典"，闻着臭吃着香。仓桥直街现炸现吃，配甜辣酱双拼。' },
  { id: 'shaoxing_meigancai', name: '梅干菜扣肉', icon: '🍖', tag: '食', type: '美食', price: 40, desc: '乌干菜配五花肉蒸到酥烂，"干菜黑油油"。鲁迅笔下的家乡味，真空装带回家。' },
  { id: 'shaoxing_huixiang', name: '茴香豆', icon: '🫘', tag: '食', type: '特产', price: 15, desc: '孔乙己"多乎哉不多也"的下酒豆。咸香耐嚼，配黄酒温两碗，"按孔乙己的姿势"吃。' },
  { id: 'shaoxing_xianggao', name: '奶油小攀·香糕', icon: '🍰', tag: '食', type: '美食', price: 12, desc: '绍兴老底子点心，小攀蛋香奶香。香糕干脆配茶，都是"外婆的味道"。' },
  { id: 'shaoxing_wuzhanmao', name: '乌毡帽', icon: '🎩', tag: '衣', type: '服饰', price: 40, desc: '鲁迅同款乌毡帽，绍兴农民的百年标配。戴上拍照秒变"闰土"，纪念意义拉满。' },
  { id: 'shaoxing_shuhua', name: '兰亭书法文创', icon: '🖌️', tag: '衣', type: '文创', price: 60, desc: '《兰亭集序》字帖、扇面与书签。书法爱好者必收，"天下第一行书"随身带。' },
  { id: 'shaoxing_yin', name: '铜镜·青瓷', icon: '🏺', tag: '衣', type: '文创', price: 90, desc: '绍兴越窑青瓷复刻小件，"秘色瓷"的家乡。铜镜纹样胸针，越国古都的手艺。' },
  { id: 'shaoxing_wupengchuan', name: '乌篷船游水巷', icon: '🛶', tag: '行', type: '体验', price: 85, desc: '船工脚踩橹手划桨，乌篷船钻过古桥洞。"船头看水，船尾看街"，绍兴的水上视角。' },
  { id: 'shaoxing_paojiu', name: '黄酒博物馆品酒·花雕DIY', icon: '🏺', tag: '玩', type: '体验', price: 100, desc: '看百年酒窖，亲手在花雕酒坛上题字封存。女儿红的故事现场复刻，"给未来存一坛酒"。' },
  { id: 'shaoxing_sheying', name: '安昌腊月风情节', icon: '🧨', tag: '玩', type: '体验', price: 60, desc: '腊月的安昌满街腊肠与酱鸭，扯白糖表演。社戏水上唱，"江南年味最浓的古镇"。' },
  { id: 'shaoxing_minsu', name: '水乡台门民宿', icon: '🏨', tag: '住', type: '住宿', price: 280, desc: '老台门改的民宿，天井里晒着腊味。夜里枕着水声入睡，清晨乌篷船欸乃而过。' },
  /* ---- 新增：黄酒新喝法 ---- */
  { id: 'sxg_zuixie', name: '醉蟹', icon: '🦀', tag: '食', type: '美食', price: 90, desc: '青壳白肚的湖蟹在陈年黄酒里浸足七日，酒香钻进蟹壳。开坛那刻蟹黄呈半凝膏状，抿一口鲜甜带酒气，是绍兴人的秋日仪式。' },
  { id: 'sxg_huangjiubing', name: '黄酒棒冰', icon: '🍦', tag: '食', type: '美食', price: 15, desc: '黄酒加奶冻成的小棒冰，咬下去先是奶香，再是淡淡酒酿回味。鲁迅故里门口人手一支，边走边啃很绍兴。' },
  { id: 'sxg_huangjiunaicha', name: '黄酒奶茶', icon: '🧋', tag: '食', type: '饮品', price: 25, desc: '奶茶里加一勺花雕，顶上的酒酿小圆子糯糯的。年轻人在乌篷船码头边喝边拍，“不醉人却上头”的黄酒新喝法。' },
  /* ---- 新增：水乡风味手信 ---- */
  { id: 'sxg_lachang', name: '安昌腊肠', icon: '🥓', tag: '食', type: '特产', price: 55, desc: '腊月里灌好的酱肠成串挂在河沿晾晒，风里飘着酱香。回家切片蒸饭，咸鲜微甜，越嚼越有安昌的年味。' },
  { id: 'sxg_meigancai', name: '乌干菜礼盒', icon: '🥬', tag: '食', type: '特产', price: 38, desc: '芥菜晒足三蒸三晒的乌干菜，鲁迅最惦记的家乡味。焖肉、蒸笋、下面，一小撮就能点亮一锅平凡的汤。' },
  { id: 'sxg_zuoyu', name: '醉鱼干', icon: '🐟', tag: '食', type: '特产', price: 45, desc: '草鱼风干后浸入加饭酒，酒香渗进鱼肉纹理。切片上锅一蒸，咸鲜回甘，配一碗热粥正正好，是水乡的下酒硬菜。' },
  { id: 'sxg_yingao', name: '绍兴印糕', icon: '🍥', tag: '食', type: '特产', price: 30, desc: '米粉压进雕花木模，蒸出一块块带花纹的软糕。淡甜不腻，刚出锅热气腾腾，老人小孩都爱吃。' },
  { id: 'sxg_mulian', name: '木莲豆腐', icon: '🍮', tag: '食', type: '美食', price: 12, desc: '木莲籽搓出的透明冻，浇上薄荷糖水与醋，夏天一碗透心凉。仓桥直街的小摊，是老绍兴的解暑密码。' },
  { id: 'sxg_huangjiu_qiao', name: '黄酒巧克力', icon: '🍫', tag: '食', type: '特产', price: 42, desc: '太雕酒揉进黑巧克力，微苦酒香与可可脂在舌尖化开。酒心夹层像极绍兴人的低调：甜里藏着一点烈。' },
  /* ---- 新增：名人文创 ---- */
  { id: 'sxg_yueju_fan', name: '越剧梁祝折扇', icon: '🪭', tag: '玩', type: '文创', price: 75, desc: '越剧梁祝主题绢扇，扇面绘着化蝶的双影。打开是水袖般的弧度，收拢是一段“十八相送”的婉转唱腔。' },
  { id: 'sxg_shiye', name: '绍兴师爷扇', icon: '🖋️', tag: '玩', type: '文创', price: 68, desc: '“无绍不成衙”——一把师爷扇题着诙谐小楷，摇扇间仿佛看见幕僚们运筹帷幄。安昌的师爷故里把这股机敏做成了文创。' },
  { id: 'sxg_liushang', name: '兰亭流觞杯', icon: '🥃', tag: '玩', type: '文创', price: 88, desc: '仿古流觞小酒盏，外壁刻“曲水流觞”四字。约三五好友围坐，把酒盏顺水推过，过一把王羲之们的雅集瘾。' },
  { id: 'sxg_yueyao', name: '越窑秘色茶盏', icon: '🍵', tag: '玩', type: '文创', price: 120, desc: '越窑青瓷的故乡就在曹娥江边，一只秘色釉茶盏温润如水。捧在手里，像把千年前的“千峰翠色”揣进兜。' },
  { id: 'sxg_huadan', name: '花雕彩绘小酒坛', icon: '🏺', tag: '玩', type: '文创', price: 108, desc: '巴掌大的袖珍酒坛，画着龙凤呈祥的花雕纹样，坛里真的装了陈酿。摆在家里是摆件，开坛就是一小桌绍兴的黄昏。' },
  /* ---- 新增：体验住宿 ---- */
  { id: 'sxg_shenyuan', name: '沈园之夜演出票', icon: '🎭', tag: '游', type: '体验', price: 120, desc: '入夜后的沈园亮起灯笼，越剧与绍剧在孤鹤轩前演《钗头凤》。水边的座次挤满人，陆游唐琬的旧事在唱词里再活一遍。' },
  { id: 'sxg_moxiang', name: '书圣故里·墨香民宿', icon: '🛏️', tag: '住', type: '住宿', price: 320, desc: '书圣故里的老台门改成民宿，窗外就是题扇桥与墨池。清晨被檐下的鸟叫醒，推窗是白墙黛瓦的水乡景致。' }
);

/* ================= data/cn/huadong/shaoxing/sx_03_stories.js ================= */
/* 绍兴 分册03：奇闻趣事（名人/黄酒/水乡/民俗） */
window.SX_STORIES = window.SX_STORIES || [];
window.SX_STORIES.push(
  /* ---- 旧档原条目 ---- */
  { id: 'shaoxing_story_kong', name: '孔乙己的茴香豆', icon: '🫘', desc: '"多乎哉？不多也"——咸亨酒店门口的孔乙己铜像成了打卡点。温两碗黄酒要一碟茴香豆，是"标准姿势"。' },
  { id: 'shaoxing_story_lu', name: '鲁迅的一天', icon: '📖', desc: '从百草园到三味书屋步行十分钟。游客按"鲁迅路线"走一圈：祖居、私塾、当铺、咸亨酒店，"课本实景版"。' },
  { id: 'shaoxing_story_nver', name: '女儿红的"十八年之约"', icon: '🍶', desc: '生女儿时埋下花雕，出嫁时挖出宴客。一坛酒藏尽父爱，"女儿红"三字值千金。' },
  { id: 'shaoxing_story_lanting', name: '曲水流觞的"文人游戏"', icon: '🍶', desc: '王羲之和41位名士溪边饮酒赋诗，微醺写下《兰亭集序》。现场重演时才明白：灵感需要酒助攻。' },
  { id: 'shaoxing_story_wupeng', name: '脚划船的绝技', icon: '🛶', desc: '乌篷船船工用脚蹬桨手扶楫，"手脚并用"全国独一份。这是绍兴人几百年练出的水上功夫。' },
  { id: 'shaoxing_story_chou', name: '绍兴人的"臭味相投"', icon: '👃', desc: '苋菜梗卤是绍兴"臭味宇宙"的中心：臭豆腐、臭千张都出自它。外地人捏鼻子尝一口，真香。' },
  /* ---- 新增：大禹与兰亭 ---- */
  { id: 'sxs_dayu', name: '大禹会诸侯于会稽', icon: '⛰️', desc: '治水成功后大禹在会稽大会诸侯、计功行赏，山便得名“会稽”。他最终归葬于此，绍兴人把这座城的故事起点，埋进了禹陵的青石之下。' },
  { id: 'sxs_lanting_zhenji', name: '兰亭真迹的下落', icon: '📜', desc: '《兰亭集序》真迹相传被唐太宗带进昭陵，如今能见的都是摹本。冯承素的神龙本最像，看那处涂改的笔迹，能想象王羲之微醺时的随性。' },
  { id: 'sxs_huane', name: '写经换鹅', icon: '🦢', desc: '王羲之爱鹅成痴，山阴道士用一群白鹅换他抄一卷《黄庭经》。写罢笼鹅而归，兰亭鹅池里如今还养着白鹅，像是在等故人。' },
  { id: 'sxs_tishan', name: '题扇桥的传说', icon: '🪭', desc: '老妪在桥头卖扇无人问津，王羲之随手为每把扇子题字，生意立刻火爆。后人把这桥叫作题扇桥，书圣的墨宝从没让绍兴人失望。' },
  /* ---- 新增：名人轶事 ---- */
  { id: 'sxs_goujian', name: '卧薪尝胆的越王台', icon: '⚔️', desc: '勾践败于吴国后立志复仇，把苦胆挂在坐卧处日日舔尝，这便是“卧薪尝胆”。府山上越王台的夯土里，藏着一段忍辱复国的十年。' },
  { id: 'sxs_huansha', name: '西施浣纱', icon: '🪞', desc: '西施本是诸暨的浣纱女，被选入吴宫前常在江边浣纱。传说水中的倒影美得让鱼忘了游，后人便把这条江叫作浣纱江。' },
  { id: 'sxs_qiuyin', name: '鉴湖女侠秋瑾', icon: '🕊️', desc: '秋瑾自号鉴湖女侠，留日、办报、操练新军，起义事败后在轩亭口从容就义。就义前她留下的那句“秋风秋雨愁煞人”，读来仍凉。' },
  { id: 'sxs_shenyuanci', name: '沈园里的钗头凤', icon: '🌹', desc: '陆游在沈园偶遇改嫁的唐琬，于粉壁题下《钗头凤》，唐琬和作后郁郁而终。四十年后陆游重游故地，写下“伤心桥下春波绿”。' },
  { id: 'sxs_shiye', name: '无绍不成衙', icon: '🪶', desc: '清代官署里绍兴师爷最多，主官换了一茬茬，幕僚却代代相传。刑名、钱谷样样精通，“无绍不成衙”成了官场流传的老话。' },
  { id: 'sxs_luzhen', name: '鲁镇在柯岩重生', icon: '🏮', desc: '鲁镇本是鲁迅小说里虚构的地名，柯岩却把它照进了现实。阿Q、祥林嫂与孔乙己在青石板街上一一“复活”，游客常和“闰土”擦肩。' },
  { id: 'sxs_zaozi', name: '书桌上的“早”字', icon: '📖', desc: '鲁迅在三味书屋的书桌上刻了个“早”字，只为提醒自己侍疾后别再迟到。如今课桌原样摆着，那道刻痕里是一个少年发狠的清晨。' },
  { id: 'sxs_baiyuan', name: '百草园的童心', icon: '🦗', desc: '何首乌、斑蝥、蟋蟀、覆盆子，鲁迅笔下的百草园是少年乐园。园里还种着皂荚树与桑椹，课本里那句“不必说”依然鲜活如昨。' },
  { id: 'sxs_shexi', name: '鲁迅的社戏之夜', icon: '🛶', desc: '《社戏》里少年们摇船看戏的夏夜，写的是水乡孩子的快乐。绍兴至今保留水上戏台，锣鼓一响，乌篷船便静静泊在台下听。' },
  /* ---- 新增：水乡风物 ---- */
  { id: 'sxs_wuzhanmao', name: '乌毡帽的由来', icon: '🎩', desc: '传说猎人救下一只刺猬，血迹凝成的毛毡可以挡雨，绍兴人便仿着做起乌毡帽。黑毡圆顶冬暖夏凉，成了农民与水乡客的标配。' },
  { id: 'sxs_yueju', name: '越剧从嵊州唱到全国', icon: '🎭', desc: '一百多年前，嵊州的说唱班先学女班，一路唱成全国第二大剧种。如今听《梁祝》腔调绵软如水，源头仍是剡溪边的那句田歌。' },
  { id: 'sxs_donghu_zaoshi', name: '东湖的斧凿之痕', icon: '⛏️', desc: '汉代起，山石被采去建城造桥，千年后留下斧凿而成的悬崖深潭。乌篷船在仙桃洞、陶公洞间穿行，抬头便是九十度直立的石壁。' },
  { id: 'sxs_dongniang', name: '冬酿一城酒香', icon: '🌾', desc: '立冬后鉴湖水最清冽，绍兴酒坊纷纷开酿，蒸糯米的白气漫过屋檐。酿酒师傅相信，冬水酿的酒能存百年，这是江南的时间生意。' },
  { id: 'sxs_taimen', name: '老台门的烟火', icon: '🏘️', desc: '绍兴人把深宅大屋叫作台门，石库门里天井、厢房、水井一应俱全。许多台门如今仍住着人家，晾衣绳从雕花檐角下悠悠穿过。' }
);

/* ================= data/cn/huadong/shaoxing/shaoxing.js ================= */
/* ============ 浙江·绍兴（完全版·分册组装） ============
 * 分册：sx_01地点 / sx_02周边 / sx_03趣事。
 * 叙事主线：鲁迅故里 / 黄酒 / 水乡 / 名人荟萃。
 */
(function () {
  window.TRAVEL_CITIES = window.TRAVEL_CITIES || [];
  window.TRAVEL_CITIES.push({
    id: 'shaoxing',
    name: '绍兴',
    country: '中国',
    cc: 'CN',
    province: '浙江',
    flag: '🇨🇳',
    region: '华东',
    hero: '🛶',
    desc: '鲁迅笔下的水乡：乌篷船摇过八字桥，孔乙己的茴香豆温两碗黄酒，书圣故里与千年古城墙，一座可以"读"的城市。',
    travel: [{ name: '高铁', icon: '🚄', cost: 400 }, { name: '飞机', icon: '✈️', cost: 730 }],
    visa: null,
    spots: (window.SX_SPOTS = window.SX_SPOTS || []),
    souvenirs: (window.SX_GIFTS = window.SX_GIFTS || []),
    stories: (window.SX_STORIES = window.SX_STORIES || []),
  });
})();

/* ================= data/cn/huadong/suzhou/suz_01_spots.js ================= */
/* 苏州 分册01：景点圣地（江南园林/古城水巷/山寺钟声/太湖古镇） */
window.SUZ_SPOTS = window.SUZ_SPOTS || [];
window.SUZ_SPOTS.push(
  /* ---- 名园（沿用原条目） ---- */
  { id: 'suzhou_zhuozheng', name: '拙政园', icon: '🌿', price: 80, desc: '中国四大名园之首，"一步一景"的江南园林巅峰。借景北寺塔的构图绝了，夏天荷花满池，雨打芭蕉更有味。' },
  { id: 'suzhou_liuyuan', name: '留园·网师园', icon: '🏡', price: 55, desc: '留园冠云峰亭亭玉立，网师园是"小园极则"。夜游网师园有昆曲演出，园林夜宴梦回明清。' },
  { id: 'szp_shizilin', name: '狮子林', icon: '🪨', price: 40, desc: '元代禅林里的太湖石假山，迷宫一样的石洞绕来绕去。乾隆六下江南五次来此，还题了"真趣"二字。' },
  { id: 'szp_canglang', name: '沧浪亭', icon: '🏡', price: 20, desc: '苏州现存最古老园林，一泓沧浪水绕园而过。"清风明月本无价，近水远山皆有情"，园名对联道尽风雅。' },
  { id: 'szp_ouyuan', name: '耦园', icon: '💞', price: 25, desc: '"耦园住佳耦，城曲筑诗城"。沈秉成夫妇在此双隐，亭台处处成双。全苏州最甜的一座园子。' },
  { id: 'szp_yipu', name: '艺圃', icon: '🌹', price: 10, desc: '藏在巷子里的小园，蔷薇季爬满白墙。茶室临水，老苏州端着茶杯看池鱼，本地人最爱的园子。' },
  { id: 'szp_huanxiu', name: '环秀山庄', icon: '⛰️', price: 15, desc: '一座湖石假山独占园心，叠山大师戈裕良的手笔。假山里可游可居，被称"尺幅千里"的立体山水。' },
  /* ---- 古城水巷（沿用原条目） ---- */
  { id: 'suzhou_pingjiang', name: '平江路·山塘街', icon: '🌉', price: 0, desc: '800年格局未变的水巷，摇橹船欸乃而过。评弹声从茶馆飘出，"君到姑苏见，人家尽枕河"。' },
  { id: 'suzhou_huqiu', name: '虎丘', icon: '⛰️', price: 70, desc: '"到苏州不游虎丘乃憾事也"——苏东坡说的。斜塔云岩寺塔比比萨斜塔还早，剑池下藏着吴王阖闾墓之谜。' },
  { id: 'suzhou_beisita', name: '北寺塔·盘门三景', icon: '🛕', price: 0, desc: '北寺塔是苏州古城制高点。盘门是中国唯一水陆并列城门，"吴都八门"的水门闸口仍在。' },
  { id: 'szp_shuangta', name: '双塔市集', icon: '🥬', price: 0, desc: '罗汉院双塔旁的菜场改造成"网红市集"，苏州话涂鸦、小吃与花店混搭。菜场逛出了美术馆的调调。' },
  { id: 'szp_fengmen', name: '葑门横街', icon: '🛒', price: 0, desc: '苏州最市井的早市街，凌晨五点半就热闹起来。茨菰、鸡头米、青团子沿街叫卖，本地人买菜都认这条街。' },
  { id: 'szp_guangqian', name: '观前街', icon: '🏮', price: 0, desc: '老牌商业街，玄妙观的大殿立在街心。采芝斋、陆稿荐的老字号一家挨一家，苏州人的"市中心"。' },
  /* ---- 山寺与馆舍 ---- */
  { id: 'szp_hanshan', name: '寒山寺·枫桥', icon: '🛕', price: 20, desc: '"姑苏城外寒山寺，夜半钟声到客船"。张继的一首诗红了上千年，古钟楼里敲三下钟，烦恼散一半。' },
  { id: 'szp_xiyuan', name: '西园寺', icon: '🐈', price: 5, desc: '五百罗汉堂与放生池，寺里的猫比香客还淡定。一碗素面配烤麸，苏州人把寺院逛成了茶馆。' },
  { id: 'szp_yuyao', name: '御窑金砖博物馆', icon: '🧱', price: 0, desc: '故宫太和殿的金砖产自苏州御窑。看"敲之有声、断之无孔"的金砖如何烧制，皇家地砖的前世今生。' },
  { id: 'szp_kunqu', name: '中国昆曲博物馆', icon: '🎭', price: 0, desc: '全晋会馆的古戏台巍峨，昆曲从这里唱了六百年。馆里还能体验扮相与水袖，一颦一笑都是程式之美。' },
  { id: 'szp_suda', name: '苏州大学·天赐庄', icon: '📚', price: 0, desc: '百年校区红砖钟楼立在银杏间，欧式教学楼爬满青藤。深秋满地金黄，像走进民国老电影。' },
  { id: 'suzhou_bowuguan', name: '苏州博物馆', icon: '🏛️', price: 0, desc: '贝聿铭封山之作，"中而新、苏而新"。片石假山以壁为纸、以石为绘，馆藏秘色瓷莲花碗是国宝。' },
  { id: 'szp_wuzhongbowu', name: '吴文化博物馆', icon: '🏺', price: 0, desc: '太湖边的吴文化宝库，青铜剑与原始瓷诉说着吴国往事。新馆临湖而建，看完展正好看太湖日落。' },
  /* ---- 太湖与古镇 ---- */
  { id: 'szp_mudu', name: '木渎古镇·天平山', icon: '🏘️', price: 0, desc: '乾隆六下江南必到的木渎，严家花园与虹饮山房相连。深秋天平山红枫如霞，江南四大赏枫地之一。' },
  { id: 'szp_lingyan', name: '灵岩山', icon: '⛰️', price: 0, desc: '吴王夫差为西施建馆娃宫于此，山顶灵岩山寺香火千年。登高望太湖，苏州城的山水之气都在眼底。' },
  { id: 'szp_tongli', name: '同里古镇', icon: '🌉', price: 100, desc: '退思园小巧玲珑，走三桥、坐摇橹船穿镇而过。家家临水、户户枕河，水乡的安静都在晨雾里。' },
  { id: 'szp_zhouzhuang', name: '周庄古镇', icon: '🏯', price: 100, desc: '陈逸飞画过双桥后，"中国第一水乡"的名头响遍世界。富安桥下的摇橹船摇过明清，梦里水乡有了模样。' },
  { id: 'szp_yangcheng', name: '阳澄湖·莲花岛', icon: '🦀', price: 0, desc: '大闸蟹的圣地，湖心莲花岛四面环水。秋天蟹肥时全岛飘香，坐在湖边啃蟹看落日，江南的秋天就圆满了。' },
  { id: 'szp_dongshan', name: '东山·太湖', icon: '🏝️', price: 0, desc: '太湖边的花果山，五月枇杷六月杨梅。启园的码头伸进湖心，紫金庵的罗汉像栩栩如生。' },
  { id: 'szp_xishan', name: '西山·林屋梅海', icon: '🌸', price: 0, desc: '太湖中的岛屿西山，二月林屋洞前梅海如雪。登缥缈峰看太湖三万六千顷，烟波里都是渔帆。' },
  /* ---- 当代苏州（沿用原条目） ---- */
  { id: 'suzhou_jinji', name: '金鸡湖·诚品书店', icon: '🌃', price: 0, desc: '园区摩天楼天际线与古典苏州形成对望。东方之门"秋裤楼"打卡，诚品书店通宵购书的文艺地标。' },
  { id: 'szp_shihu', name: '石湖·上方山', icon: '🌊', price: 0, desc: '范成大隐居的石湖，行春桥九孔连拱。秋天上方山的银杏与桂花，苏州人踏秋的私藏地。' }
);

/* ================= data/cn/huadong/suzhou/suz_02_gifts.js ================= */
/* 苏州 分册02：特色周边（苏式汤面/太湖时鲜/刺绣丝绸/水乡体验） */
window.SUZ_GIFTS = window.SUZ_GIFTS || [];
window.SUZ_GIFTS.push(
  /* ---- 苏式面点与时鲜（沿用原条目） ---- */
  { id: 'suzhou_tangmian', name: '苏式汤面', icon: '🍜', tag: '食', type: '美食', price: 25, desc: '"头汤面"是苏州人的仪式感：枫镇大肉面、三虾面。浇头几十种，面细如银丝汤清而不寡。' },
  { id: 'suzhou_yuebing', name: '苏式鲜肉月饼', icon: '🥮', tag: '食', type: '美食', price: 10, desc: '现烤酥皮一咬掉渣，鲜肉馅汁水丰盈。长发西饼、胥城大厦的队伍排出半条街。' },
  { id: 'suzhou_songshu', name: '松鼠桂鱼', icon: '🐟', tag: '食', type: '美食', price: 120, desc: '炸得形如松鼠浇糖醋汁"吱吱"作响。苏帮菜的排面担当，造型与味道双杀。' },
  { id: 'suzhou_gao', name: '桂花糕·青团', icon: '🍡', tag: '食', type: '美食', price: 15, desc: '桂花拉糕黏糯不粘牙，青团豆沙春日限定。采芝斋的老味，配一壶碧螺春正好。' },
  { id: 'suzhou_biluochun', name: '洞庭碧螺春', icon: '🍵', tag: '食', type: '特产', price: 120, desc: '洞庭东西山的"吓煞人香"，一嫩三鲜。明前茶卷曲如螺，白毫隐翠，杯中"春满江南"。' },
  { id: 'szg_sanxiamian', name: '三虾面', icon: '🦐', tag: '食', type: '美食', price: 108, desc: '虾籽、虾脑、虾仁三样炒成浇头，一碗面价格不菲。苏州人夏天的顶奢，一年就吃那两三个月。' },
  { id: 'szg_fengzhen', name: '枫镇大肉面', icon: '🍖', tag: '食', type: '美食', price: 30, desc: '白汤吊得清鲜，大肉焖得酥烂入口即化。老苏州宁可排队也要喝这碗"头汤"，大暑天更是一碗难求。' },
  { id: 'szg_tangzhou', name: '笃笃笃糖粥', icon: '🥣', tag: '食', type: '美食', price: 10, desc: '红豆沙配白粥搅出云纹，甜得温润。旧时巷口"笃笃笃，卖糖粥"的竹梆声，是老苏州的童年暗号。' },
  { id: 'szg_aotaomian', name: '奥灶面', icon: '🍜', tag: '食', type: '美食', price: 25, desc: '昆山奥灶面红汤白汤各有拥趸，鸭浇爆鱼浇头讲究。面细汤浓，一句"奥灶"（邋遢）藏着深功夫。' },
  { id: 'szg_lvdoutang', name: '苏式绿豆汤', icon: '🧋', tag: '食', type: '饮品', price: 10, desc: '绿豆、糯米、冬瓜糖、蜜枣泡在薄荷水里，清凉解暑。和别处的绿豆汤不是一个物种，苏州独一份。' },
  { id: 'szg_cangshu', name: '藏书羊肉', icon: '🍲', tag: '食', type: '美食', price: 60, desc: '木渎藏书镇的白汤羊肉锅，羊肉酥烂汤色奶白。秋风一起，苏州人的暖意都在这锅里。' },
  { id: 'szg_taihu', name: '太湖三白礼盒', icon: '🐟', tag: '食', type: '特产', price: 60, desc: '白鱼、白虾、银鱼是太湖的馈赠，做成干货礼盒带回家。"太湖三白"清蒸白灼，鲜得原汁原味。' },
  { id: 'szg_jitoumi', name: '南塘鸡头米', icon: '🌰', tag: '食', type: '特产', price: 35, desc: '芡实剥壳取米，一斤鲜米要剥上千粒。桂花糖水煮一碗，苏州人秋天最温柔的甜。' },
  { id: 'szg_yangxie', name: '阳澄湖大闸蟹', icon: '🦀', tag: '食', type: '美食', price: 138, desc: '青背白肚、金爪黄毛的正宗阳澄湖大闸蟹。蒸熟剥开，蟹黄如金蟹膏似玉，配黄酒姜醋才算完整。' },
  /* ---- 刺绣丝绸与手信（沿用原条目） ---- */
  { id: 'suzhou_cixiu', name: '苏绣', icon: '🪡', tag: '衣', type: '文创', price: 150, desc: '四大名绣之首，双面绣猫"正反如一"。一根丝线劈成六十四分之一，绣娘的手是活体放大镜。' },
  { id: 'suzhou_silk', name: '丝绸围巾', icon: '🧣', tag: '衣', type: '服饰', price: 180, desc: '苏州丝绸博物馆旁的真丝围巾，宋锦缎面。"蚕桑之乡"的温柔，送长辈最合适。' },
  { id: 'szg_songjin', name: '宋锦手包', icon: '👜', tag: '衣', type: '服饰', price: 220, desc: '宋锦织工繁复，几何纹样富丽典雅。做成小手包拿在手里，苏州的织造美学随身走。' },
  { id: 'szg_kesi', name: '缂丝团扇', icon: '🪭', tag: '玩', type: '文创', price: 260, desc: '缂丝"通经断纬"，一寸缂丝一寸金。一把缂丝团扇摇起来，千年的织法都在指尖生风。' },
  { id: 'suzhou_yuanlin', name: '园林文创', icon: '🪟', tag: '衣', type: '文创', price: 45, desc: '花窗、太湖石造型冰箱贴与折扇。"移步换景"做成文具，桌上一角江南。' },
  { id: 'szg_luzhi', name: '太湖石镇纸', icon: '🪨', tag: '玩', type: '文创', price: 55, desc: '瘦漏透皱的太湖石微缩成镇纸，摆在案头就是一座小园林。文人雅士的书桌，少不了一块好石。' },
  /* ---- 水乡体验与住宿（沿用原条目+新增） ---- */
  { id: 'suzhou_pipa', name: '评弹体验', icon: '🎻', tag: '玩', type: '体验', price: 80, desc: '平江路茶馆听吴侬软语弹词开篇。听不懂词也醉了，琵琶三弦叮咚入梦。' },
  { id: 'suzhou_chuan', name: '摇橹船水巷游', icon: '🛶', tag: '行', type: '体验', price: 60, desc: '摇橹阿姨哼着小调穿水巷，两岸枕河人家。船娘吴歌一开嗓，"苏州的声音"。' },
  { id: 'suzhou_hanfu', name: '园林汉服旅拍', icon: '📸', tag: '玩', type: '体验', price: 250, desc: '穿宋制汉服在拙政园拍写真，月洞门与花窗入镜。"园林+汉服"是苏州旅拍的顶配。' },
  { id: 'szg_kunqu', name: '夜听一场昆曲', icon: '🎭', tag: '玩', type: '体验', price: 120, desc: '山塘街的昆曲馆里水磨腔婉转，杜丽娘的"皂罗袍"一响，全场屏息。园林夜戏，是苏州给游人的梦。' },
  { id: 'szg_xiuxue', name: '苏绣体验课', icon: '🧵', tag: '玩', type: '体验', price: 100, desc: '在绣娘指导下劈丝穿针，绣一只小兰花。一枚丝线劈出八股，才懂"指尖芭蕾"有多难。' },
  { id: 'szg_yaolu', name: '学摇橹船', icon: '🚣', tag: '玩', type: '体验', price: 80, desc: '跟着船娘学摇橹，一推一扳要会"借水劲"。摇出第一个直线，成就感比坐船强十倍。' },
  { id: 'suzhou_minsu', name: '临水民宿', icon: '🏨', tag: '住', type: '住宿', price: 450, desc: '平江路深处的白墙黛瓦民宿，推窗就是小桥流水。夜里评弹声隐约，一枕江南。' }
);

/* ================= data/cn/huadong/suzhou/suz_03_stories.js ================= */
/* 苏州 分册03：奇闻趣事（园林哲思/水巷人家/缂绣匠魂/四季风物） */
window.SUZ_STORIES = window.SUZ_STORIES || [];
window.SUZ_STORIES.push(
  /* ---- 园林哲思 ---- */
  { id: 'suzhou_story_yuanlin', name: '园林的"框景魔法"', icon: '🪟', desc: '苏州园林用月洞门、花窗做"画框"，一框一景。设计师说：园林不是房子多，是"看不见的地方"多。' },
  { id: 'szs_sizhi', name: '一园藏尽四时', icon: '🌳', desc: '造园人把春海棠、夏荷、秋桂、冬梅种进同一座园子。在苏州园林里走一圈，等于看完一年四季的花事。' },
  { id: 'szs_shizilin', name: '狮子林的假山迷宫', icon: '🪨', desc: '元代天如禅师为纪念师父建狮子林，湖石堆成狮群。迷宫一样的洞壑绕得人晕头转向，乾隆进去也差点出不来。' },
  { id: 'szs_canglang', name: '沧浪亭的对联', icon: '🖋️', desc: '苏舜钦被贬后买园自嘲，"沧浪之水清兮可以濯吾缨"。园门对联"清风明月本无价，近水远山皆有情"流传千古。' },
  { id: 'szs_ouyuan', name: '耦园住佳耦', icon: '💞', desc: '耦园主人沈秉成与夫人严永华琴瑟和鸣，园中亭台皆成双对。"耦"字本就是并耕之意，全园都是爱情的样子。' },
  { id: 'szs_taihu', name: '太湖石的"瘦漏透皱"', icon: '🪨', desc: '赏石有标准：瘦、漏、透、皱。米芾见奇石要下拜称"石兄"，一块好的太湖石，在古人眼里就是立体的山水。' },
  /* ---- 水巷人家 ---- */
  { id: 'szs_shantang', name: '白居易修的山塘街', icon: '🌉', desc: '白居易任苏州刺史时开凿山塘河，淤泥堆成堤，人称"白公堤"。七里山塘到虎丘，从此成了苏州最温柔的一条街。' },
  { id: 'szs_shuangta', name: '双塔市集的前世今生', icon: '🥬', desc: '这里本是老苏州的菜市场，改造后把"菜场文化"做成了网红。苏州话墙绘与咖啡混搭，烟火气照样旺。' },
  { id: 'szs_fengmen', name: '横街的早市哲学', icon: '🥕', desc: '葑门横街五点半开市，阿婆挑最新鲜的鸡头米、茨菰。苏州人买菜的挑剔，是刻在骨子里的"不时不食"。' },
  { id: 'suzhou_story_ximen', name: '盘门水门的智慧', icon: '🌉', desc: '水门闸口可放可断，既通船又御敌。2500年前的水城设计，如今仍在使用——"活着的古城规划"。' },
  { id: 'suzhou_story_tangmian', name: '头汤面的执念', icon: '🍜', desc: '面馆五点半开门，老苏州六点前到店才喝得上"头汤"。第二碗起汤就"浑"了，讲究人的倔强。' },
  { id: 'suzhou_story_xietajie', name: '不时不食的"苏州胃"', icon: '🥮', desc: '苏州人吃面要"宽汤硬面重青"，点心讲究"应季而食"。不时不食，就是苏州人摆在桌上的时间表。' },
  { id: 'suzhou_story_shuimo', name: '评弹的"苏州FM"', icon: '🎻', desc: '老苏州早晨泡茶馆听评弹一下午，"书场"就是当年的广播电台。吴语的软糯，被称为"最温柔的中国话"。' },
  { id: 'szs_suzhouhua', name: '苏州话的软糯', icon: '🗣️', desc: '苏州话软糯嗲气，连吵架都像在撒娇。一句"倷好"，尾音上扬，外地人笑称"苏州话是吴语里的甜品"。' },
  /* ---- 缂绣匠魂 ---- */
  { id: 'suzhou_story_shuangmian', name: '双面绣的"两面派"', icon: '🪡', desc: '双面绣正反两面图案一样精美，猫眼两面瞳色不同。绣娘劈线细到放大镜才看得清，"指尖上的奇迹"。' },
  { id: 'szs_jingzhuan', name: '故宫的金砖出自苏州', icon: '🧱', desc: '太和殿铺的"金砖"来自苏州御窑，敲之有声、断之无孔。一块砖要烧一年，运到北京只铺在地上。' },
  { id: 'szs_yuanming', name: '寒山拾得的"和合"', icon: '☯️', desc: '寒山寺供着寒山、拾得两位高僧，"和合二仙"的故事传遍世界。他二人一问一答的宽心话，是劝和最好的药。' },
  { id: 'szs_fengqiao', name: '枫桥夜泊的钟声', icon: '🔔', desc: '张继落第夜泊枫桥写下《枫桥夜泊》，诗里"夜半钟声"后来传去日本，年年除夕苏州人都要敲钟迎新年。' },
  { id: 'szs_xiyuanmao', name: '西园寺的猫住持', icon: '🐈', desc: '西园寺的猫被香客喂得圆滚滚，有的卧在蒲团上打盹，有的守在大殿前"上班"。寺里素面好吃，猫也是风景。' },
  /* ---- 四时风物与节庆 ---- */
  { id: 'szs_zhouzhuang', name: '陈逸飞画活的周庄', icon: '🖼️', desc: '画家陈逸飞画了周庄双桥，取名《故乡的回忆》，让世界认识了这座水乡。一幅油画，把周庄"画"成了名镇。' },
  { id: 'szs_tuisi', name: '退思园的"补过"', icon: '🏡', desc: '任兰生被弹劾回乡建园，取"进思尽忠，退思补过"之意。园子贴水而建，是"贴水园"的代表作。' },
  { id: 'szs_yangcheng', name: '阳澄湖的"洗澡蟹"', icon: '🦀', desc: '正宗阳澄湖大闸蟹产量有限，外地蟹"洗个澡"就身价翻倍。本地人笑称：蟹界水深，认准青背白肚金爪黄毛。' },
  { id: 'szs_shihu_chuanyue', name: '石湖串月', icon: '🌙', desc: '农历八月十八夜，石湖行春桥九孔，月光穿过桥洞在湖面连成串，称"石湖串月"。苏州人的中秋，天上水中两轮月。' },
  { id: 'szs_zhaxian', name: '轧神仙的四月', icon: '🎏', desc: '四月十四苏州人"轧神仙"，传说吕洞宾混在人群里，谁挤到他谁沾仙气。神仙糕、神仙庙会，越轧越闹猛。' },
  { id: 'szs_dingxin', name: '定胜糕与"姑苏台"', icon: '🍥', desc: '传说南宋抗金前百姓送"定胜糕"助威，糕上有"定胜"二字。苏州人乔迁婚嫁都买定胜糕，讨个旗开得胜的彩头。' }
);

/* ================= data/cn/huadong/suzhou/suzhou.js ================= */
/* ============ 苏州（完全版·分册组装） ============
 * 分册：suz_01地点 / suz_02周边 / suz_03趣事。
 * 叙事主线：江南园林 / 水巷人家 / 缂绣丝绸 / 太湖四时。
 */
(function () {
  window.TRAVEL_CITIES = window.TRAVEL_CITIES || [];
  window.TRAVEL_CITIES.push({
    id: 'suzhou',
    name: '苏州',
    country: '中国',
    cc: 'CN',
    province: '江苏',
    flag: '🇨🇳',
    region: '华东',
    hero: '🌉',
    desc: '"上有天堂，下有苏杭"：拙政园的移步换景，平江路的评弹吴语，一碗苏式汤面浇头讲究，园林之城把精致刻进了骨子里。',
    travel: [{ name: '高铁', icon: '🚄', cost: 380 }, { name: '飞机', icon: '✈️', cost: 750 }],
    visa: null,
    spots: (window.SUZ_SPOTS = window.SUZ_SPOTS || []),
    souvenirs: (window.SUZ_GIFTS = window.SUZ_GIFTS || []),
    stories: (window.SUZ_STORIES = window.SUZ_STORIES || []),
  });
})();

/* ================= data/cn/huadong/taian/ta_01_spots.js ================= */
/* 泰安 分册01：景点圣地（登山朝圣线+岱庙古建+山脚胜迹） */
window.TA_SPOTS = window.TA_SPOTS || [];
window.TA_SPOTS.push(
  { id: 'taian_taishan', name: '泰山', icon: '⛰️', price: 115, desc: '五岳之首，"会当凌绝顶，一览众山小"。6660级台阶从红门到玉皇顶，夜爬看日出是经典玩法。' },
  { id: 'taian_daimiao', name: '岱庙', icon: '🛕', price: 30, desc: '历代帝王封禅泰山前祭拜的行宫，与故宫齐名的三大宫殿式建筑群。汉柏唐槐千年犹在。' },
  { id: 'taian_riguang', name: '玉皇顶日出', icon: '🌄', price: 0, desc: '凌晨四点山顶挤满军大衣，云海之上金光乍现。"泰山日出"是中国人的一生心愿清单。' },
  { id: 'taian_shibapan', name: '十八盘·南天门', icon: '🧱', price: 0, desc: '最陡处坡度70度的"天梯"，1600级石阶直上南天门。爬完腿抖三天，"过了十八盘，天上一重天"。' },
  { id: 'taian_houshiwu', name: '后石坞·桃花峪', icon: '🌲', price: 0, desc: '泰山"幽区"，古松林立人少景美。天烛峰路线是户外党最爱，"泰山的前世"。' },
  { id: 'taian_wenquan', name: '泰山温泉城', icon: '♨️', price: 128, desc: '下山后的犒劳，硫磺泉泡到通体舒泰。"爬山泡汤"是泰安周末的标准流程。' },
  { id: 'taian_fangte', name: '泰安方特欢乐世界', icon: '🎢', price: 280, desc: '泰山脚下的主题乐园，"飞跃极限"球幕飞车。带孩子家庭的缓冲站，刺激项目不少。' },
  { id: 'tap_hongmen', name: '红门宫', icon: '🏮', price: 0, desc: '红门晓日是泰山古八景之一，登山者大多从这道山门起步。检票而入即是天路，古柏夹道石坊相迎。' },
  { id: 'tap_kongzidenglin', name: '孔子登临处', icon: '⛩️', price: 0, desc: '石坊题着“登泰山而小天下”，源自孔子登临之叹。儒家圣人走过的山路成了文脉，天下第一山由此得名。' },
  { id: 'tap_doumugong', name: '斗母宫', icon: '🛕', price: 0, desc: '登泰山中路的小巧古刹，三重院落沿坡升起，供奉斗姆元君。檐角风铃清响，过客歇脚讨一碗热茶。' },
  { id: 'tap_jingshiyu', name: '经石峪', icon: '🪨', price: 0, desc: '山谷石坪刻着半部《金刚经》，字大如斗铺了整整一坡，号称大字鼻祖。夏日溪水漫过经文的画面最出片。' },
  { id: 'tap_zhongtianmen', name: '中天门', icon: '🚠', price: 0, desc: '泰山之半名中天，索道与进山巴士在此换乘。抬头南天门藏在云里，身后是层层远山与来时的路。' },
  { id: 'tap_yunbuqiao', name: '云步桥·五大夫松', icon: '🌉', price: 0, desc: '飞瀑溅雪的断崖横着一座小桥，桥北古松下立着“五大夫”石碑。秦始皇避雨封松的典故，就藏在这虬枝里。' },
  { id: 'tap_tianjie', name: '天街', icon: '🛍️', price: 0, desc: '南天门上依崖而生的青石板街，海拔一千四百米。店铺卖军大衣姜汤和煎饼，云雾时常漫过屋檐。' },
  { id: 'tap_bixiaci', name: '碧霞祠', icon: '🏯', price: 0, desc: '供奉泰山奶奶碧霞元君的金顶古观，明代大殿铜瓦鎏金。登山香客进香叩首，山顶最热闹处就在此处。' },
  { id: 'tap_riguanfeng', name: '日观峰·拱北石', icon: '🌅', price: 0, desc: '泰山观日出最正统的位置，拱北石探向云海。凌晨四点人已站满岩台，红日从云隙之间轰然跃出。' },
  { id: 'tap_wuzibei', name: '无字碑', icon: '🪦', price: 0, desc: '玉皇顶旁的汉代石表，通体无字任人猜想。有人说是汉武帝立石告天，碑上的沉默比铭文更有重量。' },
  { id: 'tap_wuyueduzun', name: '五岳独尊石刻', icon: '🗿', price: 0, desc: '光绪年间镌就的四个大字，是泰山最硬的签名。无数人排着长队与它合影，把“独尊”二字收进行囊。' },
  { id: 'tap_jiqitaiming', name: '大观峰·纪泰山铭', icon: '📜', price: 0, desc: '唐玄宗封禅后亲书《纪泰山铭》，刻满千丈崖壁，字字描金。远望如一卷圣旨摊开在青岩之上。' },
  { id: 'tap_tianzhufeng', name: '天烛峰', icon: '🎇', price: 0, desc: '泰山东麓群峰如烛，直插青天，是看日落与星空的秘境。山崖下就是封禅大典的露天实景剧场。' },
  { id: 'tap_dongyudao', name: '东御道', icon: '🥾', price: 0, desc: '汉武帝东封泰山走过的古御道，沿溪谷曲折上山。石板被岁月磨得发亮，路旁还躺着宋代的石桥残基。' },
  { id: 'tap_heilongtan', name: '黑龙潭', icon: '🌊', price: 0, desc: '泰山西溪百丈崖下的一汪碧潭，瀑布三叠垂落。传说潭中栖龙，水色墨绿深不见底，掬一捧沁凉入骨。' },
  { id: 'tap_daizongfang', name: '岱宗坊', icon: '⛩️', price: 0, desc: '登泰古道的起点石坊，是山与城的界碑。旧时官民祭山先过此坊，如今抬脚过坊，便算入了泰山。' },
  { id: 'tap_tianwai', name: '天外村广场', icon: '🏙️', price: 0, desc: '山脚“天圆地方”广场，进山巴士与索道的枢纽。十二根盘龙石柱环列，抬头整座泰山迎面压来。' },
  { id: 'tap_puzhaosi', name: '普照寺', icon: '🙏', price: 0, desc: '泰山南麓的幽静古寺，筛月亭下六朝松筛一地碎光。冯玉祥曾隐居读书，山门钟声不疾不徐。' },
  { id: 'tap_wangmuch', name: '王母池', icon: '⛲', price: 0, desc: '泰山脚下千年道观池苑，传为王母梳妆之处。泉水自岩隙涌出，古树虬蟠，暑天入园暑气顿消。' },
  { id: 'tap_tiankuangdian', name: '岱庙·天贶殿', icon: '🏛️', price: 0, desc: '岱庙主殿与故宫太和殿齐名，北宋大木作气度雄浑。殿内《启跸回銮图》画尽宋真宗封禅仪仗。' },
  { id: 'tap_hanbaiyuan', name: '汉柏院', icon: '🌳', price: 0, desc: '汉武帝登封泰山时手植的柏树，两千多岁仍在抽青。枯枝横空如龙爪，“汉柏凌寒”位列岱庙古树之首。' }
);

/* ================= data/cn/huadong/taian/ta_02_gifts.js ================= */
/* 泰安 分册02：特色周边（山珍豆腐/茶叶酒水/封禅文创/住宿体验） */
window.TA_GIFTS = window.TA_GIFTS || [];
window.TA_GIFTS.push(
  { id: 'taian_jianbing', name: '泰山煎饼卷大葱', icon: '🌯', tag: '食', type: '美食', price: 12, desc: '薄脆煎饼卷章丘大葱蘸酱，"山东的豪迈卷"。甜面酱一点，山东人的乡愁。' },
  { id: 'taian_sanmei', name: '泰山三美：白菜豆腐水', icon: '🍲', tag: '食', type: '美食', price: 40, desc: '泰安三美宴听着朴素吃着鲜。山泉水点的豆腐嫩到颤，"皇帝封禅也吃这个"。' },
  { id: 'taian_chishan', name: '赤鳞鱼', icon: '🐟', tag: '食', type: '美食', price: 100, desc: '泰山溪流里的"赤鳞鱼"，古代贡品。油炸酥到连刺都能吃，稀罕着呢。' },
  { id: 'taian_zhuo', name: '肥城桃', icon: '🍑', tag: '食', type: '特产', price: 30, desc: '"中国桃子之乡"肥城的佛桃，一个管饱。香甜多汁，九月的泰安水果顶流。' },
  { id: 'taian_yao', name: '泰山何首乌·四叶参', icon: '🌿', tag: '食', type: '特产', price: 80, desc: '泰山四大名药之首，炖汤滋补。"何首乌"名字就来自泰山人何首乌的传说。' },
  { id: 'taian_shike', name: '泰山石敢当文创', icon: '🪨', tag: '衣', type: '文创', price: 60, desc: '"石敢当"镇宅石的小摆件，泰山石辟邪传千年。文创新形态：钥匙扣与车挂。' },
  { id: 'taian_bi', name: '泰山玉·五岳独尊文创', icon: '💚', tag: '衣', type: '文创', price: 120, desc: '泰山玉手串温润墨绿。"五岳独尊"石刻冰箱贴，登山打卡的"官方纪念"。' },
  { id: 'taian_shouzhang', name: '登山杖与军大衣', icon: '🦯', tag: '衣', type: '服饰', price: 30, desc: '夜爬标配：竹杖5元、军大衣租30元。山顶"军大衣海洋"是泰安冬季名场面。' },
  { id: 'taian_yepa', name: '夜爬泰山', icon: '🌙', tag: '玩', type: '体验', price: 115, desc: '晚上十点从红门出发，凌晨登顶等日出。手电筒长龙蜿蜒如星河，"体力与意志的成人礼"。' },
  { id: 'taian_suo', name: '中天门索道·桃花峪索道', icon: '🚡', tag: '行', type: '体验', price: 100, desc: '体力不够索道来凑，十分钟直达月观峰。缆车里看"十八盘如天梯倒挂"。' },
  { id: 'taian_fengshan', name: '封禅大典实景演出', icon: '🎭', tag: '玩', type: '体验', price: 198, desc: '山体为幕的实景演出，重现帝王封禅。灯光洒在真实的泰山岩壁上，气势逼人。' },
  { id: 'taian_minsu', name: '红门民宿', icon: '🏨', tag: '住', type: '住宿', price: 200, desc: '红门登山口的老院民宿，老板帮你规划夜爬路线。存行李、寄明信片，服务贴心。' },
  { id: 'tag_doufuyan', name: '泰山豆腐宴', icon: '🍲', tag: '食', type: '美食', price: 68, desc: '一桌豆子能翻出百种花样，卤水豆腐雕出芙蓉与麒麟。宴席相传源自帝王封禅的斋戒，山泉水点的豆腐嫩滑不散。' },
  { id: 'tag_huoshao', name: '泰山驴油火烧', icon: '🫓', tag: '食', type: '美食', price: 10, desc: '驴油起酥的炭火烤饼，层层掉渣满口咸香。刚出炉烫得嘶哈也要趁热咬，泰安街头最朴素的满足。' },
  { id: 'tag_doufurufen', name: '泰山豆腐乳', icon: '🫙', tag: '食', type: '特产', price: 28, desc: '泰安山水养的豆腐，入缸发酵成玫红腐乳。咸鲜绵密配馒头稀饭，一瓶就能吃出家乡味。' },
  { id: 'tag_banli', name: '泰山板栗', icon: '🌰', tag: '食', type: '特产', price: 25, desc: '泰山板栗个小壳薄，剥开是糯甜的栗仁。糖炒的油亮滚烫，是泰安秋天街头的香气密码。' },
  { id: 'tag_nvercha', name: '泰山女儿茶', icon: '🍵', tag: '食', type: '饮品', price: 88, desc: '山泉灌溉的嫩芽，泡开汤色碧绿带着兰花香。相传此茶为山中女儿手采，名字里藏着泰山的温柔。' },
  { id: 'tag_taishanyuan', name: '泰山原浆啤酒', icon: '🍺', tag: '食', type: '饮品', price: 25, desc: '保质期只有几天的新鲜啤酒，不过滤保留活酵母。本地人撸串必配，泡沫里能喝到泰山泉水的清冽。' },
  { id: 'tag_yudie', name: '封禅玉牒书签', icon: '📖', tag: '玩', type: '文创', price: 58, desc: '仿封禅玉牒打造的黄铜书签，刻着篆字与云纹。古人祭天告地的信物，如今夹在书页间镇住一页山河。' },
  { id: 'tag_bihua', name: '天贶殿壁画冰箱贴', icon: '🧲', tag: '玩', type: '文创', price: 35, desc: '把天贶殿《启跸回銮图》微缩成金属冰箱贴。帝王仪仗旌旗猎猎，厨房门一开就是千年前封禅的排场。' },
  { id: 'tag_tuoben', name: '纪泰山铭拓片卷轴', icon: '🖼️', tag: '玩', type: '文创', price: 150, desc: '唐玄宗亲书《纪泰山铭》的拓印装裱成轴，金钩铁画压在宣纸上。摊开来便见盛唐气象，书房里最提气的一卷。' },
  { id: 'tag_xiangnang', name: '汉柏柏籽香囊', icon: '🪔', tag: '闻', type: '文创', price: 45, desc: '用岱庙汉柏的柏籽柏叶晒干入囊，清苦的松柏香能安神助眠。两千岁古树的气息装进小锦袋，贴身佩着。' },
  { id: 'tag_tiaoshan', name: '挑山工木版画', icon: '🧗', tag: '玩', type: '文创', price: 90, desc: '木版套色印出挑山工的身影，肩上一根扁担走“之”字。老手艺人一刀一刀刻的，是泰山人压不弯的脊梁。' },
  { id: 'tag_piying', name: '泰山皮影人偶', icon: '🎎', tag: '玩', type: '文创', price: 120, desc: '牛皮雕的泰山皮影人偶，染得眉眼鲜活。泰山皮影以“十不闲”绝技出名，一个人就能唱整台大戏。' },
  { id: 'tag_gaizhang', name: '封禅登山盖章护照', icon: '📔', tag: '玩', type: '文创', price: 45, desc: '从红门到玉皇顶一路打卡盖章的登山护照。每处站点一枚风景章，集齐便是一卷自己的泰山图。' },
  { id: 'tag_wuyueyi', name: '五岳独尊印花T恤', icon: '👕', tag: '衣', type: '服饰', price: 79, desc: '“五岳独尊”四字印上纯棉T恤，攀上山顶那天穿正应景。泰山给的底气，穿在身上走哪都硬气。' },
  { id: 'tag_hanfu', name: '岱庙汉服写真', icon: '👘', tag: '衣', type: '服饰', price: 99, desc: '租一身宋制汉服逛岱庙，天贶殿前拍一组古风照。朱墙汉柏为幕，恍然回到帝王封禅的年代。' },
  { id: 'tag_shanding', name: '天街山顶宾馆', icon: '🛏️', tag: '住', type: '住宿', price: 320, desc: '天街旁的高山宾馆，推开窗就是云海。夜里看银河白天等日出，把“会当凌绝顶”睡成现实。' },
  { id: 'tag_moyu', name: '泰山墨玉刻字印章', icon: '🖋️', tag: '玩', type: '文创', price: 130, desc: '泰山墨玉润如黛，可刻“五岳独尊”或自己的名字。蘸上朱砂印下去，一方属于你的泰山凭证。' },
  { id: 'tag_fuqihong', name: '碧霞祠祈福红带', icon: '🎀', tag: '游', type: '体验', price: 15, desc: '在碧霞祠请一条红绸带，写上心愿系上山顶。风过处千万条红带翻飞，泰山替众生守着念想。' }
);

/* ================= data/cn/huadong/taian/ta_03_stories.js ================= */
/* 泰安 分册03：奇闻趣事（封禅历史/民间传说/山民风俗/登山攻略） */
window.TA_STORIES = window.TA_STORIES || [];
window.TA_STORIES.push(
  { id: 'taian_story_fengshan', name: '为什么皇帝都爱泰山', icon: '👑', desc: '秦皇汉武唐宗宋祖都来封禅，"受命于天"的认证仪式。泰山是"直通帝座"的天堂，石刻两千多处。' },
  { id: 'taian_story_yepa', name: '夜爬大军的"星河"', icon: '🌌', desc: '凌晨的泰山石阶上全是手电光点，像一条星河。素不相识的爬友互相喊"加油"，到顶就成战友。' },
  { id: 'taian_story_gandayi', name: '山顶军大衣经济学', icon: '🧥', desc: '山顶温度比山下低10度，军大衣租赁成产业。披绿大衣看日出，是几代中国人的共同记忆。' },
  { id: 'taian_story_shigandang', name: '石敢当的降妖传说', icon: '🪨', desc: '泰山石敢当能降妖除魔，全国宅院立石以求平安。一块石头的"全民信仰"从泰山出发。' },
  { id: 'taian_story_yi', name: '挑山工的"慢哲学"', icon: '🧗', desc: '泰山挑山工肩挑百斤走"之"字，走得慢却总先到。冯骥才的文章让这种精神全国闻名。' },
  { id: 'taian_story_yunhai', name: '"云海玉盘"奇观', icon: '☁️', desc: '夏季雨后泰山云海如白玉盘铺满山谷。老人说："看云海要靠缘分，缘分是凌晨四点起床。"' },
  { id: 'tas_fengshanli', name: '封禅的礼数', icon: '🛐', desc: '登泰山筑圆坛祭天叫封，到山脚小丘辟土祭地叫禅。帝王须先斋戒沐浴，再埋玉牒告天，整套仪式才算礼成。' },
  { id: 'tas_qinshihuang', name: '秦始皇遇雨封松', icon: '🌧️', desc: '秦始皇封禅下山遇暴雨，慌忙躲进一棵松树下避雨。回朝念它护驾有功，就封这棵树做了“五大夫”官。' },
  { id: 'tas_hanwudi', name: '汉武帝的无字碑', icon: '🗿', desc: '汉武帝八次登封泰山，却在极顶立下一块无字石碑。有人赞他功高不居，有人猜碑里藏着玉牒，千年没有定论。' },
  { id: 'tas_songzhenzong', name: '宋真宗的天书', icon: '🌠', desc: '为了凑足封禅的理由，宋真宗编出“天书”降世，把黄帛挂上树梢当祥瑞。一场大典耗掉半座国库，也成了封禅绝唱。' },
  { id: 'tas_tangxuanzong', name: '唐玄宗金书摩崖', icon: '📜', desc: '开元盛世里玄宗登封泰山，亲笔写下《纪泰山铭》刻满崖壁，字上涂金。千年风雨洗过，那抹金色仍是山间最亮的光。' },
  { id: 'tas_bixiayuanjun', name: '泰山奶奶的心事', icon: '👵', desc: '碧霞元君在泰山人心里的分量赛过帝王，香客都唤她一声“老奶奶”。求子、问平安、盼丰收，山顶香火燃着百姓心事。' },
  { id: 'tas_kongzi', name: '孔子登泰山', icon: '📚', desc: '相传孔子登上泰山便觉得天下变小，从此泰山成了儒家的精神高地。后世文人争相登岱题诗，都想在圣人脚印旁留名。' },
  { id: 'tas_youyan', name: '有眼不识泰山', icon: '🧐', desc: '传说鲁班有位徒弟名叫泰山，手巧却被师父误会赶走。多年后鲁班见到精巧竹器才追悔，那句成语从此传了下来。' },
  { id: 'tas_taianming', name: '泰安得名的由来', icon: '🏮', desc: '金代在此设军取名泰安，意为“泰山安则四海皆安”。一座城因为一座山得名，也把“平安”写进了自己的名字。' },
  { id: 'tas_hanbo', name: '汉柏两千岁', icon: '🌳', desc: '汉武帝登封泰山时亲手种下的柏树，如今两千多岁还在发芽。树干拧得像麻绳，岱庙人叫它汉柏连理，是庙里最老的住客。' },
  { id: 'tas_wangmuch', name: '王母池的仙气', icon: '⛲', desc: '王母池传说是西王母梳洗的地方，古时道士在池畔炼丹修真。池水冬暖夏凉，崖壁满是题刻，老泰安都信这里沾着仙气。' },
  { id: 'tas_nvercha', name: '女儿茶的传说', icon: '🍵', desc: '相传古时山下一对父女相依为命，女儿采泰山嫩芽煮茶替父亲治病，茶香飘满山谷。后人感念孝心，把这茶唤作女儿茶。' },
  { id: 'tas_doufuyan', name: '豆腐宴的来历', icon: '🍲', desc: '传说帝王封禅前要斋戒净身，御厨见不得荤腥，只好把豆腐做出百般花样。手艺流进民间，成了泰安宴席的看家本事。' },
  { id: 'tas_chilin', name: '贡品赤鳞鱼', icon: '🐟', desc: '赤鳞鱼只活在山涧冷泉里，离水片刻便咽气，古人当它是仙品。历代都是朝廷指名要的贡鱼，寻常人家难得一见。' },
  { id: 'tas_piying', name: '泰山皮影十不闲', icon: '🎭', desc: '泰山皮影讲究“十不闲”：一个人又操影人又唱戏又敲锣鼓，手脚嘴全不停。范家班传了数代，老手艺如今进了非遗名录。' },
  { id: 'tas_richu', name: '夜爬看日出时辰表', icon: '⏰', desc: '夜爬泰山讲究掐着点走：夏天约凌晨三点半登顶，冬春可稍晚。日观峰东侧最开阔，云海日出同框还得看几分运气。' },
  { id: 'tas_simaqian', name: '重于泰山', icon: '🖊️', desc: '司马迁身受大辱仍写下“人固有一死，或重于泰山，或轻于鸿毛”。从此泰山成了一杆秤，称量中国人一生的分量。' },
  { id: 'tas_shijing', name: '封禅大典的山体舞台', icon: '🎆', desc: '天烛峰的山崖是天然幕布，声光电把秦皇汉武的封禅故事演在石壁上。水幕升起那刻，观众仿佛真站在大典现场。' }
);

