/* ================= data/cn/huadong/yangzhou/yz_01_spots.js ================= */
/* 扬州 分册01：景点圣地（湖山园林/盐商宅邸/运河古迹/博物馆群） */
window.YZ_SPOTS = window.YZ_SPOTS || [];
window.YZ_SPOTS.push(
  /* ---- 湖山与园林（沿用原条目） ---- */
  { id: 'yangzhou_shouxihu', name: '瘦西湖', icon: '🌸', price: 100, desc: '"两堤花柳全依水，一路楼台直到山"。五亭桥像莲花绽放，二十四桥"玉人吹箫"，春天柳絮如烟。' },
  { id: 'yangzhou_geru', name: '个园', icon: '🎍', price: 45, desc: '以竹得名的盐商园林，四季假山一园看尽春夏秋冬。宣石冬山"积雪"效果，江南园林的独一份。' },
  { id: 'yangzhou_heyuan', name: '何园', icon: '🏛️', price: 40, desc: '"晚清第一园"，1500米复道回廊立体交通。中西合璧的百叶窗与壁炉，盐商的开放气派。' },
  { id: 'yzp_xiaopangu', name: '小盘谷', icon: '🌿', price: 25, desc: '隐在巷子里的清代小园，假山逼仄却堆出千岩万壑。前花厅后水阁，方寸之间藏着扬州园林的精气神。' },
  { id: 'yzp_erming', name: '二分明月楼', icon: '🌙', price: 15, desc: '小园取名自天下三分明月夜，二层楼台最宜望月。院里月亮门照壁处处圆圆，盐商把扬州月色砌进了墙里。' },
  /* ---- 老城街巷与早茶（沿用原条目） ---- */
  { id: 'yangzhou_dongguan', name: '东关街', icon: '🏮', price: 0, desc: '千年古运河边的商业老街，谢馥春香粉老铺在此。夜灯笼亮起，"春风十里扬州路"的现实版。' },
  { id: 'yangzhou_zaocha', name: '冶春茶社早茶', icon: '🍵', price: 60, desc: '"早上皮包水"，扬州早茶与广式并称双绝。冶春临水而坐，蒸笼白汽里全是仪式感。' },
  { id: 'yzp_pishijie', name: '皮市街', icon: '🎨', price: 0, desc: '明清曾卖皮货的老街，如今书店咖啡店与手作铺挤满巷子。墙上涂鸦新潮，游客慢悠悠逛出扬州新文艺。' },
  /* ---- 新增：盐商宅邸与名人故居 ---- */
  { id: 'yzp_wangshi', name: '汪氏小苑', icon: '🏮', price: 35, desc: '藏在深巷的盐商大宅，三路三进的木雕砖雕精巧。后花园假山贴水，比个园更安静，处处是扬州盐商的讲究。' },
  { id: 'yzp_lushi', name: '卢氏盐商住宅', icon: '🏛️', price: 30, desc: '晚清盐商卢绍绪的豪宅，百间楼屋雕梁画栋。如今夜里还有盐商宴与古琴，吃顿饭像穿越回盐业盛世。' },
  { id: 'yzp_zhuziqing', name: '朱自清故居', icon: '📖', price: 0, desc: '安乐巷深处的三进老宅，朱自清在此度过少年时光。青砖小院安静朴素，站在窗前想他笔下的背影与荷塘。' },
  { id: 'yzp_shikefa', name: '史可法纪念馆', icon: '🗡️', price: 20, desc: '梅花岭下纪念明末督师史可法，衣冠冢与祠堂肃穆。兵临城下不降，扬州人记他三百年，每年梅花开满岭。' },
  /* ---- 新增：运河与古迹 ---- */
  { id: 'yzp_guazhou', name: '瓜洲古渡', icon: '⛴️', price: 0, desc: '春风又绿江南岸的瓜洲渡口，汴水与长江在此相望。古渡石阶长满青苔，杜十娘的故事沉在江水里。' },
  { id: 'yzp_sanwan', name: '运河三湾风景区', icon: '🌊', price: 0, desc: '大运河在这儿绕了三道湾才蓄住水势，湿地芦苇连天。栈道穿行水杉林，斜阳把整条河染成金色绸带。' },
  { id: 'yzp_puhading', name: '普哈丁园', icon: '🕌', price: 15, desc: '古运河边安葬着阿拉伯先贤普哈丁，宋代墓亭古朴素雅。回回先贤长眠扬州千年，运河曾带来世界的客商。' },
  { id: 'yzp_zhuyuwan', name: '茱萸湾', icon: '🦒', price: 45, desc: '古运河弯成一片半岛，茱萸满坡还有动物乐园。春天芍药开成海，鹿园长颈鹿探头，扬州人春游首选地。' },
  { id: 'yzp_suichangdi', name: '隋炀帝墓遗址', icon: '⚱️', price: 20, desc: '2013年曹庄挖出隋炀帝真墓，墓志刻着他的年号。一代暴君与他的江都梦，最后埋在扬州城边的麦田下。' },
  { id: 'yzp_tianning', name: '天宁寺·御码头', icon: '⛩️', price: 20, desc: '乾隆南巡驻跸过的天宁寺，门前石码头直通瘦西湖。僧人已散钟声未远，清代曾在此刻成整套《全唐诗》。' },
  /* ---- 新增：文博与遗址 ---- */
  { id: 'yzp_hanling', name: '汉广陵王墓', icon: '🏺', price: 30, desc: '西汉广陵王刘胥的黄肠题凑大墓，整木棺椁结构惊人。楠木地宫保存完好，看两千年前王侯的下葬排场。' },
  { id: 'yzp_shuangbo', name: '扬州双博馆', icon: '📜', price: 0, desc: '双博馆藏着扬州两千年文物，最亮是雕版印刷展厅。看中国雕版从隋唐一路刻到民国，还能亲手刷印一页带走。' },
  { id: 'yzp_tangcheng', name: '唐城遗址', icon: '🏯', price: 25, desc: '蜀冈上残存的唐代城墙，夯土高台望得见整座扬州。当年十里长街商铺如云，如今站在城头想盛唐的气象。' },
  { id: 'yzp_songjiacheng', name: '宋夹城', icon: '🏹', price: 0, desc: '南宋抗金的夹城遗址，如今围成体育休闲公园。城门复建，护城河绕一圈，跑步遛弯都能撞见宋代城墙。' },
  /* ---- 沿用原条目：运河与禅寺 ---- */
  { id: 'yangzhou_dayunhe', name: '中国大运河博物馆', icon: '🚢', price: 0, desc: '"运河上的舟楫"巨型船模震撼，沉浸式数字展。扬州是"运河长子"，一条河读懂半部中国经济史。' },
  { id: 'yangzhou_daming', name: '大明寺·鉴真纪念堂', icon: '🛕', price: 45, desc: '鉴真东渡日本的出发地，栖灵塔可登高。日本唐招提寺的"兄弟寺"情谊，文化输出的千年佳话。' },
  /* ---- 新增：禅寺道观 ---- */
  { id: 'yzp_qionghua', name: '琼花观', icon: '💮', price: 15, desc: '欧阳修写过无双亭的琼花观，道观里古树还在。传说隋炀帝为看琼花开凿运河，花开如雪传说比花更长久。' },
  { id: 'yzp_gaomin', name: '高旻寺', icon: '🛕', price: 20, desc: '三汊河口的千年禅寺，塔影落在运河波光里。来果老和尚中兴的道场，晨钟暮鼓仍守着大江边这一方清净。' },
  { id: 'yzp_baguai', name: '扬州八怪纪念馆', icon: '🖌️', price: 25, desc: '金农曾住过的西方寺，如今挂满八怪的画。郑板桥的竹、金农的梅，怪得各有章法，扬州卖画养出艺术奇观。' },
  { id: 'yzp_wenchangge', name: '文昌阁·四望亭', icon: '🗼', price: 0, desc: '汶河路中央的明代文昌阁巍然独立，四望亭在街心对望。古时文人祭拜魁星，如今车流绕着两座地标打转。' }
);

/* ================= data/cn/huadong/yangzhou/yz_02_gifts.js ================= */
/* 扬州 分册02：特色周边（淮扬味道/早茶点心/非遗文创/体验住宿） */
window.YZ_GIFTS = window.YZ_GIFTS || [];
window.YZ_GIFTS.push(
  /* ---- 淮扬名菜（沿用原条目） ---- */
  { id: 'yangzhou_baozi', name: '蟹黄汤包·三丁包', icon: '🥟', tag: '食', type: '美食', price: 25, desc: '"三丁"是鸡丁、肉丁、笋丁，鲜香三重奏。蟹黄汤包"轻轻提、慢慢移"，先开窗后喝汤。' },
  { id: 'yangzhou_chaofan', name: '扬州炒饭', icon: '🍚', tag: '食', type: '美食', price: 30, desc: '发源地的正宗版本：火腿、海参、虾仁、青豆。粒粒分明"金裹银"，全国的扬州炒饭都得来认祖。' },
  { id: 'yangzhou_jiangcai', name: '扬州酱菜·牛皮糖', icon: '🥒', tag: '食', type: '特产', price: 30, desc: '三和四美酱菜脆爽百年，牛皮糖软韧拉丝。老字号伴手礼，配粥下茶都好。' },
  { id: 'yangzhou_xie', name: '高邮咸鸭蛋', icon: '🥚', tag: '食', type: '特产', price: 40, desc: '汪曾祺笔下的家乡味，"筷子头一扎，红油就冒出来"。蛋黄流油起沙，配白粥一绝。' },
  { id: 'yangzhou_xiehua', name: '谢馥春香粉', icon: '🌸', tag: '衣', type: '文创', price: 60, desc: '1915年巴拿马万国博览会金奖的"鸭蛋粉"。古典鹅蛋盒包装，"东方香粉"的百年芳华。' },
  { id: 'yangzhou_diao', name: '扬州漆器·玉雕', icon: '🖼️', tag: '衣', type: '文创', price: 200, desc: '点螺漆器在光下变幻，扬州玉雕"琮璧之巧"。"扬州工"是工艺界的金字招牌。' },
  { id: 'yangzhou_wood', name: '雕版印刷体验', icon: '🖨️', tag: '玩', type: '体验', price: 60, desc: '扬州是雕版印刷术的发源地之一。亲手刷印一页《唐诗》，油墨书香，"活着的非遗"。' },
  { id: 'yangzhou_daoqiang', name: '扬州三把刀', icon: '💈', tag: '玩', type: '体验', price: 80, desc: '厨刀、修脚刀、理发刀，扬州人的手艺名片。修脚师傅的手艺是国家级非遗，"足底按摩的祖师爷"。' },
  { id: 'yangzhou_paozao', name: '"晚上水包皮"泡澡', icon: '♨️', tag: '玩', type: '体验', price: 80, desc: '"早上皮包水，晚上水包皮"——泡澡修脚全套。扬州澡堂师傅的手艺，泡完整个人"酥"了。' },
  { id: 'yangzhou_chuan2', name: '古运河夜游', icon: '⛴️', tag: '行', type: '体验', price: 60, desc: '夜游京杭大运河扬州段，两岸灯火与东关古渡。一条河看尽"运河城市"的繁华基因。' },
  { id: 'yangzhou_hanfu', name: '瘦西湖汉服旅拍', icon: '📸', tag: '玩', type: '体验', price: 220, desc: '三月烟雨穿汉服游瘦西湖，二十四桥入镜。"烟花三月"的实景拍摄，出片率爆表。' },
  { id: 'yangzhou_minsu', name: '古城客栈', icon: '🏨', tag: '住', type: '住宿', price: 300, desc: '东关街附近的盐商老宅客栈，天井里养着锦鲤。早晨被隔壁茶社的白汽香唤醒。' },
  /* ---- 新增：淮扬名菜 ---- */
  { id: 'yzg_shizitou', name: '蟹粉狮子头', icon: '🍖', tag: '食', type: '美食', price: 68, desc: '肥瘦相间的肉圆裹进蟹黄蟹肉，砂锅清炖六小时。用勺子轻轻一舀就散开，入口软糯不见肥腻，淮扬菜的功夫全在火候。' },
  { id: 'yzg_dazhugansi', name: '大煮干丝', icon: '🍲', tag: '食', type: '美食', price: 48, desc: '一块白干切出千根细丝，鸡汤火腿丝同煮入味。豆腐丝细如发却根根不断，鲜汤裹着干丝，是扬州宴席上的文雅菜。' },
  { id: 'yzg_tangansi', name: '烫干丝', icon: '🥢', tag: '食', type: '美食', price: 18, desc: '早茶桌上的头道冷盘，干丝开水烫三遍再堆成塔。浇上麻油酱油虾米姜丝，一拌一夹清脆爽口，清晨就鲜到眉毛。' },
  { id: 'yzg_laoe', name: '扬州盐水鹅', icon: '🦢', tag: '食', type: '美食', price: 55, desc: '老鹅卤得金黄透亮，皮脆肉嫩咸鲜入骨。斩一碟配啤酒，鹅掌鹅翅下酒最香，扬州人的餐桌离不开这一味老卤。' },
  { id: 'yzg_shaomai', name: '翡翠烧麦·千层油糕', icon: '🥟', tag: '食', type: '美食', price: 28, desc: '翡翠烧麦皮薄透绿像翡翠，千层油糕层层分明甜润。两样点心上过国宴，是扬州早茶里最考验师傅手法的名角。' },
  /* ---- 新增：早茶与饮品 ---- */
  { id: 'yzg_fuchun', name: '富春茶社早茶', icon: '🍵', tag: '食', type: '美食', price: 75, desc: '老扬州起早赶富春，一笼三丁包配一壶魁龙珠。茶香里烫干丝堆尖，天井中老茶客谈天，皮包水的早晨从这儿开始。' },
  { id: 'yzg_wutinggao', name: '五亭桥文创雪糕', icon: '🍦', tag: '食', type: '美食', price: 22, desc: '瘦西湖五亭桥造型的雪糕，举在桥边拍照刚刚好。茉莉味清香不腻，一支雪糕把扬州的桥与夏都装进嘴里。' },
  { id: 'yzg_lvchun', name: '绿杨春茶', icon: '🍃', tag: '食', type: '饮品', price: 88, desc: '扬州本地产的绿杨春，芽叶细秀香气清幽。玻璃杯里看叶子缓缓舒展，茶汤明亮带豆香，扬州人的下午就靠这一杯。' },
  { id: 'yzg_daxie', name: '高邮湖大闸蟹', icon: '🦀', tag: '食', type: '特产', price: 180, desc: '秋风起时高邮湖蟹正肥，青壳白肚黄满膏腴。蒸熟蘸姜醋慢慢拆，蟹肉鲜甜带着湖水气，是扬州人秋天的仪式感。' },
  /* ---- 新增：非遗文创 ---- */
  { id: 'yzg_jianzhi', name: '扬州剪纸', icon: '✂️', tag: '玩', type: '文创', price: 45, desc: '线条细如游丝的扬州剪纸，花鸟鱼虫栩栩如生。剪纸艺人现场手作，红纸翻飞间剪出瘦西湖的亭台与杨柳。' },
  { id: 'yzg_diaoshu', name: '雕版线装《唐诗》', icon: '📚', tag: '玩', type: '文创', price: 120, desc: '广陵古籍刻印社手工刷印的线装书，宣纸软糯墨香扑鼻。翻开是“烟花三月下扬州”，把千年书卷气捧在手心。' },
  { id: 'yzg_tongcaohua', name: '扬州通草花', icon: '🌺', tag: '玩', type: '文创', price: 65, desc: '通草削成薄片再捏出花瓣，一朵牡丹能乱真。通草花曾是清宫贡品，如今只剩少数匠人还会这门指尖绝艺。' },
  { id: 'yzg_yunhe', name: '大运河文创书签', icon: '🚢', tag: '玩', type: '文创', price: 35, desc: '铜质书签上刻着漕船与帆影，錾出运河上下的浪纹。从北京到杭州两千公里，一条河的故事浓缩在指间金属里。' },
  { id: 'yzg_niupitang', name: '大麒麟阁牛皮糖', icon: '🍬', tag: '食', type: '特产', price: 40, desc: '老字号大麒麟阁的牛皮糖，软糖拉丝裹满芝麻。薄荷味清凉耐嚼，甜而不腻不粘牙，扬州人从小吃到大的零食。' },
  /* ---- 新增：体验与游艺 ---- */
  { id: 'yzg_pinghua', name: '广陵书场评话', icon: '🎭', tag: '玩', type: '体验', price: 60, desc: '沏壶茶坐进广陵书场，醒木一拍全场安静。说书人一人千面，宋江武松从口中活过来，听一折便忘了时辰。' },
  { id: 'yzg_qingqu', name: '扬州清曲茶座', icon: '🎵', tag: '玩', type: '体验', price: 50, desc: '扬州清曲软糯婉转，丝竹声里咿呀唱着旧时月色。艺人身着长衫慢摇檀板，把古城六百年的风月唱给你听。' },
  { id: 'yzg_yaolu', name: '瘦西湖摇橹船', icon: '🛶', tag: '玩', type: '体验', price: 150, desc: '船娘摇橹咿呀穿过虹桥，湖上微风裹着柳絮。一桨一橹荡开水面，看两岸楼台缓缓后退，人在画中游说的就是此刻。' },
  { id: 'yzg_mingchu', name: '淮扬名厨学艺课', icon: '👨‍🍳', tag: '游', type: '体验', price: 260, desc: '跟淮扬菜大师学做狮子头与煮干丝，刀工火候手把手教。自己烧的菜端上桌，尝一口才知好味道全在细节里。' }
);

/* ================= data/cn/huadong/yangzhou/yz_03_stories.js ================= */
/* 扬州 分册03：奇闻趣事（诗篇典故/盐商园林/淮扬风物/市井节俗） */
window.YZ_STORIES = window.YZ_STORIES || [];
window.YZ_STORIES.push(
  /* ---- 沿用原条目：生活与盐商 ---- */
  { id: 'yangzhou_story_pibaoshui', name: '皮包水与水包皮', icon: '♨️', desc: '扬州人的幸福公式：早上吃茶包子（皮包水），晚上泡澡（水包皮）。慢生活的"祖师爷级"代表。' },
  { id: 'yangzhou_story_yanshang', name: '盐商造就的繁华', icon: '💰', desc: '清代两淮盐商聚集扬州，富可敌国。园林、淮扬菜、戏剧都因盐商的"内卷消费"而登峰造极。' },
  { id: 'yangzhou_story_jianzhen', name: '鉴真六次东渡', icon: '🛕', desc: '大明寺鉴真和尚双目失明仍六次东渡日本传戒律。日本唐招提寺至今供奉鉴真坐像，"文化大使"第一人。' },
  { id: 'yangzhou_story_ershi', name: '二十四桥到底有几座', icon: '🌉', desc: '"二十四桥明月夜"引发千年争论：是24座桥还是一座桥名？如今瘦西湖里那座白玉桥就叫"二十四桥"。' },
  { id: 'yangzhou_story_sanba', name: '"腰缠十万贯，骑鹤下扬州"', icon: '🦢', desc: '古人把"下扬州"列为人生三大梦想之一。扬州从唐代的"魔都"地位可见一斑。' },
  { id: 'yangzhou_story_wangzengqi', name: '汪曾祺的故乡味觉', icon: '🥚', desc: '"高邮咸蛋，质细而油多"被写进课文。扬州人饮食自信的底气：连咸鸭蛋都是文学级的。' },
  /* ---- 新增：诗篇典故 ---- */
  { id: 'yzs_yanhua', name: '烟花三月下扬州', icon: '🛶', desc: '李白在黄鹤楼送别孟浩然，一句“烟花三月下扬州”把扬州写进春天。柳色如烟时节，千百年来多少人循着这句诗来赴江南。' },
  { id: 'yzs_shouxihu', name: '瘦西湖名字的由来', icon: '🌸', desc: '清代诗人汪沆一句“故应唤作瘦西湖”，让这湾碧水从此得名。瘦在秀气，湖在风骨，一个瘦字道尽扬州园林的清雅。' },
  { id: 'yzs_guangling', name: '广陵散从此绝矣', icon: '🎻', desc: '嵇康临刑前从容弹完《广陵散》，叹“广陵散于今绝矣”。广陵正是扬州古称，一曲绝响让扬州染上名士悲烈。' },
  { id: 'yzs_pingshan', name: '欧阳修筑平山堂', icon: '🏛️', desc: '欧阳修守扬州时于大明寺侧筑堂，远望江南群峰与堂齐平。他留下“文章太守”的佳话，平山堂成了文人的精神高地。' },
  /* ---- 新增：园林与建筑 ---- */
  { id: 'yzs_geyuan', name: '个园为何叫个园', icon: '🎍', desc: '盐商黄至筠爱竹成癖，取竹叶之形半个“个”字为园名。园中四季假山用石不同，一园之内走过春夏秋冬的光阴。' },
  { id: 'yzs_heyuan', name: '何园的复道回廊', icon: '🏯', desc: '何园主人何芷舠建起一千五百米复道回廊，楼上楼下晴雨皆通。中西合璧的窗棂漏着光，扬州园林的巧思都在廊里。' },
  { id: 'yzs_wuting', name: '五亭桥上的十五洞', icon: '🌉', desc: '瘦西湖五亭桥下有十五个桥洞，月圆之夜每个洞都映出一轮月。传说十五洞能走通天上人间，桥亭相叠若莲花出水。' },
  { id: 'yzs_baita', name: '一夜堆成的白塔', icon: '🗼', desc: '传乾隆游湖叹缺北海白塔，盐商连夜用盐堆成假塔应景，随后速建真塔。真假难辨的手笔，成了扬州盐商的传奇。' },
  /* ---- 新增：人物轶事 ---- */
  { id: 'yzs_shikefa', name: '史可法死守扬州', icon: '🗡️', desc: '清军南下，史可法督师扬州血战不降，城破殉国，衣冠葬于梅花岭。一句“城亡与亡”，让扬州记住了这位硬骨头。' },
  { id: 'yzs_zhuziqing', name: '朱自清的扬州', icon: '📖', desc: '朱自清生于扬州，自称“我是扬州人”。瘦西湖的水、东关街的灯都写进他的散文，清淡文字里全是故乡的旧影。' },
  { id: 'yzs_banqiao', name: '郑板桥卖画扬州', icon: '🖌️', desc: '郑板桥客居扬州以卖画为生，还明码标价写了润格。他把竹兰画得清劲脱俗，市井的扬州反倒养出了一代怪才。' },
  { id: 'yzs_suidi', name: '隋炀帝的江都梦', icon: '⚱️', desc: '隋炀帝三下江都，最终在扬州被缢杀。他开运河、看琼花的传说传了千年，直到2013年考古才确认帝王埋骨之地。' },
  /* ---- 新增：淮扬风物 ---- */
  { id: 'yzs_chaofan', name: '扬州炒饭的来历', icon: '🍚', desc: '隋代尚食直长谢讽记载过“碎金饭”，一粒粒裹蛋如碎金。扬州炒饭由古籍到民间，最终炒成了世界认识扬州的味道。' },
  { id: 'yzs_shizitou', name: '狮子头的大块头', icon: '🍖', desc: '相传隋炀帝下扬州命御厨做四道菜，其中“葵花斩肉”肉圆硕大如狮头。后来文人改名狮子头，粗犷菜竟做得文雅细腻。' },
  { id: 'yzs_xiefuchun', name: '谢馥春的鸭蛋粉', icon: '🌸', desc: '谢馥春是扬州老牌香粉铺，鸭蛋粉曾捧回万国博览会大奖。粉盒做成鸭蛋形，东方脂香悠悠飘了一百多年。' },
  /* ---- 新增：市井书场 ---- */
  { id: 'yzs_pinghua', name: '评话场里的醒木', icon: '🎭', desc: '扬州评话书场里醒木一拍，说书人一人演尽千军万马。王少堂一部《水浒》说红大江南北，市井间处处是听书人。' },
  { id: 'yzs_guazhou', name: '瓜洲渡头的旧事', icon: '⛴️', desc: '古运河入江处的瓜洲，是漕船与商旅的必经渡口。杜十娘怒沉百宝箱的悲剧就发生在这里，潮起潮落淘尽多少故事。' },
  { id: 'yzs_quanshi', name: '扬州诗局刻全唐诗', icon: '📜', desc: '康熙年间扬州设诗局刊刻《全唐诗》，近九百卷大书由雕版匠人一刀一刀刻成。扬州的雕版技艺，因此名动天下。' }
);

/* ================= data/cn/huadong/yangzhou/yangzhou.js ================= */
/* ============ 江苏·扬州（完全版·分册组装） ============
 * 由旧档 data/cn/huadong/yangzhou.js 拆分为册扩容而来。
 * 分册：yz_01地点 / yz_02周边 / yz_03趣事。城市字段沿旧档。
 * 叙事主线：烟花三月 / 运河繁华 / 园林盐商 / 淮扬风物。
 */
(function () {
  window.TRAVEL_CITIES = window.TRAVEL_CITIES || [];
  window.TRAVEL_CITIES.push({
    id: 'yangzhou',
    name: '扬州',
    country: '中国',
    cc: 'CN',
    province: '江苏',
    flag: '🇨🇳',
    region: '华东',
    hero: '🌸',
    desc: '"烟花三月下扬州"：瘦西湖的二十四桥明月夜，早茶 culture 一吃半天，三把刀的技艺，慢城扬州把生活过成了诗。',
    travel: [{ name: '高铁', icon: '🚄', cost: 400 }, { name: '飞机', icon: '✈️', cost: 750 }],
    visa: null,
    spots: (window.YZ_SPOTS = window.YZ_SPOTS || []),
    souvenirs: (window.YZ_GIFTS = window.YZ_GIFTS || []),
    stories: (window.YZ_STORIES = window.YZ_STORIES || []),
  });
})();

/* ================= data/cn/huanan/guangzhou/gz_01_spots.js ================= */
/* 广州 分册01：景点圣地（珠江新城/千年商都/西关老街/岭南园林） */
window.GZ_SPOTS = window.GZ_SPOTS || [];
window.GZ_SPOTS.push(
  /* ---- 珠江与新城（沿用原条目） ---- */
  { id: 'guangzhou_xiaomanyao', name: '广州塔"小蛮腰"', icon: '🗼', price: 150, desc: '600米的纤细腰身是珠江新城最亮的名片。登塔观景或塔顶摩天轮，夜色里整条珠江都在为你打光。' },
  { id: 'guangzhou_shamian', name: '沙面岛', icon: '🏛️', price: 0, desc: '珠江白鹅潭畔的欧式建筑群，领事馆旧址林立。梧桐绿荫下婚纱摄影队一字排开，复古城堡感拉满。' },
  { id: 'gzp_huacheng', name: '花城广场·海心沙', icon: '🌆', price: 0, desc: '广州新中轴的心脏，广州塔与双子塔南北对望。整点音乐喷泉、新年灯光秀，中轴夜景一步一景。' },
  { id: 'gzp_pati', name: '琶醍啤酒文化创意园', icon: '🍺', price: 0, desc: '珠江边的老啤酒厂改造，江景餐吧一字排开。傍晚看日落、入夜吹江风，广州人的夜生活有江水的味道。' },
  { id: 'gzp_taigucang', name: '太古仓码头', icon: '⚓', price: 0, desc: '百年红砖仓库码头改造成文创园，江边长廊散步看货轮。夜里灯光亮起，老码头成了最惬意的江边客厅。' },
  { id: 'gzp_beijinglu', name: '北京路步行街·千年古道', icon: '🏮', price: 0, desc: '玻璃栈道下压着唐宋元明清五朝路面，千年古道原样可见。旁边大佛寺金殿灯火，闹市里藏着一座古刹。' },
  /* ---- 西关与岭南老街（沿用原条目） ---- */
  { id: 'guangzhou_chenjiaci', name: '陈家祠', icon: '🏯', price: 10, desc: '岭南建筑艺术巅峰，砖雕、木雕、灰塑挤满屋脊。每块砖都像一出戏，"百鸟朝凤"图能看上半天。' },
  { id: 'guangzhou_yongqingfang', name: '永庆坊·粤剧博物馆', icon: '🎭', price: 0, desc: '西关骑楼老街改造的文创街区，李小龙祖居就在巷里。粤剧艺术博物馆水榭戏台，金丝戏服亮瞎眼。' },
  { id: 'gzp_shangxiajiu', name: '上下九步行街', icon: '🛍️', price: 0, desc: '骑楼连绵的老商业街，陶陶居、莲香楼的老字号招牌一路排开。西关小姐的胭脂水粉，都曾在这条街上买。' },
  { id: 'gzp_enninglu', name: '恩宁路骑楼街', icon: '🏘️', price: 0, desc: '广州最美骑楼街，铜器铺里叮叮当当。看铜壶师傅敲打，或钻进老巷找一碗濑粉，时间在这里走得很慢。' },
  { id: 'gzp_liwan', name: '荔湾湖·西关大屋', icon: '🪟', price: 0, desc: '趟栊门、满洲窗、青云巷——西关大屋的讲究都在细节里。湖边榕树下听粤曲，老广州的生活原样演出。' },
  { id: 'gzp_dongshan', name: '东山口', icon: '🍂', price: 0, desc: '新河浦的民国小洋楼与红砖老别墅，如今塞满咖啡店与潮牌。"有钱住西关，有势住东山"，广州的文艺新地标。' },
  /* ---- 千年商都与海丝 ---- */
  { id: 'gzp_shisanhang', name: '十三行博物馆', icon: '⚓', price: 0, desc: '清代广州一口通商，十三行商馆区成了世界贸易中心。馆里的外销瓷与通草画，讲着东方之珠的前传。' },
  { id: 'gzp_huangpugang', name: '黄埔古港', icon: '🚢', price: 0, desc: '千年古港，粤海第一关的牌坊立在岸边。清代"哥德堡号"就从这里满载中国货回欧洲。村口姜撞奶一绝。' },
  { id: 'gzp_nanhai', name: '南海神庙·波罗庙', icon: '⛩️', price: 0, desc: '海上丝路的起点神庙，供奉南海神。千年"波罗诞"庙会时万人空巷，庙里的红棉与古碑都是海贸见证。' },
  { id: 'gzp_guangxiao', name: '光孝寺', icon: '🙏', price: 0, desc: '"未有羊城，先有光孝"。六祖慧能在此受戒，菩提树下辨"风动幡动"。千年古刹立在闹市，一进门就安静。' },
  { id: 'gzp_liurong', name: '六榕寺·花塔', icon: '🛕', price: 0, desc: '六榕塔亭亭如花，苏东坡题"六榕"二字。登塔可望老城，寺里的素斋与斋菜馆都是老字号。' },
  { id: 'gzp_shengxin', name: '石室圣心大教堂', icon: '⛪', price: 0, desc: '全球四座全石构哥特教堂之一，双塔尖直插天际。光线穿过彩窗洒满长椅，静坐片刻心就沉下来。' },
  { id: 'gzp_zhenhai', name: '镇海楼·广州博物馆', icon: '🏯', price: 0, desc: '越秀山上的五层红楼，广州城的千年变迁都在这。登楼望木棉与老城，"五岭以南第一楼"名不虚传。' },
  /* ---- 花城与城市 ---- */
  { id: 'guangzhou_yuexiu', name: '越秀公园·五羊雕像', icon: '🐏', price: 0, desc: '五羊石像述着"五羊衔谷"的建城传说，"羊城"得名于此。明代古城墙盘在山间，木棉花开时红遍全山。' },
  { id: 'gzp_zhongshan', name: '中山纪念堂', icon: '🏛️', price: 0, desc: '八角攒尖顶的大礼堂，没有一根柱子挡住视线。堂前木棉参天，广州的会客厅兼着城市名片。' },
  { id: 'gzp_huanghuagang', name: '黄花岗七十二烈士墓园', icon: '🕊️', price: 0, desc: '"浩气长存"的牌坊立在青松之间，孙中山手书。清末的枪声在此点燃，广州的近代史绕不开这座陵园。' },
  { id: 'gzp_yuntai', name: '云台花园', icon: '🌹', price: 0, desc: '白云山脚的欧式花园，玫瑰园与飞瀑四季不歇。春天郁金香、秋天菊展，广州市民拍花首选地。' },
  { id: 'guangzhou_baiyunshan', name: '白云山', icon: '⛰️', price: 5, desc: '"羊城第一秀"，五元门票的天然氧吧。凌晨就有阿伯打着手电登顶看日出，摩星岭上全城尽收眼底。' },
  { id: 'guangzhou_shengbo', name: '广东省博物馆', icon: '🦕', price: 0, desc: '"月光宝盒"造型建筑里藏着千年海贸史。广彩瓷、沉船出水文物，海上丝绸之路的实证都在这。' },
  /* ---- 岭南园林与古镇 ---- */
  { id: 'gzp_yuyinshanfang', name: '余荫山房', icon: '🏯', price: 18, desc: '岭南四大名园之一，占地不大却移步换景。虹桥印月、深柳堂，小小一方园子藏着清代文人的巧思。' },
  { id: 'gzp_baomo', name: '宝墨园', icon: '🏛️', price: 0, desc: '番禺的岭南园林，陶塑巨壁与锦鲤池相映成趣。夏天荷花满塘，园林里的水乡版画展值得一看。' },
  { id: 'gzp_shawan', name: '沙湾古镇', icon: '🏘️', price: 0, desc: '岭南古镇，砖雕灰塑满墙。姜埋奶的发源地，鱼灯与广东音乐都从这里走出。' },
  { id: 'gzp_changlong', name: '长隆野生动物世界', icon: '🐼', price: 300, desc: '坐小火车穿行自驾区，长颈鹿从车窗边走过。全球唯一的熊猫三胞胎在此，考拉、白虎各占山头。' }
);

/* ================= data/cn/huanan/guangzhou/gz_02_gifts.js ================= */
/* 广州 分册02：特色周边（叹茶早味/广府靓汤/岭南手信/花城体验） */
window.GZ_GIFTS = window.GZ_GIFTS || [];
window.GZ_GIFTS.push(
  /* ---- 叹茶与早点（沿用原条目） ---- */
  { id: 'guangzhou_zaocha', name: '早茶一盅两件', icon: '🥟', tag: '食', type: '美食', price: 60, desc: '虾饺、凤爪、叉烧包推车流转，一壶普洱坐半天。"叹早茶"叹的是从容，广州人的人情往来都在茶桌上。' },
  { id: 'guangzhou_changfen', name: '布拉肠粉', icon: '🌯', tag: '食', type: '美食', price: 10, desc: '米浆现拉现蒸，布一样滑嫩。浇豉油、撒芝麻，牛肉蛋馅随心搭，五块钱解锁广州人的清晨。' },
  { id: 'guangzhou_yuntunmian', name: '云吞面', icon: '🍜', tag: '食', type: '美食', price: 15, desc: '竹升压出的银丝面脆弹，云吞藏在碗底。大地鱼汤底鲜到掉眉，先汤后面再云吞，顺序都不能乱。' },
  { id: 'guangzhou_shuangpinai', name: '双皮奶', icon: '🍮', tag: '食', type: '美食', price: 12, desc: '水牛奶两次结皮，奶皮厚得能托起汤匙。加红豆莲子双拼，甜品店的镇店之宝。' },
  { id: 'gzg_tingzaizhou', name: '艇仔粥', icon: '🍲', tag: '食', type: '美食', price: 15, desc: '疍家人在艇上现煮的粥，鱼片虾仁花生浮满一碗。荔湾湖边的艇仔粥，吃的是水上人家的鲜。' },
  { id: 'gzg_jidizhou', name: '及第粥', icon: '🥣', tag: '食', type: '美食', price: 12, desc: '猪肝猪腰肉丸滚进粥里，粥绵料足。传说书生考前喝此粥高中状元，"及第粥"图的就是好彩头。' },
  { id: 'gzg_ganchaonihe', name: '干炒牛河', icon: '🍜', tag: '食', type: '美食', price: 25, desc: '镬气十足的炒河粉，牛肉滑嫩、芽菜爽口。一条河粉要炒得不碎不油，最见大排档师傅的功夫。' },
  { id: 'gzg_baozai', name: '煲仔饭', icon: '🍚', tag: '食', type: '美食', price: 30, desc: '砂锅煲出的米饭粒粒分明，腊味油香渗进饭里。锅巴金黄焦脆，淋一圈豉油翻拌，香到隔壁桌都看过来。' },
  { id: 'gzg_zezebao', name: '啫啫黄鳝煲', icon: '🥘', tag: '食', type: '美食', price: 60, desc: '砂锅烧到极热猛火啫熟黄鳝，上桌还在"啫啫"作响。酱香入味，揭开盖的一瞬锅气扑面。' },
  { id: 'gzg_jiangzhuangnai', name: '沙湾姜撞奶', icon: '🍮', tag: '食', type: '美食', price: 12, desc: '水牛奶撞入姜汁，凝成布丁般嫩滑。姜的辛香撞上奶的甜润，沙湾古镇的一口招牌。' },
  { id: 'gzg_yangzhiganlu', name: '杨枝甘露', icon: '🥭', tag: '食', type: '美食', price: 25, desc: '芒果西柚椰浆加西米，酸甜清润。港式甜品的广府远亲，广州人夏天的一碗清凉。' },
  { id: 'gzg_ningmengcha', name: '广式冻柠茶', icon: '🍹', tag: '食', type: '饮品', price: 10, desc: '几片柠檬在冰红茶里捣出香气，酸爽回甘。广州人的"续命水"排行第二，仅次于凉茶。' },
  { id: 'guangzhou_liangcha', name: '廿四味凉茶', icon: '🍵', tag: '食', type: '饮品', price: 5, desc: '苦到怀疑人生的中药茶饮，广州人却当"续命水"。喉咙一痛就来一杯，喝完老板递一颗话梅救场。' },
  { id: 'guangzhou_liaotang', name: '老火靓汤', icon: '🍲', tag: '食', type: '美食', price: 25, desc: '三煲四炖足足六小时，木棉花煲鲫鱼、五指毛桃炖鸡。广州妈妈的执念：宁可食无菜，不可饭无汤。' },
  /* ---- 广府食材与手信（沿用原条目） ---- */
  { id: 'guangzhou_baiqieji', name: '白切鸡', icon: '🍗', tag: '食', type: '美食', price: 48, desc: '清远走地鸡"三提三浸"，皮爽肉滑骨髓带红。蘸姜葱蓉，广州人检验一只鸡的最高标准。' },
  { id: 'guangzhou_shaoe', name: '深井烧鹅', icon: '🦢', tag: '食', type: '美食', price: 58, desc: '荔枝木明炉烧制，皮脆如玻璃、油香四溢。斩件上桌配酸梅酱，一口下去，粤语十级也说不出话。' },
  { id: 'guangzhou_jizibing', name: '鸡仔饼', icon: '🍪', tag: '食', type: '特产', price: 18, desc: '冰肉、蒜蓉、南乳入饼，咸甜交错带椒盐香。成珠楼百年配方，长得像小鸡而得名的老广味道。' },
  { id: 'guangzhou_laopobing', name: '广式老婆饼', icon: '🥮', tag: '食', type: '特产', price: 15, desc: '冬瓜蓉馅酥皮饼，软糯清甜。传说因阿哥卖饼赎妻得名，广州人把它做成了百年手信。' },
  { id: 'guangzhou_chenpi', name: '新会陈皮', icon: '🍊', tag: '食', type: '特产', price: 88, desc: '"一两陈皮一两金"，越陈越香越值钱。煲汤炖肉放一片，广东人对时间的投资从陈皮开始。' },
  { id: 'gzg_lachang', name: '广州腊味·腊肠礼盒', icon: '🌭', tag: '食', type: '特产', price: 40, desc: '皇上皇的腊肠肥瘦相宜，酒香微甜。秋风一起广州人就晒腊味，一盒腊肠就是最正的年味。' },
  { id: 'gzg_jigonglan', name: '鸡公榄', icon: '🫒', tag: '食', type: '特产', price: 15, desc: '穿着公鸡服吹哨卖橄榄的"鸡公榄"，是老广州的街头记忆。酸甜的甘草榄，如今成了怀旧零食。' },
  { id: 'guangzhou_guangxiu', name: '广绣书签', icon: '🧵', tag: '衣', type: '文创', price: 45, desc: '四大名绣之一，一根丝线劈成几十股绣出荔枝红。书签小件，针脚里全是岭南的富丽与耐心。' },
  { id: 'gzg_guangcai', name: '广彩瓷杯', icon: '🍵', tag: '玩', type: '文创', price: 120, desc: '广彩瓷金碧辉煌，岭南花果画满杯身。清代外销瓷的爆款，如今烧进茶杯，喝的是十三行的贵气。' },
  { id: 'gzg_xingshi', name: '醒狮小摆件', icon: '🦁', tag: '玩', type: '文创', price: 60, desc: '迷你南狮头彩绘威风，眨眼睛的绒毛狮仔萌态十足。岭南醒狮文化，摆一对在案头镇宅纳福。' },
  { id: 'gzg_wudiao', name: '石湾公仔', icon: '🧸', tag: '玩', type: '文创', price: 80, desc: '石湾陶塑的公仔憨态传神，渔樵耕读样样入陶。"石湾瓦，甲天下"，广东人的客厅总少不了一只。' },
  /* ---- 花城体验与住宿（沿用原条目+新增） ---- */
  { id: 'guangzhou_zhujiang', name: '珠江夜游', icon: '🚢', tag: '行', type: '体验', price: 78, desc: '游船从天字码头出发，两岸霓虹倒进江里。经过小蛮腰时全船惊呼，珠江的夜比白天艳十倍。' },
  { id: 'guangzhou_yueju', name: '粤剧变装拍照', icon: '🎭', tag: '玩', type: '体验', price: 88, desc: '穿戴凤冠霞帔、勾面谱拍一组粤剧写真。水袖一甩、眼波一转，西关小姐的韵味上身。' },
  { id: 'guangzhou_baiyun_huadao', name: '白云山滑道', icon: '🛷', tag: '玩', type: '体验', price: 30, desc: '从山顶坐着滑车一路冲下林荫弯道，风声呼呼。上山五块钱，下山三十块尖叫，值。' },
  { id: 'gzg_xiaguo', name: '学做一只水晶虾饺', icon: '🥟', tag: '玩', type: '体验', price: 120, desc: '跟着点心师傅揉澄面、捏褶子，虾饺要十三褶才算过关。自己包的那笼，蒸出来第一个抢光。' },
  { id: 'gzg_xingshijc', name: '醒狮体验班', icon: '🦁', tag: '玩', type: '体验', price: 150, desc: '在武馆扎马步、学醒狮基本步，狮头一举就要"眨眼"。上高桩不敢，采个青讨个彩头没问题。' },
  { id: 'gzg_jianggu', name: '粤语讲古坛', icon: '🎙️', tag: '玩', type: '体验', price: 60, desc: '广州老城还有讲古坛，讲古佬一把折扇说《三国》。粤语声调一起，老广州的下午茶就有了配乐。' },
  { id: 'guangzhou_jiudian', name: '珠江新城景观房', icon: '🏨', tag: '住', type: '住宿', price: 500, desc: '高层落地窗正对小蛮腰，夜里躺在床上看塔身变色。楼下就是花城广场，广州的繁华一眼收进。' }
);

/* ================= data/cn/huanan/guangzhou/gz_03_stories.js ================= */
/* 广州 分册03：奇闻趣事（羊城源流/千年商都/西关风情/花城节庆） */
window.GZ_STORIES = window.GZ_STORIES || [];
window.GZ_STORIES.push(
  /* ---- 羊城源流 ---- */
  { id: 'gzs_wuyang', name: '五羊衔谷的传说', icon: '🐏', desc: '相传五位仙人骑五色羊衔谷穗降临，祝福此地"永无饥荒"。广州因此称"羊城""穗城"，五羊石像成了城市的图腾。' },
  { id: 'gzs_guangxiao', name: '光孝寺的"风幡之争"', icon: '🍃', desc: '六祖慧能初到光孝寺，见僧争论"风动还是幡动"，他一句"仁者心动"语惊四座。禅宗六祖，就在这棵菩提树下受戒。' },
  { id: 'gzs_yueyu', name: '粤语里藏着唐音', icon: '🗣️', desc: '粤语保留了大量中古音，用粤语念唐诗格外押韵。九声六调抑扬顿挫，难怪有人笑称"讲粤语像在唱歌"。' },
  { id: 'gzs_mumian', name: '英雄花木棉', icon: '🌸', desc: '木棉又叫英雄花，花开时满树红艳不落一叶。老广州捡木棉花晒干煲汤，红棉盛开的春天，是这座城市最昂扬的样子。' },
  { id: 'gzs_tao_taoju', name: '陶陶居的百年牌匾', icon: '🏮', desc: '陶陶居茶楼开了一百多年，招牌出自康有为之手。一盅两件叹到今天，老广州的社交场从来不缺这张茶桌。' },
  /* ---- 千年商都 ---- */
  { id: 'gzs_shisanhang', name: '十三行的黄金年代', icon: '⚓', desc: '清代广州一口通商，十三行商馆垄断中西贸易几十年。白银从这里流进中国，世界货从这里走向全球。' },
  { id: 'gzs_huangpugang', name: '哥德堡号的广州之旅', icon: '🚢', desc: '十八世纪瑞典商船"哥德堡号"三赴广州，带回的瓷器茶叶养活了半个瑞典。沉船后打捞的文物，如今两国共享。' },
  { id: 'gzs_guangjiaohui', name: '广交会六十年', icon: '🛍️', desc: '1957年起，广交会一年两届从未中断，被称为"中国第一展"。万商云集流花路，广州的外贸故事一直在续写。' },
  { id: 'gzs_guangshi', name: '石室的"岭南石匠"', icon: '⛪', desc: '圣心大教堂的石头从香港打磨好再运来，是法国设计师与广东石匠合力的杰作。中西手艺，砌成一座纯石哥特。' },
  /* ---- 西关风情与市井 ---- */
  { id: 'guangzhou_story_shichi', name: '"什么都敢吃"的误会', icon: '🍽️', desc: '"食在广州"被传成广州人什么都敢吃，其实粤菜最讲鲜与本味。真正的底气是：一只鸡都有几十种做法。' },
  { id: 'guangzhou_story_tan', name: '"叹"早茶哲学', icon: '☕', desc: '广州人说"叹早茶"，"叹"就是享受。一盅两件坐一上午，报纸看完再走——慢慢来，是这座城市最奢侈的日常。' },
  { id: 'gzs_xiguan_dongshan', name: '西关小姐与东山少爷', icon: '🎩', desc: '老广州一句"东山少爷、西关小姐"，讲的是富商住西关、权贵居东山。如今的东山口成了潮店聚集地，少爷们换成了年轻人。' },
  { id: 'gzs_qilou', name: '骑楼下的清凉', icon: '🏘️', desc: '南洋华侨把骑楼带回广州，二楼住人一楼留廊，遮阳避雨。骑楼下卖糖水卖凉茶，广州人的夏天其实不怕晒。' },
  { id: 'gzs_xingshi', name: '醒狮的"采青"', icon: '🦁', desc: '过年舞狮要"采青"：把生菜利是挂在高处，狮子叠罗汉去摘。醒狮一舞，锣鼓一响，广东人的年才正式开始。' },
  { id: 'gzs_jigonglan', name: '吹哨子的"鸡公榄"', icon: '🎺', desc: '从前卖榄人扮成公鸡沿街叫卖，哨子一响孩子就围过来。一句"鸡公榄，有辣有唔辣"，是老广州回不去的童年。' },
  { id: 'gzs_tingzai', name: '艇仔粥与水上的疍家', icon: '🛶', desc: '疍家人世代住在船上，以船为家。他们在艇上卖粥、唱咸水歌，一碗艇仔粥里，是水上人家的烟火人间。' },
  { id: 'guangzhou_story_liangcha', name: '凉茶铺的救场话梅', icon: '😖', desc: '第一次喝廿四味的游客表情管理全线崩溃，老板娘见怪不怪递上一颗话梅。这颗话梅被称为"广州最温柔的售后服务"。' },
  { id: 'gzs_ditie', name: '广州地铁三号线的"人潮"', icon: '🚇', desc: '广州地铁三号线是"全国最挤"，早晚高峰摩肩接踵。广州人一边吐槽一边挤，谁让珠江新城和城中村都在这条线上。' },
  { id: 'guangzhou_story_tajian', name: '小蛮腰的百变灯光', icon: '🌈', desc: '广州塔每晚换装：过年红、清明白、节庆金……网友练就"看塔辨节日"的本领，它成了全城最大电子日历。' },
  { id: 'guangzhou_story_zhuandiao', name: '陈家祠的"砖雕大戏"', icon: '🎬', desc: '陈家祠墙上一块砖雕能雕七层楼阁、上百人物。当年工匠按戏出雕刻，游客笑称"清末的连续剧，一集都没烂尾"。' },
  { id: 'gzs_panda3', name: '长隆的熊猫三胞胎', icon: '🐼', desc: '全球唯一存活的熊猫三胞胎"萌帅酷"在长隆出生，妈妈"菊笑"一胎三宝成了明星。广州人隔三差五就去看它们长大。' },
  /* ---- 花城节庆 ---- */
  { id: 'gzs_huashi', name: '除夕夜行花街', icon: '🌸', desc: '"未行花街，不算过年"。广州人除夕逛花市，买金桔桃花图个好彩头。花城的花街一开，年味就到了。' },
  { id: 'gzs_longzhou', name: '龙舟水里的端午节', icon: '🐲', desc: '端午前后广州人赛龙舟、吃龙船饭，猎德村的龙舟请出水要拜三拜。鼓声一响，整条珠江都跟着沸腾。' },
  { id: 'gzs_boluodan', name: '波罗诞的千年庙会', icon: '⛩️', desc: '南海神庙的"波罗诞"是珠三角最盛大的庙会，善信"买波罗鸡"求平安。十万人挤进庙里，比过年还热闹。' },
  { id: 'guangzhou_story_richu', name: '凌晨白云山等日出', icon: '🌄', desc: '看日出不一定要去海边，广州仔凌晨四点爬白云山，摩星岭上一人一壶茶等天亮。下山还能饮个早茶，完美闭环。' }
);

/* ================= data/cn/huanan/guangzhou/guangzhou.js ================= */
/* ============ 广州（完全版·分册组装） ============
 * 分册：gz_01地点 / gz_02周边 / gz_03趣事。
 * 叙事主线：千年商都海丝 / 西关骑楼市井 / 叹茶食在广州 / 花城四季。
 */
(function () {
  window.TRAVEL_CITIES = window.TRAVEL_CITIES || [];
  window.TRAVEL_CITIES.push({
    id: 'guangzhou',
    name: '广州',
    country: '中国',
    cc: 'CN',
    province: '广东',
    flag: '🇨🇳',
    region: '华南',
    hero: '🗼',
    desc: '两千年的商都，骑楼下飘着肠粉和靓汤香。"小蛮腰"亮灯时珠江生辉，早茶桌上的虾饺永远是第一主角。',
    travel: [{ name: '高铁', icon: '🚄', cost: 460 }, { name: '飞机', icon: '✈️', cost: 780 }],
    visa: null,
    spots: (window.GZ_SPOTS = window.GZ_SPOTS || []),
    souvenirs: (window.GZ_GIFTS = window.GZ_GIFTS || []),
    stories: (window.GZ_STORIES = window.GZ_STORIES || []),
  });
})();

/* ================= data/cn/huanan/guilin/gl_01_spots.js ================= */
/* 桂林 分册01：景点圣地（漓江山水 / 城区峰林 / 喀斯特溶洞 / 古镇田园 / 郊县壮景） */
window.GL_SPOTS = window.GL_SPOTS || [];
window.GL_SPOTS.push(
  /* ---- 旧档原条目（保留不动） ---- */
  { id: 'guilin_lijiang', name: '漓江竹筏（兴坪-九马画山）', icon: '🛶', price: 216, desc: '"江作青罗带，山如碧玉簪"。竹筏过黄布倒影——20元人民币背面取景地，掏出纸币对照拍照是仪式。' },
  { id: 'guilin_yangshuo', name: '阳朔西街·遇龙河', icon: '🏘️', price: 0, desc: '1400年历史的西街，"地球村"酒吧美食云集。遇龙河竹筏是最温柔的漂流，两岸稻田如画。' },
  { id: 'guilin_xiangbishan', name: '象鼻山', icon: '🐘', price: 55, desc: '桂林城徽，山形如巨象饮水。水月洞倒影成"象山水月"，夜景灯光下更梦幻。' },
  { id: 'guilin_ludiyan', name: '芦笛岩', icon: '💎', price: 90, desc: '"大自然艺术之宫"，溶洞钟乳石五彩斑斓。狮岭朝霞与水晶宫，"国宾洞"接待过无数元首。' },
  { id: 'guilin_longji', name: '龙脊梯田', icon: '🌾', price: 80, desc: '龙脊山上的"天梯"，壮瑶族人耕种650年。五月灌水如镜、九月金浪翻滚，云雾天如登天梯。' },
  { id: 'guilin_liangjiang', name: '两江四湖夜游', icon: '⛴️', price: 185, desc: '夜游串联漓江、桃花江与四湖，日月双塔金光倒影。榕湖桥底的水下灯光，"桂林夜色封神"。' },
  { id: 'guilin_yinzi', name: '银子岩', icon: '🕳️', price: 85, desc: '"游了银子岩，一世不缺钱"。雪松般的钟乳石银光闪闪，三层溶洞迷宫。' },
  /* ---- 新增（分册扩容） ---- */
  { id: 'glp_duxiufengwangcheng', name: '独秀峰·王城', icon: '🏯', price: 100, desc: '明太祖封藩靖江王在此营建王城，比故宫还早的皇家气派。登上独秀峰顶，桂林城层层瓦檐尽收眼底，贡院的号舍仍留着科举墨香。' },
  { id: 'glp_qixingyan', name: '七星岩', icon: '🪨', price: 90, desc: '七星岩与芦笛岩并称桂林两大老牌溶洞，隋唐起就有人进洞题壁。洞中石笋石幔千姿百态，出洞还能逛逛花桥与骆驼山。' },
  { id: 'glp_diecaishan', name: '叠彩山', icon: '🏔️', price: 60, desc: '山石层层叠起如彩缎堆锦，故得名叠彩。登拿云亭可把漓江与桂林城收进同一幅画面，陈毅“愿做桂林人，不愿做神仙”的名句就刻在洞口。' },
  { id: 'glp_fuboshan', name: '伏波山', icon: '⛰️', price: 30, desc: '一座石山半插进漓江，传说伏波将军曾在此试剑退敌。还珠洞里的试剑石悬空不落，岩壁上还留着宋人的摩崖题刻。' },
  { id: 'glp_yulonghe', name: '遇龙河竹筏（金龙桥段）', icon: '🛶', price: 150, desc: '遇龙河是漓江最温柔的支流，竹筏慢悠悠地过一道道青石矮坝。水清得能看见水草摆动，岸边的凤尾竹和牛陪你走上几里。' },
  { id: 'glp_shilixiang', name: '十里画廊', icon: '🚵', price: 0, desc: '阳朔往月亮山的景观长廊，喀斯特山影一帧帧从窗外掠过。骑单车最自在，累了就拐进路边的大榕树或聚龙潭歇脚。' },
  { id: 'glp_xingping', name: '兴坪古镇', icon: '🏡', price: 0, desc: '漓江边的千年古镇，青石板路一直铺到码头。黄昏时分渔翁披蓑衣驾竹排，二十元人民币背面的元宝山就立在镇前的江面上。' },
  { id: 'glp_riyueshuangta', name: '日月双塔', icon: '🗼', price: 35, desc: '杉湖中央一金一银两座塔并肩而立，日塔通体以铜铸成。入夜灯光亮起，塔与倒影在水面拉成两团光晕，是桂林夜景的招牌画面。' },
  { id: 'glp_lingqu', name: '兴安灵渠', icon: '🏺', price: 55, desc: '秦始皇为运送粮草凿通的古运河，把湘江与漓江连在一起。铧嘴分水、天平泄洪，两千多年过去这处水利仍在灌溉农田。' },
  { id: 'glp_maoershan', name: '猫儿山', icon: '🐱', price: 120, desc: '华南第一高峰，漓江的源头老山界就在群山之间。雨后云海漫过峰顶，四月高山杜鹃盛放，红军的足迹也留在这片山里。' },
  { id: 'glp_gudongpubu', name: '古东瀑布', icon: '💦', price: 65, desc: '全国少见的可攀瀑布，夏天穿草鞋拽铁链溯溪而上，水花溅湿半截裤腿。八级瀑布一级比一级清凉，山顶的老藤古树也好看。' },
  { id: 'glp_taohuayuan', name: '世外桃源', icon: '🌸', price: 60, desc: '阳朔把陶渊明的桃花源搬进了现实：小船穿过漆黑山洞，豁然开朗处有侗寨鼓楼与桃林，岸上拦路歌把游人唱进画里。' },
  { id: 'glp_dongxiang', name: '东西巷·逍遥楼', icon: '🛍️', price: 0, desc: '明清老巷改成的街区，青砖马头墙里开着小店与戏台。夜里灯笼成串亮起，登上重建的逍遥楼，能望见漓江和对岸灯火。' },
  { id: 'glp_yaoshan', name: '尧山索道', icon: '🚡', price: 100, desc: '缆车缓缓爬升，把桂林城最高的尧山送上云端。山顶俯瞰，万座峰林像春笋立在阡陌田野间，傍晚还能等一场镀金晚霞。' },
  { id: 'glp_dayurongshu', name: '大榕树', icon: '🌳', price: 25, desc: '树龄一千四百多年的古榕，树冠铺开足有二十多亩。传说刘三姐与阿牛哥在此抛绣球定情，如今树下仍围满拍照的游人。' },
  { id: 'glp_lijiangyouchuan', name: '漓江三星游船', icon: '🚢', price: 215, desc: '从磨盘山码头乘游船顺漓江而下，四小时躺在甲板上看景。九马画山、黄布倒影迎面而来，船一转舵又是一幅新画。' },
  { id: 'glp_bajiaozhai', name: '资源八角寨', icon: '⛰️', price: 90, desc: '桂林最北藏着一片丹霞地貌，八角寨的崖壁像被刀斧劈过。雨后云海翻涌，人贴着窄窄的山脊行走，腿肚子直打颤。' },
  { id: 'glp_zizhou', name: '訾洲·象鼻山观景台', icon: '🌿', price: 40, desc: '象鼻山正对的江心洲，是看象山水月的最佳位置。雨雾天来最有味道，“訾洲烟雨”从唐代就是桂林八景，柳宗元还写过游记。' },
  { id: 'glp_daxu', name: '大圩古镇', icon: '🏮', price: 0, desc: '漓江边的千年圩市，青石板街与万寿桥都还是老样子。江边石码头逐级没入水中，傍晚有人挑担有人浣衣，日子走得格外慢。' }
);

/* ================= data/cn/huanan/guilin/gl_02_gifts.js ================= */
/* 桂林 分册02：特色周边（山水美食 / 桂花手信 / 壮乡文创 / 户外体验） */
window.GL_GIFTS = window.GL_GIFTS || [];
window.GL_GIFTS.push(
  /* ---- 旧档原条目（保留不动） ---- */
  { id: 'guilin_mifen', name: '桂林米粉', icon: '🍜', tag: '食', type: '美食', price: 10, desc: '卤水米粉先干拌后加汤，锅烧脆皮是灵魂。"桂林人的一天从二两米粉开始"。' },
  { id: 'guilin_pijiuyu', name: '阳朔啤酒鱼', icon: '🐟', tag: '食', type: '美食', price: 88, desc: '漓江鱼配啤酒焖烧，鱼鳞都炸得酥脆。西街每家店都有"秘方"，剑骨鱼最贵最嫩。' },
  { id: 'guilin_suancai', name: '桂林酸品', icon: '🥒', tag: '食', type: '美食', price: 10, desc: '"英雄难过美人关，美人难过酸摊关"。酸萝卜、酸芒果蘸辣椒盐，桂北人的解馋神器。' },
  { id: 'guilin_luohan', name: '罗汉果', icon: '🍈', tag: '食', type: '特产', price: 40, desc: '"东方神果"甜度是蔗糖300倍且零热量。罗汉果茶润嗓，桂林人的"随身药箱"。' },
  { id: 'guilin_sanyu', name: '三花酒·豆腐乳', icon: '🍶', tag: '食', type: '特产', price: 40, desc: '桂林三宝：三花酒、豆腐乳、辣椒酱。三花酒斟酒起花三层，"米香型白酒之王"。' },
  { id: 'guilin_huashan', name: '壮锦·扎染', icon: '🧶', tag: '衣', type: '服饰', price: 90, desc: '壮锦团龙纹围巾、蓝染布包。龙脊红瑶长发姐姐的手作，"山里的颜色"。' },
  { id: 'guilin_shanshui', name: '山水文创·人民币打卡框', icon: '💵', tag: '衣', type: '文创', price: 25, desc: '20元人民币同款画框、漓江山水冰箱贴。在兴坪举着画框对齐真山，"全民仪式感"。' },
  { id: 'guilin_yurehe', name: '遇龙河竹筏漂流', icon: '🚣', tag: '玩', type: '体验', price: 200, desc: '人工撑筏慢漂4小时，过堤坝"小刺激"。水牛在岸边吃草，"最温柔的漂流"。' },
  { id: 'guilin_feiji', name: '热气球看峰林', icon: '🎈', tag: '玩', type: '体验', price: 300, desc: '阳朔热气球升空，俯瞰万座喀斯特小山包。"桂林山水的上帝视角"。' },
  { id: 'guilin_panye', name: '印象刘三姐演出', icon: '🎭', tag: '玩', type: '体验', price: 238, desc: '张艺谋导演，漓江水面为舞台。600名演员渔火点点，"山水实景演出鼻祖"。' },
  { id: 'guilin_panxi', name: '攀岩·骑行十里画廊', icon: '🚲', tag: '玩', type: '体验', price: 120, desc: '阳朔是全球著名攀岩地，月亮山岩壁经典。骑行十里画廊，"人车共游山水间"。' },
  { id: 'guilin_minsu', name: '漓江边民宿', icon: '🏨', tag: '住', type: '住宿', price: 350, desc: '兴坪江畔民宿，阳台正对黄布倒影。清晨渔翁带鸬鹚从窗前划过，"20元画面实景"。' },
  /* ---- 新增（分册扩容） ---- */
  { id: 'glg_tianluoniang', name: '阳朔田螺酿', icon: '🐚', tag: '食', type: '美食', price: 28, desc: '田螺肉挑出剁碎，拌上猪肉薄荷紫苏再塞回螺壳，连壳焖烧。牙签挑出一整颗塞进嘴里，满口鲜香，是“十八酿”里最勾人的一口。' },
  { id: 'glg_youcha', name: '恭城油茶', icon: '🍵', tag: '食', type: '美食', price: 15, desc: '茶叶姜蒜在铁锅里捶出茶沫，冲进滚水煮成一碗咸香。配米花麻蛋炒花生，苦后回甘，瑶家人说三碗下肚才算喝过。' },
  { id: 'glg_guihuagao', name: '桂花糕', icon: '🌼', tag: '食', type: '特产', price: 18, desc: '糯米粉兑糖桂花蒸成小方糕，面上撒一层金桂。趁热咬开软糯弹牙，桂花香从舌尖漫到喉咙，满口都是秋天的味道。' },
  { id: 'glg_guihuami', name: '桂林桂花蜜', icon: '🍯', tag: '食', type: '特产', price: 45, desc: '金桂入蜜封存，琥珀色的蜜里浮着细碎花瓣。冲温水或蘸糕饼皆宜，一勺下去，把桂林满城的桂香都收进瓶底。' },
  { id: 'glg_guihuatang', name: '桂花糖', icon: '🍬', tag: '食', type: '美食', price: 15, desc: '麦芽糖裹进干桂花与芝麻，切成一粒粒小方块。入口酥脆、满嘴花香，是老桂林人兜里的童年零嘴。' },
  { id: 'glg_guihuaxiangnang', name: '桂花香囊', icon: '🌸', tag: '闻', type: '文创', price: 35, desc: '应季桂花晾干装进绣花布囊，挂在包上或枕边，暗香能浮上小半年。每只花纹都不同，带走一袋桂林的甜香。' },
  { id: 'glg_lipuyukourou', name: '荔浦芋扣肉', icon: '🍖', tag: '食', type: '美食', price: 48, desc: '荔浦芋头粉糯起沙，与带皮五花肉相间码进碗里，蒸到肉化芋香。扣肉入口即化，芋片吸饱肉汁，是广西年夜饭的压轴菜。' },
  { id: 'glg_lijiangyugan', name: '漓江小鱼干', icon: '🐟', tag: '食', type: '特产', price: 38, desc: '漓江里的小鱼仔晒干再油酥，拌上辣椒芝麻炒得香酥透骨。抓一把配粥下酒都合适，漓江的鲜味被装进一只小罐。' },
  { id: 'glg_shanshuisijin', name: '漓江山水丝巾', icon: '🧣', tag: '衣', type: '服饰', price: 120, desc: '真丝方巾印着漓江山水与渔翁竹筏，蓝绿渐层如水墨晕染。系在颈间或缠上包带，把二十元人民币的风景随身带着走。' },
  { id: 'glg_guilinmingxinpian', name: '漓江手绘明信片', icon: '📮', tag: '玩', type: '文创', price: 30, desc: '手绘桂林山水明信片，附一张二十元取景对照卡。在兴坪码头挑一张写好，盖上桂林邮戳，寄给远方的朋友。' },
  { id: 'glg_huaxiangsan', name: '阳朔滑翔伞', icon: '🪂', tag: '玩', type: '体验', price: 420, desc: '从十里画廊的山坡起飞，教练带你滑翔过峰林与稻田。双脚离地那刻风声灌满耳朵，落地后还忍不住抬头再看天。' },
  { id: 'glg_qianguqing', name: '桂林千古情', icon: '🎪', tag: '玩', type: '体验', price: 260, desc: '宋城出品的歌舞大秀，把桂林山水与传说搬上旋转舞台。灯光喷泉追着剧情走，雨丝真从头顶飘落，阳朔之夜多了场热闹。' },
  { id: 'glg_longjidiaojiao', name: '龙脊吊脚楼民宿', icon: '🏚️', tag: '住', type: '住宿', price: 280, desc: '木楼悬在梯田之上，推窗便是层层金浪或翻涌云雾。夜里听虫鸣、清晨等日出，壮族阿嫂端来一碗油茶，日子慢成风景。' },
  { id: 'glg_fuzi', name: '王府福字拓印', icon: '📜', tag: '玩', type: '文创', price: 25, desc: '在靖江王城贡院里亲手拓一张“福”字，墨香中沾沾千年文气。老师傅手把手教，拓好的福字卷起带走，是最好的彩头。' },
  { id: 'glg_xiuqiu', name: '壮乡绣球', icon: '🧵', tag: '玩', type: '文创', price: 30, desc: '壮族姑娘抛给心上人的定情信物，彩绸拼缝、下缀流苏。挑一只挂进车里或别在包上，山歌里的浪漫便一路跟着你。' }
);

/* ================= data/cn/huanan/guilin/gl_03_stories.js ================= */
/* 桂林 分册03：奇闻趣事（传说 / 人物历史 / 山水风物 / 市井节庆） */
window.GL_STORIES = window.GL_STORIES || [];
window.GL_STORIES.push(
  /* ---- 旧档原条目（保留不动） ---- */
  { id: 'guilin_story_20', name: '20元人民币的取景地', icon: '💵', desc: '兴坪漓江段的元宝山就是纸币背面风景。游客人手一张20元对镜拍照，"最接地气的打卡"。' },
  { id: 'guilin_story_suan', name: '"英雄难过美人关"的下半句', icon: '🥒', desc: '桂林酸摊全国独一份，酸嘢文化源自湿热气候。本地谚语：英雄难过美人关，美人难过酸摊关。' },
  { id: 'guilin_story_luohan', name: '罗汉果的"神果"之路', icon: '🍈', desc: '罗汉果原是瑶族秘药，如今甜味剂出口全球。"零卡甜"的东方智慧，桂北山地的财富。' },
  { id: 'guilin_story_longji', name: '龙脊梯田的"六百年接力"', icon: '🌾', desc: '壮瑶先民从元朝开始凿山造田，最大坡度50度。一根扁担养活一族人，"挂在山上的史诗"。' },
  { id: 'guilin_story_laojie', name: '西街的"地球村"', icon: '🌍', desc: '80年代背包客发现阳朔，西街成了"洋人街"。咖啡馆招牌中英双语三十年，"最早的国际化小镇"。' },
  { id: 'guilin_story_lusan', name: '刘三姐的歌仙传说', icon: '🎵', desc: '刘三姐用山歌斗败三个秀才的传说家喻户晓。如今桂林人吵架都自带山歌韵脚，"歌仙故里"。' },
  /* ---- 新增（分册扩容） ---- */
  { id: 'gls_hanyu_yiju', name: '韩愈一句诗捧红桂林', icon: '📜', desc: '唐代韩愈写下“江作青罗带，山如碧玉簪”，一句诗让桂林美了千年。有趣的是他本人从未来过桂林，诗是送给赴桂林任官的友人。' },
  { id: 'gls_xiangshan_chuanshuo', name: '象鼻山的神象传说', icon: '🐘', desc: '传说一头神象给天帝驮经，累得在漓江边喝水，被宝剑钉住化成石头山。象鼻低垂探入江心，水月洞正是那弯喝水的地方。' },
  { id: 'gls_jiuxiamashan', name: '九马画山数马', icon: '🐎', desc: '九马画山的崖壁上，灰白纹路天然勾出群马。相传谁数出九匹就能中状元，船工总爱逗游客：你看出了几匹？' },
  { id: 'gls_wangcheng_gushi', name: '王城比故宫还早', icon: '🏯', desc: '朱元璋封侄孙为靖江王，在桂林营建王城，比北京故宫还早三十多年。城墙围了六百多年，如今广西师大的学生天天在里面上课。' },
  { id: 'gls_gongyuan_zhuangyuan', name: '贡院走出四位状元', icon: '🎓', desc: '清代广西贡院就设在王城里，从这里走出四位状元。赶考的书生都爱摸一摸“状元及第”坊，沾一沾沉淀百年的文气。' },
  { id: 'gls_xuxiake_guilin', name: '徐霞客的桂林日记', icon: '🧭', desc: '徐霞客在桂林游了一个多月，钻遍七星岩与芦笛岩，写下上万字游记。他说桂林的山“如青莲出水”，至今仍是旅人的地图。' },
  { id: 'gls_lijiang_yugong', name: '漓江上的鸬鹚渔翁', icon: '🎣', desc: '老渔翁撑着竹排，几只鸬鹚立在船头。鱼鹰一个猛子扎进水里，叼上鱼来乖乖上交，这手艺从爷爷传到了孙子。' },
  { id: 'gls_yulonghe_chuan', name: '遇龙河与遇龙桥', icon: '🐉', desc: '传说有条龙常在遇龙河兴风作浪，被仙人施法镇住，桥因此得名遇龙桥。如今桥下竹筏悠悠，龙的影子只在水底浅浅地晃。' },
  { id: 'gls_mifen_qinshi', name: '米粉是秦军的乡愁', icon: '🍜', desc: '相传修建灵渠的秦军想念家乡的面条，伙夫把米磨浆蒸熟压成细条，米粉就此诞生。两千年前的思乡，成了桂林人的每日早点。' },
  { id: 'gls_yaojia_youcha', name: '瑶家油茶待客', icon: '🍵', desc: '瑶家待客先敬油茶，茶叶姜蒜在捶打里出味，滚水一冲香气四溢。客人不喝满三碗不许走，这是茶山的规矩，也是茶山的热情。' },
  { id: 'gls_hongyao_shaoyi', name: '红瑶长发与晒衣节', icon: '🎊', desc: '龙脊黄洛瑶寨的红瑶女子，头发留得又长又亮很少剪。每年六月六晒衣节，吊脚楼挂满五彩嫁衣，长发表演一亮相就围满游客。' },
  { id: 'gls_guilin_gui', name: '桂林因桂树成林得名', icon: '🌳', desc: '桂林的名字来自“桂树成林”，桂花是这座城的市花。深秋满城金桂银桂盛开，风一吹桂花雨落得人满身都是香。' },
  { id: 'gls_sanhuajiu_jiuhua', name: '三花酒摇出的三层花', icon: '🍶', desc: '桂林酒坊摇动酒坛，酒面能泛起三层细花，三花酒因此得名。米香醇厚度数不高，本地人吃啤酒鱼时也要倒上一杯。' },
  { id: 'gls_yinxiang_sanjie', name: '印象刘三姐点亮漓江', icon: '🎭', desc: '2004年张艺谋把刘三姐的歌搬上漓江水面，六千平方米的水上舞台，渔民划着竹排当演员。山水实景演出从此风靡全国。' },
  { id: 'gls_yangshuo_panyan', name: '阳朔是攀岩者的天堂', icon: '🧗', desc: '阳朔的石灰岩崖壁吸引着全世界的攀岩者，月亮山一带挂满彩色岩点。白天攀岩泡在岩壁，晚上回西街喝酒，一住就是好几个月。' }
);

/* ================= data/cn/huanan/guilin/guilin.js ================= */
/* ============ 桂林（完全版·分册组装） ============
 * 分册：gl_01地点 / gl_02周边 / gl_03趣事。
 * 叙事主线：漓江山水甲天下 / 城在山中画卷 / 桂香与市井烟火 / 民族与户外活力。
 */
(function () {
  window.TRAVEL_CITIES = window.TRAVEL_CITIES || [];
  window.TRAVEL_CITIES.push({
    id: 'guilin',
    name: '桂林',
    country: '中国',
    cc: 'CN',
    province: '广西',
    flag: '🇨🇳',
    region: '华南',
    hero: '🏞️',
    desc: '"桂林山水甲天下"：漓江竹筏穿行喀斯特峰林，二十元人民币背面的风景就在眼前，阳朔西街的啤酒鱼香飘四季。',
    travel: [{ name: '高铁', icon: '🚄', cost: 350 }, { name: '飞机', icon: '✈️', cost: 750 }],
    visa: null,
    spots: (window.GL_SPOTS = window.GL_SPOTS || []),
    souvenirs: (window.GL_GIFTS = window.GL_GIFTS || []),
    stories: (window.GL_STORIES = window.GL_STORIES || []),
  });
})();

/* ================= data/cn/huanan/sanya/sya_01_spots.js ================= */
/* 三亚 分册01：景点圣地（经典海湾 / 离岛雨林 / 人文地标 / 网红新场） */
window.SYA_SPOTS = window.SYA_SPOTS || [];
window.SYA_SPOTS.push(
  /* ---- 旧档原条目（保留不动） ---- */
  { id: 'sanya_yalongwan', name: '亚龙湾', icon: '🏖️', price: 0, desc: '"天下第一湾"，七千米月牙形白沙细腻如粉。公共沙滩免费开放，躺在椰影下，海水蓝得分成三层渐变。' },
  { id: 'sanya_wuzhizhou', name: '蜈支洲岛', icon: '🐠', price: 144, desc: '海水能见度冠绝全岛的"潜水天堂"，珊瑚花园近在脚下。环岛电瓶车绕一圈，情人桥上全是浪漫。' },
  { id: 'sanya_tianyahaijiao', name: '天涯海角', icon: '🗿', price: 81, desc: '清雍正年间题刻的"天涯""海角"巨石卧在碧海银滩。古人的世界尽头，如今的爱情圣地，排队也要合张影。' },
  { id: 'sanya_nanshan', name: '南山文化旅游区', icon: '🙏', price: 108, desc: '108米海上观音凌波而立。素斋馆的罗汉斋值得一试，佛教文化与椰岛风光同框。' },
  { id: 'sanya_dadonghai', name: '大东海', icon: '🌅', price: 0, desc: '离市区最近的海湾，傍晚本地人跳舞、游客逐浪。救生员吹哨声、沙滩排球声和海浪声组成热闹的和弦。' },
  { id: 'sanya_luhuitou', name: '鹿回头公园', icon: '🦌', price: 45, desc: '黎族"鹿回头"传说的发源地，山顶俯瞰三亚湾全景。日落时分"最美夕阳海湾"亮灯，情侣打卡预定地。' },
  { id: 'sanya_houhai', name: '后海村', icon: '🏄', price: 0, desc: '冲浪爱好者聚集的小渔村，浪型温柔适合新手。白天学冲浪，傍晚海边酒吧看落日，躺平式度假天花板。' },
  /* ---- 新扩充：海湾与日落 ---- */
  { id: 'syap_yemeng', name: '三亚湾·椰梦长廊', icon: '🌇', price: 0, desc: '二十里椰林沿着海湾铺成长廊，傍晚人人都朝着落日走。海面上金光碎成鱼鳞，渔船摇着桨缓缓归来，本地人把这里叫落日大厅。' },
  { id: 'syap_xidao', name: '西岛', icon: '🏝️', price: 98, desc: '离岸不远的珊瑚岛，一上岸就是四百年渔村。旧渔船泊在浅湾，登上牛王岭看玻璃海，赶早班船还能撞见渔民拉网。' },
  { id: 'syap_xiaodonghai', name: '小东海', icon: '🌊', price: 0, desc: '大东海旁的隐世礁石滩，游客稀少水也清。退潮时礁石缝里藏着海螺和小蟹，本地人带张折叠凳，一坐就是一下午。' },
  { id: 'syap_taiyangwan', name: '太阳湾公路', icon: '🛣️', price: 0, desc: '贴着珊瑚湾修出的沿海公路，弯道一个接一个。自驾到观景台停下，翡翠色的海水在脚下翻涌，风里全是海盐味。' },
  { id: 'syap_fenghuangdao', name: '凤凰岛', icon: '🌆', price: 0, desc: '五栋白色大楼立在人工岛上，像竖起的手掌对着海面。入夜灯光流转，整座岛都在变色，是三亚湾最抢镜的地标。' },
  { id: 'syap_fanchuan', name: '半山半岛帆船港', icon: '⛵', price: 0, desc: '港湾里桅杆密得像一片树林，白帆在蓝天下转着圈。傍晚帆影拖着长尾巴归港，站在栈桥上看久了，出海的心会痒。' },
  { id: 'syap_bailu', name: '三亚河·白鹭公园', icon: '🦢', price: 0, desc: '城市中心的河岸公园，红树林里栖满白鹭。傍晚白鹭群从椰林顶上掠过，本地人沿河散步遛弯，慢是三亚的另一面。' },
  /* ---- 新扩充：离岛雨林与山野 ---- */
  { id: 'syap_senlin', name: '热带天堂森林公园', icon: '🌿', price: 158, desc: '亚龙湾后山的雨林王国，过江龙索桥颤颤悠悠连着两座山峰。桥那头是树屋咖啡，回头看，海湾像一块蓝绸子摊在脚下。' },
  { id: 'syap_dadongtian', name: '大小洞天', icon: '🏞️', price: 90, desc: '南山脚下海山相拥，崖壁上留着宋代以来的石刻题字。洞府清幽，海风穿堂，站在礁石上看浪，才懂什么叫福如东海。' },
  { id: 'syap_zhongliao', name: '中廖村·黎村田园', icon: '🏡', price: 0, desc: '吉阳山下的黎族村庄，稻田边织机咿呀响，黎锦的彩色纹样在阿婆手里慢慢长出来。喝一杯山兰酒，黎歌唱到月亮爬上槟榔树。' },
  { id: 'syap_meiguigu', name: '亚龙湾玫瑰谷', icon: '🌹', price: 60, desc: '山坡开满各色玫瑰，花田一直铺到山脚。三亚的日头把花瓣晒得格外沉，风一吹，整面坡的花都跟着点头。' },
  { id: 'syap_hudiegu', name: '亚龙湾蝴蝶谷', icon: '🦋', price: 50, desc: '热带雨林里的蝴蝶园，大翅膀的蝴蝶落在肩头不肯走。溪流边树影斑驳，翅膀扑棱的声音比浪还温柔。' },
  { id: 'syap_shuidao', name: '水稻国家公园', icon: '🦕', price: 88, desc: '海棠湾边的稻田里站着一大群会叫会摇头的恐龙，全按化石一比一复刻。小朋友追着恐龙跑，大人在田埂上等晚霞。' },
  /* ---- 新扩充：人文地标与度假新场 ---- */
  { id: 'syap_mianshui', name: '海棠湾国际免税城', icon: '🛍️', price: 0, desc: '单体面积数一数二的免税商城，橱窗从香化排到腕表。有人拎着登机牌赶在起飞前来扫最后一单，柜姐笑称这里像机场候机室。' },
  { id: 'syap_yalandisi', name: '亚特兰蒂斯水世界', icon: '🎢', price: 358, desc: '恒温水上王国，玻璃滑道从塔顶直冲进鲨鱼池。胆子小的去造浪池，浪一来，全场的尖叫比海还响。' },
  { id: 'syap_yazhougucheng', name: '崖州古城', icon: '🏯', price: 0, desc: '明清古城墙围着千年学宫，红墙琉璃瓦藏着海岛的书香气。骑楼老街卖着本地小吃，三亚人的祖辈大多从这里走向大海。' },
  { id: 'syap_qianguqing', name: '三亚千古情', icon: '🎭', price: 280, desc: '一场歌舞看完黎苗上千年：鹿回头、冼夫人、海上丝路轮番登场。声光电把剧场变成涨潮的海，演员会突然从观众席后头走出来。' },
  { id: 'syap_fenghuangling', name: '凤凰岭·海誓山盟', icon: '🚡', price: 96, desc: '索道缓缓爬上主峰，山顶挂满同心锁与红绸。黄昏时海天之间像烧起来，成对的人举着手机等最后一缕光。' },
  { id: 'syap_tianyazhen', name: '天涯小镇', icon: '🏘️', price: 0, desc: '蓝白小楼从渔村一直刷到海边，一条街的墙都是海的颜色。本地人叫它马岭，年轻人喊它天涯小镇，巷子尽头就是沙滩。' }
);

/* ================= data/cn/huanan/sanya/sya_02_gifts.js ================= */
/* 三亚 分册02：特色周边（海鲜椰子 / 黎苗手信 / 海岛体验） */
window.SYA_GIFTS = window.SYA_GIFTS || [];
window.SYA_GIFTS.push(
  /* ---- 旧档原条目（保留不动） ---- */
  { id: 'sanya_qingbuliang', name: '清补凉', icon: '🍧', tag: '食', type: '美食', price: 15, desc: '椰奶打底，红豆绿豆西瓜芋圆鹌鹑蛋十几种料。三亚夜宵的灵魂，一碗下去暑气全消。' },
  { id: 'sanya_yeziji', name: '椰子鸡火锅', icon: '🍗', tag: '食', type: '美食', price: 150, desc: '三个椰子水倒进锅里，文昌鸡块一涮即熟。蘸沙姜金桔酱油，清甜鲜嫩，火锅界的一股清流。' },
  { id: 'sanya_haixian', name: '第一市场海鲜加工', icon: '🦞', tag: '食', type: '美食', price: 120, desc: '自选龙虾、和乐蟹、芒果螺，拎到加工店清蒸椒盐。人均百元吃一桌硬壳海鲜，防"刺客"认准官方指导价。' },
  { id: 'sanya_wenchangji', name: '文昌鸡', icon: '🐔', tag: '食', type: '美食', price: 58, desc: '海南四大名菜之首，白切做法配桔子酱油。皮黄肉嫩骨酥，椰林里散养的鸡自带果香。' },
  { id: 'sanya_yezifan', name: '椰子饭', icon: '🍚', tag: '食', type: '美食', price: 25, desc: '糯米塞进整颗椰壳蒸透，切开带着椰香船形。糯米吸饱椰汁，甜糯喷香，黎家待客主食。' },
  { id: 'sanya_hainanfen', name: '海南粉', icon: '🍜', tag: '食', type: '美食', price: 12, desc: '腌粉浇牛肉干、花生、竹笋卤汁，拌开满口咸鲜。配一碗海螺清汤，"腌粉加汤"是本地吃法暗号。' },
  { id: 'sanya_yezidong', name: '椰子冻', icon: '🥥', tag: '食', type: '美食', price: 15, desc: '整颗椰子里凝出椰奶冻，插勺即食。冰镇后清甜滑嫩，椰香是别处模仿不出的热带浓度。' },
  { id: 'sanya_xianyezi', name: '现开椰青', icon: '🌴', tag: '食', type: '饮品', price: 12, desc: '路旁椰摊一刀开壳，插吸管直接喝。清甜椰水配椰肉，躺在沙滩上喝才是三亚的"标准姿势"。' },
  { id: 'sanya_mangguozhi', name: '鲜榨芒果汁', icon: '🥤', tag: '食', type: '饮品', price: 10, desc: '本地贵妃芒果现榨，浓稠到需要用勺。不加一滴水，是热带水果对榨汁机的诚意。' },
  { id: 'sanya_yongyi', name: '度假泳衣', icon: '👙', tag: '衣', type: '服饰', price: 100, desc: '三亚的第一件"装备"。沙滩上人字拖配花泳衣，防晒衫颜色越亮越好——海岛滤镜从穿衣开始。' },
  { id: 'sanya_jiushengquan', name: '救生圈租赁', icon: '🛟', tag: '玩', type: '体验', price: 30, desc: '抱着泳圈漂在大东海，浪来了就尖叫。不会游泳也能"下海"，救生员的哨声是全场的保险。' },
  { id: 'sanya_chonglang', name: '冲浪板租赁·教学', icon: '🏄', tag: '玩', type: '体验', price: 150, desc: '后海村冲浪教学两小时，从趴板划水到成功起乘。摔进海里八次、站起来一次，从此上头。' },
  { id: 'sanya_youting', name: '游艇出海半日', icon: '🛥️', tag: '玩', type: '体验', price: 300, desc: '登上游艇驶向深蓝，甲板上晒太阳、碰杯。船长说运气好能见海豚——话音刚落，浪里真有银光。' },
  { id: 'sanya_kuaiting', name: '快艇香蕉船', icon: '🚤', tag: '玩', type: '体验', price: 100, desc: '快艇拖着香蕉船急转弯，全船人挨个"落水"。海水灌进嘴里是咸的，笑声是真的大。' },
  { id: 'sanya_fuqian', name: '浮潜看珊瑚', icon: '🤿', tag: '玩', type: '体验', price: 180, desc: '咬住呼吸管把脸埋进海里，珊瑚丛和小丑鱼就在眼前。上船后第一句话都是：里面居然是另一个世界。' },
  { id: 'sanya_haidiao', name: '出海海钓', icon: '🎣', tag: '玩', type: '体验', price: 250, desc: '渔船带你去近海礁区，抛竿等鱼咬钩。钓上一条金线鱼能吹一年，船上现烤就是舌尖上的战利品。' },
  { id: 'sanya_ganhai', name: '赶海抓蟹摸螺', icon: '🦀', tag: '玩', type: '体验', price: 80, desc: '退潮后的滩涂是天然宝库，翻石头找螃蟹、追寄居蟹、摸海螺。小桶装满才舍得上岸。' },
  { id: 'sanya_tangyi', name: '沙滩遮阳伞躺椅', icon: '⛱️', tag: '玩', type: '体验', price: 50, desc: '租一把伞两张躺椅，冰椰子一放，躺平一下午。听浪声吹海风，才是度假的本体。' },
  { id: 'sanya_haijing_hotel', name: '亚龙湾海景酒店', icon: '🏨', tag: '住', type: '住宿', price: 700, desc: '推窗是私人沙滩与无边泳池连成一线。清晨在鸟叫和浪声里醒来，度假感从睁眼那刻拉满。' },
  /* ---- 新扩充：本地好物 ---- */
  { id: 'syag_yezitang', name: '椰糖椰子片礼盒', icon: '🍬', tag: '食', type: '特产', price: 40, desc: '新鲜椰肉烘成脆片，厚椰糖甜而不腻。带一盒回大陆，泡面里丢两片，也飘着海岛的甜。' },
  { id: 'syag_huangjiao', name: '黄灯笼辣椒酱', icon: '🌶️', tag: '食', type: '特产', price: 25, desc: '海南独有的黄灯笼椒熬成蒜香辣酱，一小勺辣得人冒汗还停不下嘴。蘸芒果、拌白切鸡都是绝配。' },
  { id: 'syag_shuiguo', name: '当季热带水果礼盒', icon: '🥭', tag: '食', type: '特产', price: 128, desc: '山竹、莲雾、菠萝蜜按斤称好装箱，熟透的甜从果皮往外渗。摊主总要交代：放软了再吃，别进冰箱冻坏了味。' },
  { id: 'syag_chenxiang', name: '海南沉香线香', icon: '🪵', tag: '闻', type: '特产', price: 260, desc: '黎寨老香农慢火熏出的沉香，点一支青烟笔直。屋里飘着木香与海风，恍惚又回到椰林的午后。' },
  { id: 'syag_tengqiao', name: '藤桥排骨', icon: '🍖', tag: '食', type: '美食', price: 68, desc: '海棠湾藤桥镇的名菜，排骨腌足一夜再炸，外酥里嫩还带蒜香。镇上老店一天只出几炉，去晚了就没了。' },
  { id: 'syag_lijin', name: '黎锦织绣方巾', icon: '🧣', tag: '衣', type: '服饰', price: 120, desc: '黎族阿婆在腰机上织出菱形纹，一块方巾要守织半月。世界级非遗，缠在腕上就是黎寨的祝福。' },
  { id: 'syag_yaodiao', name: '海南椰雕茶壶', icon: '🍶', tag: '玩', type: '文创', price: 180, desc: '百年椰雕手艺，把椰壳磨成一把乌亮小壶。灌进热水也不裂，摆在案头是海岛上长出来的器物。' },
  { id: 'syag_beike', name: '贝壳风铃', icon: '🐚', tag: '玩', type: '文创', price: 35, desc: '小东海拾的白贝壳串成风铃，海风一过叮当作响。挂在家门口，每天都能听见三亚的浪。' },
  /* ---- 新扩充：海岛出行与栖居 ---- */
  { id: 'syag_diandong', name: '环岛电动车半日租', icon: '🛵', tag: '行', type: '体验', price: 80, desc: '在椰梦长廊扫码租辆小电驴，沿着湾一路兜风。头发吹成乱草也喊值，这才是海岛度假的正确打开方式。' },
  { id: 'syag_yelang', name: '三亚湾夜游船', icon: '🛳️', tag: '游', type: '体验', price: 220, desc: '入夜驶进灯火包围的海湾，凤凰岛的灯光倒进海里碎成金箔。夜风一吹，整座城的喧嚣都被甩在船尾。' },
  { id: 'syag_minsu', name: '海棠湾椰林民宿', icon: '🛖', tag: '住', type: '住宿', price: 450, desc: '椰林深处的白色小院，推开窗是芭蕉叶和晾着的渔网。清晨被鸟叫喊醒，隔壁渔家正往院里送刚捞回的鱼。' }
);

/* ================= data/cn/huanan/sanya/sya_03_stories.js ================= */
/* 三亚 分册03：奇闻趣事（传说 / 岛上人家 / 度假时代） */
window.SYA_STORIES = window.SYA_STORIES || [];
window.SYA_STORIES.push(
  /* ---- 旧档原条目（保留不动） ---- */
  { id: 'sanya_story_dongbei', name: '东北第四省', icon: '🧣', desc: '三亚街头东北话浓度高到离谱：卖椰子的、开出租的、当导游的都有东北口音。网友认证："东北第四省"实至名归。' },
  { id: 'sanya_story_kena', name: '海鲜"防刺客"指南', icon: '🛡️', desc: '第一市场曾因"海鲜刺客"上热搜，如今官方挂牌指导价、公平秤上墙。买前问价、选连锁加工店，吃得明明白白。' },
  { id: 'sanya_story_tianya', name: '两块石头的排队', icon: '📸', desc: '天涯海角的"天涯"石前永远排长队，每人只给拍三秒。明明海滩上石头一大片，大家偏要挤那一块"正版"。' },
  { id: 'sanya_story_houniao', name: '候鸟老人过春', icon: '🕊️', desc: '每年冬天几十万北方老人飞来三亚过冬，清晨沙滩上打太极、跳交谊舞。三亚湾的日出，见证了他们的第二故乡。' },
  { id: 'sanya_story_wuzhizhou', name: '蜈支洲的前世', icon: '🏝️', desc: '蜈支洲旧名"牛奇洲"，因岛上一种叫"蜈支"的草药得名。曾经只有渔民的岛，如今是潜客心中的"中国马尔代夫"。' },
  { id: 'sanya_story_yezi', name: '椰子的全生命周期', icon: '🥥', desc: '在三亚，椰子从嫩到老各有所用：嫩椰喝水、老椰取肉。本地人笑称：一棵椰树养活半个旅游业，剩下半个靠海。' },
  /* ---- 传说与风物 ---- */
  { id: 'syas_luhuitou', name: '鹿回头的传说', icon: '🦌', desc: '黎族猎手追一头梅花鹿追到海边悬崖，鹿无路可逃，回头化作美丽的黎家少女。两人结为夫妻，这座山便叫鹿回头——三亚最甜的爱情故事。' },
  { id: 'syas_zhuganwu', name: '黎寨的竹竿舞', icon: '💃', desc: '节庆时黎家姑娘把竹竿摆成井字，一开一合敲出节奏。跳的人要踩着点跳进跳出，慢了就被夹住脚，全场笑得直不起腰。' },
  { id: 'syas_changzhuoyan', name: '黎寨的百人长桌宴', icon: '🥘', desc: '黎家婚嫁节庆，全村在椰林下摆起长桌，竹筒饭、烤乳猪、山兰酒一字排开。认识的挨着不认识的坐，酒过三巡就一起唱起黎歌。' },
  { id: 'syas_shuiguojiaoyan', name: '水果蘸辣椒盐', icon: '🧂', desc: '三亚水果摊的隐藏吃法：青芒果、番石榴切块蘸辣椒盐，咸辣一激，果酸全变成甜。外地人皱眉，本地人一根竹签吃得嘶哈响。' },
  { id: 'syas_taifeng', name: '台风天的三亚', icon: '🌀', desc: '夏秋台风一来，停航停课又停工，超市的泡面椰水被扫空。风眼过境的片刻天会突然放晴，等第二面风墙砸下，满街都是断椰叶。' },
  { id: 'syas_tieluduohai', name: '火车坐船过海', icon: '🚂', desc: '从大陆开来海南岛的列车，到了琼州海峡北岸会被拆成几段送上渡轮，摇摇晃晃"坐船"过海，到岛上再接起来开往三亚。' },
  /* ---- 岛上人家 ---- */
  { id: 'syas_danjia', name: '疍家渔排人家', icon: '🛶', desc: '疍家人世代以船为家，在港湾里搭起成片渔排，吃喝拉撒全在水上。小孩在甲板间蹿跳长大，渔排餐厅的鱼虾还养在脚下的网箱里。' },
  { id: 'syas_xiadaomingbing', name: '西岛女民兵', icon: '⚓', desc: '上世纪六七十年代，西岛渔家姑娘成立民兵连守岛。她们扛着炮在浪里操练，八姐妹炮班的故事传遍全国，如今岛上还留着纪念园。' },
  { id: 'syas_bailuhuijia', name: '白鹭把家搬回市区', icon: '🪶', desc: '三亚河治理前又臭又挤，白鹭几乎绝迹。清淤复绿种红树林之后，成群白鹭飞回市中心筑巢，傍晚市民在岸边看着它们排队归林。' },
  { id: 'syas_yazhou', name: '崖州·流放的尽头', icon: '✒️', desc: '唐宋时官员获罪多被贬来崖州，古人口中的天涯海角原是流放地的代名词。贬官们却在海边办学教耕，把中原的读书声留在了岛上。' },
  { id: 'syas_shanhuzhongshu', name: '海底种珊瑚的人', icon: '🪸', desc: '蜈支洲岛有一群潜水员不下网不捕鱼，改在海底"种树"——把珊瑚幼苗一株株绑上礁石。几年过去，荒芜的海底重新长出了彩色花园。' },
  { id: 'syas_houshan', name: '后海村的翻身', icon: '🏄', desc: '后海曾是安静得卖不出一碗粉的小渔村，直到冲浪客发现这里的浪又软又长。如今板店民宿开满巷子，渔民家的孩子也踩着浪板下了海。' },
  { id: 'syas_hunpai', name: '婚纱照之都', icon: '💍', desc: '三亚是全国旅拍重镇，旺季的海滩像影棚：同一片礁石上好几对新人排队，化妆师补妆、摄影师抢机位，连浪花都得赶趟儿给面子。' },
  { id: 'syas_bohou', name: '博后村的民宿', icon: '🛌', desc: '亚龙湾旁的博后村曾是耕地少得可怜的渔村，年轻人往外跑。如今村民把老屋改成民宿，院子修起泳池，成了海南出名的民宿第一村。' },
  /* ---- 度假时代 ---- */
  { id: 'syas_xiajiaozhi', name: '沙滩下饺子', icon: '🥟', desc: '春节和暑假的大东海，下饺子三个字是写实：水里的、岸上的、撑伞的都挤成一片。本地人笑一笑，转身去了人少的小东海。' },
  { id: 'syas_dianying', name: '一部电影带火一座山', icon: '🎬', desc: '《非诚勿扰》里的过江龙索桥和鸟巢木屋拍完就火了。电影上映那年，森林公园的索道排队排到山脚，连桥上摇晃都成了打卡项目。' },
  { id: 'syas_haitangwan', name: '海棠湾的变脸', icon: '🌃', desc: '二十年前海棠湾还是疍家渔火照着的荒滩，如今免税城和酒店群的灯光把夜空染亮。老渔民说，夜里分不清哪盏是船灯哪盏是霓虹。' }
);

/* ================= data/cn/huanan/sanya/sanya.js ================= */
/* ============ 三亚（完全版·分册组装） ============
 * 分册：sya_01地点 / sya_02周边 / sya_03趣事。
 * 三条叙事线：热带海岛 / 黎苗风情 / 度假天堂。
 */
(function () {
  window.TRAVEL_CITIES = window.TRAVEL_CITIES || [];
  window.TRAVEL_CITIES.push({
    id: 'sanya',
    name: '三亚',
    country: '中国',
    cc: 'CN',
    province: '海南',
    flag: '🇨🇳',
    region: '华南',
    hero: '🌴',
    desc: '中国的热带天堂：椰风、白沙、碧海。潜入蜈支洲的珊瑚花园，赶一次退潮的海，傍晚捧一颗现开的椰青看日落。',
    travel: [{ name: '飞机', icon: '✈️', cost: 1100 }, { name: '高铁', icon: '🚄', cost: 690 }],
    visa: null,
    spots: (window.SYA_SPOTS = window.SYA_SPOTS || []),
    souvenirs: (window.SYA_GIFTS = window.SYA_GIFTS || []),
    stories: (window.SYA_STORIES = window.SYA_STORIES || []),
  });
})();

/* ================= data/cn/huanan/shenzhen/szn_01_spots.js ================= */
/* 深圳 分册01：景点圣地（山海/特区地标/科技之城/主题乐园）
 * 沿用旧档 7 个原景点条目（shenzhen_ 前缀）+ 新增 19 个（id: sznp_ 前缀）。 */
window.SZN_SPOTS = window.SZN_SPOTS || [];
window.SZN_SPOTS.push(
  { id: 'shenzhen_shijie', name: '世界之窗', icon: '🌍', price: 220, desc: '"一天环游世界"，埃菲尔铁塔按1:3复刻。微缩景观+文化表演，夜场烟花更浪漫。' },
  { id: 'shenzhen_huanlegu', name: '欢乐谷·锦绣中华', icon: '🎢', price: 230, desc: '欢乐谷木质过山车"雪域雄鹰"俯冲尖叫。锦绣中华微缩中华景观，"一步一城"。' },
  { id: 'shenzhen_dameisha', name: '大梅沙·较场尾', icon: '🏖️', price: 0, desc: '免费海滨浴场沙软浪缓。较场尾民宿彩墙如童话小镇，"深圳的海"。' },
  { id: 'shenzhen_lianhuashan', name: '莲花山·深圳湾公园', icon: '🌳', price: 0, desc: '莲花山顶广场俯瞰市民中心，"深圳天际线机位"。深圳湾骑行海边栈道，日落看候鸟。' },
  { id: 'shenzhen_huaqiangbei', name: '华强北·深圳博物馆', icon: '💻', price: 0, desc: '"中国电子第一街"，手机配件宇宙。深圳博物馆讲"深圳速度"，改革开放的奇迹现场。' },
  { id: 'shenzhen_guangchang', name: '平安金融中心云际观光层', icon: '🏙️', price: 200, desc: '600米"深圳之巅"，116层观光层。云上深圳+Free Sky 观光，玻璃栈道悬空。' },
  { id: 'shenzhen_gankeng', name: '甘坑客家小镇·大鹏所城', icon: '🏘️', price: 0, desc: '客家围屋与明清海防所城。大鹏所城"将军村"，较场尾就在旁边。' },
  /* ---- 特区地标与山海 ---- */
  { id: 'sznp_lianhua_dxp', name: '莲花山公园·邓小平像', icon: '🗽', price: 0, desc: '山顶广场的邓小平铜像面朝深圳中轴线，登高者常来献花留影。俯瞰市民中心楼群，那曲"春天的故事"就从脚下铺开。' },
  { id: 'sznp_dengguangxiu', name: '深圳湾灯光秀', icon: '🌃', price: 0, desc: '入夜后深圳湾沿岸楼宇联播灯光秀，人才公园海边是最佳机位。整片湾区倒映进海面，深圳把夜景做成名片。' },
  { id: 'sznp_gaigekai', name: '深圳改革开放展览馆', icon: '📜', price: 0, desc: '"大潮起珠江"常设展，把特区四十年装进一个馆。国贸三天一层楼的老照片、蛇口开山炮，看得人心潮难平。' },
  { id: 'sznp_zhongying', name: '中英街', icon: '🛍️', price: 0, desc: '一条街横跨深港两制，界碑立在街心成了必打卡点。老铺卖着港货零食，百米老街浓缩了百年边贸史。' },
  { id: 'sznp_qianhai', name: '前海石公园', icon: '🏗️', price: 0, desc: '前海是"特区中的特区"，前海石见证滩涂变新城。隔海望去摩天轮缓缓转动，深圳仍在向海生长。' },
  { id: 'sznp_nantou', name: '南头古城', icon: '🏘️', price: 0, desc: '深圳的"城市之根"，东晋设宝安县时这里就有人烟。城墙根下潮牌店与咖啡馆共生，老砖瓦讲着年轻城的前世。' },
  { id: 'sznp_chiwan', name: '赤湾天后宫', icon: '⛩️', price: 0, desc: '赤湾山下的妈祖庙香火绵延数百年，郑和下西洋曾来祭祀。古庙面朝伶仃洋，守着深圳最早的出海记忆。' },
  /* ---- 山海与自然 ---- */
  { id: 'sznp_rencai', name: '深圳人才公园', icon: '🌟', price: 0, desc: '全国首座人才主题公园，星光桥镌刻着深圳的功勋人物。黄昏看日落、入夜赏灯光秀，是湾区夜景的免费机位。' },
  { id: 'sznp_xichong', name: '西涌海滩', icon: '🌌', price: 30, desc: '深圳最长的沙滩，玻璃海水配细软沙。白天冲浪赶海，入夜走向天文台观星，大鹏的蓝可以看上一整天。' },
  { id: 'sznp_xiaomeisha', name: '小梅沙', icon: '🏖️', price: 50, desc: '大鹏湾畔的"东方夏威夷"，沙滩细白海水澄澈。海洋世界与度假酒店环湾而建，是深圳人最念旧的海边。' },
  { id: 'sznp_wutongshan', name: '梧桐山', icon: '⛰️', price: 0, desc: '鹏城第一峰，好汉坡直上九百四十三米。山顶云海翻涌时，深圳湾与香港群山同框，是登山客的周末天堂。' },
  { id: 'sznp_xianhu', name: '仙湖植物园·弘法寺', icon: '🌿', price: 15, desc: '梧桐山脚的植物王国，化石森林与仙人掌温室最出片。半山弘法寺香火旺盛，湖光山色里上炷平安香。' },
  { id: 'sznp_haishang', name: '海上世界', icon: '🛳️', price: 0, desc: '远洋客轮明华轮泊进蛇口，成为夜生活的中心。邓小平题字仍在船身，音乐喷泉与酒吧街把海风衬得热闹。' },
  { id: 'sznp_wanqu', name: '欢乐港湾·湾区之光', icon: '🎡', price: 100, desc: '宝安湾畔的摩天轮高一百二十八米，名叫"湾区之光"。转到最高处，前海湾的日落与城市灯火同框入画。' },
  { id: 'sznp_chunsun', name: '华润大厦"春笋"', icon: '🌇', price: 0, desc: '形如春笋的华润大厦在深圳湾畔拔节而上。傍晚塔身映着霞光，从人才公园望过去，就是一幅现代山海图。' },
  /* ---- 科技之城与主题乐园 ---- */
  { id: 'sznp_kejiyuan', name: '深圳湾科技园·腾讯滨海大厦', icon: '🏢', price: 0, desc: '两栋弧形塔楼并肩的腾讯滨海大厦立在深圳湾畔。入夜后科技园灯火通明，这座城市最年轻的野心都在加班。' },
  { id: 'sznp_dajiang', name: '大疆"天空之城"', icon: '🚁', price: 0, desc: '悬挑结构层层托起空中花园，是大疆全球总部大楼。无人机之都的地标建筑，科幻感像随时会起飞。' },
  { id: 'sznp_oct', name: '华侨城创意园', icon: '🎨', price: 0, desc: '旧厂房改出的文艺街区，涂鸦墙、独立书店藏在树荫里。周末创意市集人潮涌动，是深圳青年的精神地标。' },
  { id: 'sznp_dongbu', name: '东部华侨城', icon: '🚡', price: 180, desc: '大侠谷与茶溪谷双谷相依，云海索道把山海拉近。茵特拉根小镇像欧洲一角，是深圳人的度假后花园。' }
);

