/* ================= data/cn/huazhong/changsha/cs_01_spots.js ================= */
/* 长沙 分册01：景点圣地（湘江橘子洲/岳麓文脉/市井娱乐/湖湘郊野） */
window.CS_SPOTS = window.CS_SPOTS || [];
window.CS_SPOTS.push(
  /* ---- 湘江与橘子洲（沿用原条目） ---- */
  { id: 'changsha_juzizhou', name: '橘子洲头', icon: '🍊', price: 0, desc: '湘江中的长岛，青年毛泽东雕像凝望远方。"独立寒秋，湘江北去，橘子洲头"，周六晚焰火照亮江面。' },
  { id: 'changsha_tianxin', name: '天心阁·杜甫江阁', icon: '🏯', price: 32, desc: '天心阁是古城墙遗存，"潇湘古阁"。杜甫江阁看湘江焰火最佳机位，周六晚人山人海。' },
  { id: 'csp_xiangjiang', name: '湘江风光带·风帆广场', icon: '🌊', price: 0, desc: '沿江步道从橘子洲头一路铺开，夜跑、遛弯、看焰火都在这。傍晚江面镀金，长沙人的城市阳台。' },
  { id: 'csp_kaifu', name: '开福寺', icon: '🛕', price: 0, desc: '湘江边的千年古刹，明清大雄宝殿香火鼎盛。寺里的素面与桂花糕有名，庙会时人挤人。' },
  /* ---- 岳麓文脉（沿用原条目） ---- */
  { id: 'changsha_yuelu', name: '岳麓山·岳麓书院', icon: '⛰️', price: 0, desc: '"千年学府"岳麓书院"惟楚有材，于斯为盛"。爱晚亭"停车坐爱枫林晚"，秋天红枫满山。' },
  { id: 'csp_aiwan', name: '爱晚亭·穿石坡湖', icon: '🍁', price: 0, desc: '爱晚亭飞檐翘角立在清风峡，亭名取自杜牧诗句、匾额由毛泽东题写。深秋枫叶红了整片山谷。' },
  { id: 'csp_diyishifan', name: '湖南第一师范', icon: '📚', price: 0, desc: '青年毛泽东在此求学八年，"恰同学少年"的母校。灰墙黛瓦的城南书院旧址，教室里还留着当年的课桌。' },
  { id: 'csp_houhu', name: '后湖国际艺术园', icon: '🎨', price: 0, desc: '岳麓山下的老村落改造成艺术家聚落，工作室与画廊藏在巷子里。湖边咖啡店看展发呆，文艺浓度高。' },
  /* ---- 市井与娱乐（沿用原条目） ---- */
  { id: 'changsha_wenheyou', name: '超级文和友', icon: '🏙️', price: 0, desc: '把80年代老长沙社区"搬"进商场七层。排队三小时，拍照两小时，"市井沉浸式游乐场"。' },
  { id: 'changsha_jiefangxi', name: '解放西路·太平老街', icon: '🏮', price: 0, desc: '长沙夜生活的心脏，凌晨三点还堵车。太平街贾谊故居与臭豆腐老铺，"古老与嗨混在一起"。' },
  { id: 'csp_huogongdian', name: '火宫殿·坡子街', icon: '🏮', price: 0, desc: '火宫殿是长沙小吃的祖庙，庙前坪里臭豆腐、糖油粑粑摆满摊。坡子街老字号林立，毛爷爷当年也来"打卡"。' },
  { id: 'csp_mifenjie', name: '湖南米粉街', icon: '🍜', price: 0, desc: '一条街集合湖南各地米粉：常德牛肉粉、津市粉、攸县粉。街口的大碗雕塑是嗦粉合影C位。' },
  { id: 'csp_hualongchi', name: '化龙池清吧街', icon: '🎸', price: 0, desc: '麻石老巷里的酒吧街，民谣歌手抱着吉他唱到凌晨。比解放西安静，是老巷子里泡出来的文艺夜。' },
  { id: 'csp_baishajing', name: '白沙古井', icon: '💧', price: 0, desc: '一眼古井涌了上千年，市民提着桶排队打水。井水清甜泡茶最好，长沙人的"自来水"在井边。' },
  /* ---- 博物馆与红色记忆（沿用原条目） ---- */
  { id: 'changsha_bo', name: '湖南博物院', icon: '🏺', price: 0, desc: '马王堆汉墓：辛追夫人两千年不腐，素纱襌衣仅49克。"一票难求"的顶级博物馆，提前一周抢约。' },
  { id: 'csp_binjiang', name: '滨江文化园·三馆一厅', icon: '🏛️', price: 0, desc: '长沙博物馆、图书馆、规划馆与音乐厅扎堆湘江北岸。博物馆里的长沙窑与青铜器，把楚地讲透。' },
  { id: 'csp_lizijian', name: '李自健美术馆', icon: '🖼️', price: 0, desc: '湖畔的清水混凝土建筑群，油画《南京大屠杀》震撼人心。旁边的谢子龙影像馆也值得一逛。' },
  /* ---- 娱乐新地标与郊野（沿用原条目+新增） ---- */
  { id: 'changsha_meixihu', name: '梅溪湖·谢子龙影像馆', icon: '📷', price: 0, desc: '梅溪湖城市岛双螺旋观景台出片。谢子龙影像艺术馆的清水混凝土建筑，文艺打卡顶流。' },
  { id: 'csp_hunan_tv', name: '湖南广电·马栏山', icon: '📺', price: 0, desc: '芒果台的演播楼是追星圣地，粉丝在广电门口守候。马栏山视频文创园里，可能偶遇刚下班的综艺团队。' },
  { id: 'csp_yuren', name: '渔人码头', icon: '🍻', price: 0, desc: '湘江西岸的欧式街区，晚上江景餐吧与夜宵摊一字排开。吹着江风吃小龙虾，长沙夏天的快乐模板。' },
  { id: 'csp_yanghu', name: '洋湖湿地公园', icon: '🪷', price: 0, desc: '城市的绿肺，芦苇荡与荷塘接天。湿地科普馆里看候鸟，周末露营野餐，长沙市区的慢生活。' },
  { id: 'csp_tongguan', name: '长沙铜官窑', icon: '🏺', price: 0, desc: '唐代长沙窑就在铜官，瓷器上写诗、画椰枣纹，远销西亚。古镇里看龙窑遗址，"黑石号"沉船文物在此展出。' },
  { id: 'csp_jinggang', name: '靖港古镇', icon: '🏘️', price: 0, desc: '沩水入湘江口的千年古镇，麻石街与老码头保存完好。曾国藩曾在此练兵，糖油粑粑与皮影戏是老招牌。' },
  { id: 'csp_dawei', name: '大围山', icon: '⛰️', price: 0, desc: '浏阳的"湘东绿色明珠"，五月高山杜鹃开满山坡。夏天避暑看日出云海，冬天还能看雪。' },
  { id: 'csp_huaming', name: '花明楼·刘少奇故里', icon: '🏛️', price: 0, desc: '宁乡花明楼炭子冲，刘少奇故居与纪念馆静立青山间。铜像广场开阔，红色研学常来之地。' },
  { id: 'csp_huitang', name: '灰汤温泉', icon: '♨️', price: 130, desc: '宁乡灰汤温泉自古有名，"灰汤贡鸭"都带温泉味。山间泡汤看竹海，秋冬最是惬意。' }
);

/* ================= data/cn/huazhong/changsha/cs_02_gifts.js ================= */
/* 长沙 分册02：特色周边（湘菜江湖/长沙小吃/湘绣铜官/夜都体验） */
window.CS_GIFTS = window.CS_GIFTS || [];
window.CS_GIFTS.push(
  /* ---- 湘菜与小吃（沿用原条目） ---- */
  { id: 'changsha_xiangcai', name: '湘菜：剁椒鱼头', icon: '🌶️', tag: '食', type: '美食', price: 88, desc: '红剁椒铺满大鱼头，蒸出鲜辣。配一份"金汤"拌面，"湘菜之魂"。' },
  { id: 'changsha_choudoufu', name: '黑色经典臭豆腐', icon: '🧆', tag: '食', type: '美食', price: 12, desc: '黑得发亮、灌汤爆汁的长沙臭豆腐。浇蒜水辣椒萝卜丁，"闻着臭吃着上头"。' },
  { id: 'changsha_xiaolongxia', name: '文和友口味虾', icon: '🦞', tag: '食', type: '美食', price: 128, desc: '口味虾麻辣鲜香，吮指程度五颗星。配紫苏与冰啤酒，长沙夜宵的"三件套"。' },
  { id: 'changsha_dabing', name: '糖油粑粑·大香肠', icon: '🍡', tag: '食', type: '美食', price: 10, desc: '糖油粑粑糯米炸得金黄流糖。老长沙大香肠"比手臂短比脸长"，李公庙排队三十年。' },
  { id: 'changsha_zhou', name: '周记凉面', icon: '🍜', tag: '食', type: '美食', price: 15, desc: '长沙凉面麻酱香浓，嗦一碗"透心凉"。夏天的老街必备，配糖水铺的绿豆沙。' },
  { id: 'csg_mifen', name: '长沙米粉', icon: '🍜', tag: '食', type: '美食', price: 12, desc: '圆粉扁粉任选，码子现炒现盖。原汤粉配剁辣椒，嗦完还要喝口汤，长沙人的清晨标配。' },
  { id: 'csg_suoluo', name: '唆螺', icon: '🐚', tag: '食', type: '美食', price: 20, desc: '田螺剪尾加紫苏辣椒爆炒，用嘴"唆"出螺肉。夜宵摊上的功夫活，唆得越响越有味。' },
  { id: 'csg_gualiangfen', name: '刮凉粉', icon: '🍜', tag: '食', type: '美食', price: 8, desc: '凉粉在井字刀上刮成细条，浇辣椒油醋汁。夏天街头来一碗，酸辣开胃透心凉。' },
  { id: 'csg_maoshi', name: '毛氏红烧肉', icon: '🍖', tag: '食', type: '美食', price: 60, desc: '不用酱油、全靠糖色炒出的红烧肉，肥而不腻。据说毛主席最爱这一口，"毛氏"成了湘菜招牌。' },
  { id: 'csg_shaokao', name: '湘西小串烧烤', icon: '🍢', tag: '食', type: '美食', price: 40, desc: '湘西小串细签慢烤，牛肉牛油玉米粒一把一把上。解放西夜宵的烟火，都在烤炉边上。' },
  /* ---- 湖湘风物（沿用原条目） ---- */
  { id: 'changsha_chayan', name: '茶颜悦色', icon: '🧋', tag: '食', type: '饮品', price: 20, desc: '"幽兰拿铁"奶油顶碧根果碎，中式奶茶开创者。全国独一份的"长沙限定"，离长沙就想它。' },
  { id: 'csg_duojiao', name: '剁辣椒·豆豉', icon: '🌶️', tag: '食', type: '特产', price: 20, desc: '红椒剁碎盐渍，酸辣开胃。湖南人的厨房里，一坛剁辣椒能配一切，拌饭炒菜皆是乡愁。' },
  { id: 'csg_jiangbanya', name: '酱板鸭', icon: '🦆', tag: '食', type: '特产', price: 50, desc: '鸭子卤后风干再酱，肉紧味浓、辣得够劲。撕一条慢慢嚼，湖南特产的"重口味担当"。' },
  { id: 'csg_heicha', name: '安化黑茶', icon: '🍵', tag: '食', type: '特产', price: 60, desc: '安化千两茶、茯砖茶压成砖，陈香醇厚。湖南黑茶走茶马古道，一块茶砖能喝一年。' },
  { id: 'csg_chayan_libao', name: '茶颜悦色伴手礼', icon: '🎁', tag: '食', type: '特产', price: 45, desc: '茶颜的茶包与联名周边礼盒，把"幽兰拿铁"的茶香带回家。长沙限定，出了省买不到。' },
  /* ---- 湘绣与匠人手信（沿用原条目+新增） ---- */
  { id: 'changsha_shouwang', name: '守艺人湘绣', icon: '🪡', tag: '衣', type: '文创', price: 150, desc: '湘绣"绣鸟能听声，绣虎能奔跑"。鬅毛针法绣狮虎，四大名绣的"动态派"。' },
  { id: 'changsha_wenwan', name: '浏阳花炮·菊花石', icon: '🎆', tag: '衣', type: '文创', price: 60, desc: '浏阳花炮"世界花炮之乡"。菊花石天然开花纹理，"石头里的菊花"。' },
  { id: 'changsha_mao', name: '毛主席纪念文创', icon: '🟥', tag: '衣', type: '文创', price: 40, desc: '橘子洲头青年艺术雕像徽章、红书签。红色旅游城市的纪念品，"恰同学少年"。' },
  { id: 'csg_tongguanci', name: '铜官窑茶盏', icon: '🏺', tag: '玩', type: '文创', price: 80, desc: '长沙铜官窑的褐彩茶盏，盏上还能题诗句。唐代外销瓷的老手艺，端在手里就是一段海上丝路。' },
  { id: 'csg_xiabu', name: '浏阳夏布', icon: '🧺', tag: '玩', type: '文创', price: 60, desc: '苎麻织的夏布透气清凉，做成手帕茶席。老手艺织了一千年，摸上去是夏天的触感。' },
  /* ---- 夜都与体验（沿用原条目+新增） ---- */
  { id: 'changsha_juhua', name: '橘子洲焰火观赏', icon: '🎆', tag: '玩', type: '体验', price: 0, desc: '每周六晚焰火在湘江上空绽放十五分钟。杜甫江阁与风帆广场是最佳机位，人潮与浪漫齐飞。' },
  { id: 'changsha_yeyu', name: '解放西夜生活之旅', icon: '🍻', tag: '玩', type: '体验', price: 100, desc: '清吧、livehouse、夜宵摊一晚串完。长沙人"越夜越精神"，凌晨三点还在嗦粉。' },
  { id: 'changsha_guibu', name: '嗦粉晨间之旅', icon: '🍜', tag: '玩', type: '体验', price: 25, desc: '长沙米粉"圆的扁的"任选，码子盖码现炒。原味粉配剁辣椒，"长沙的早晨从嗦粉开始"。' },
  { id: 'csg_caidi', name: '湘菜大师课', icon: '👨‍🍳', tag: '玩', type: '体验', price: 150, desc: '跟湘菜师傅学炒一道辣椒炒肉或剁椒鱼头。锅气腾腾里明白：湘菜的精髓就是"下饭"。' },
  { id: 'csg_xiangjiangyou', name: '湘江夜游', icon: '⛴️', tag: '玩', type: '体验', price: 100, desc: '游船从橘子洲码头出发，两岸灯光与焰火倒映江面。江风吹过，星城的夜比想象中更亮。' },
  { id: 'csg_xiaogong', name: '笑工场相声', icon: '🎤', tag: '玩', type: '体验', price: 80, desc: '大兵领衔的长沙本土相声，长沙话包袱抖得响。笑到肚子疼，还学会了两句"塑普"。' },
  { id: 'csg_zuliao', name: '长沙足疗体验', icon: '🦶', tag: '玩', type: '体验', price: 100, desc: '"脚都"名不虚传：按脚、修脚、泡脚一条龙。逛了一天解放西，最后在足疗店"续命"。' },
  { id: 'changsha_minsu', name: '五一广场民宿', icon: '🏨', tag: '住', type: '住宿', price: 300, desc: '五一商圈高空民宿，落地窗看摩天楼霓虹。楼下就是太平街，夜宵下楼即达。' }
);

/* ================= data/cn/huazhong/changsha/cs_03_stories.js ================= */
/* 长沙 分册03：奇闻趣事（楚地文脉/湖湘风云/市井娱乐/烟火节庆） */
window.CS_STORIES = window.CS_STORIES || [];
window.CS_STORIES.push(
  /* ---- 楚地文脉 ---- */
  { id: 'changsha_story_yuelu', name: '岳麓书院的千年讲堂', icon: '📜', desc: '岳麓书院创办于976年，至今仍在办学。"惟楚有材，于斯为盛"的对联，是中国书院的天花板。' },
  { id: 'css_zhuzhang', name: '朱张会讲的盛况', icon: '📖', desc: '南宋朱熹与张栻在岳麓书院会讲，"三日夜不能合"，四方学子骑马而来、饮马湘江。中国思想史的高光，就在这间讲堂。' },
  { id: 'css_aiwan', name: '爱晚亭的名字', icon: '🍁', desc: '亭名取自杜牧"停车坐爱枫林晚"，匾额由毛泽东手书。青年毛泽东常与同学在亭中读书，爱晚亭从此带上传奇。' },
  { id: 'css_baisha', name: '白沙古井打水人', icon: '💧', desc: '白沙井水千年不竭，每天清晨都有市民拎着大桶排队。井水泡茶清甜回甘，长沙人的讲究藏在老井边。' },
  { id: 'changsha_story_xinzhu', name: '辛追夫人的"时间胶囊"', icon: '🏺', desc: '马王堆辛追夫人出土时皮肤有弹性、血管可见。素纱襌衣49克，"叠十层还能看报纸"。' },
  /* ---- 湖湘风云 ---- */
  { id: 'css_wenxi', name: '文夕大火的伤疤', icon: '🔥', desc: '1938年"焦土抗战"烧起文夕大火，古城三天三夜成灰。天心阁重建如昨，城墙上的火痕提醒后人勿忘。' },
  { id: 'css_huogong', name: '火宫殿与毛主席的臭豆腐', icon: '🧆', desc: '火宫殿的臭豆腐名扬天下，当年毛主席回长沙专程去尝，赞了一句"火宫殿的臭豆腐还是好吃"。一句话火了七十年。' },
  { id: 'css_yishi', name: '毛泽东在第一师范', icon: '📚', desc: '青年毛泽东在一师范求学八年：洗冷水浴、办夜校、读"无字之书"。他在日记里写"与天奋斗其乐无穷"，豪气从此处起步。' },
  { id: 'css_tongguan', name: '铜官窑与"黑石号"', icon: '🚢', desc: '1998年印尼海域打捞出唐代沉船"黑石号"，六万多件瓷器大多来自长沙窑。原来一千年前，长沙的茶碗就卖到了波斯湾。' },
  { id: 'css_huapao', name: '浏阳花炮的祖师', icon: '🎆', desc: '传说唐代李畋为驱除瘟疫，用竹筒装硝引爆，"爆竹"由此而来。浏阳人尊李畋为祖师，花炮一响传了一千三百年。' },
  /* ---- 市井娱乐 ---- */
  { id: 'changsha_story_chayan', name: '茶颜悦色为什么不出省', icon: '🧋', desc: '茶颜悦色十年坚守长沙，"供应链配不上野心"曾上热搜。如今出了省，长沙人还是最爱"家门口的"。' },
  { id: 'changsha_story_ye', name: '不夜城的基因', icon: '🌃', desc: '长沙夜经济全国第一梯队，解放西凌晨仍堵车。"娱乐之都"的底气：夜宵、酒吧、洗脚城一条龙。' },
  { id: 'changsha_story_juzi', name: '橘子洲的焰火情', icon: '🎆', desc: '橘子洲焰火每周六燃放，"长沙的浪漫周更"。湘江两岸大桥上站满人，"全城抬头"。' },
  { id: 'changsha_story_wenheyou', name: '文和友的"怀旧生意"', icon: '🏙️', desc: '超级文和友复刻80年代长沙社区，老物件真从拆迁房收来。年轻人排队拍照，"贩卖回忆"的门道。' },
  { id: 'css_mangguo', name: '湖南卫视与"快乐"工厂', icon: '📺', desc: '马栏山的芒果台造出《快乐大本营》《天天向上》，捧红一代代主持人。"马栏坡"成了中国娱乐的地名梗。' },
  { id: 'css_zhudou', name: '"脚都"名号的由来', icon: '🦶', desc: '长沙人爱"洗脚"出了名，足疗店密度全国第一，网友戏称长沙是"脚都"。逛累了的游客，最后都在足疗店躺平。' },
  { id: 'css_supu', name: '长沙"塑普"的幽默', icon: '🗣️', desc: '长沙普通话被戏称"塑料普通话"（塑普），腔调上扬自带喜感。一句"哦改咯"，连吵架都像在说相声。' },
  { id: 'css_mifen', name: '圆粉扁粉之争', icon: '🍜', desc: '长沙人嗦粉分两派：圆粉派和扁粉派谁也说服不了谁。常德牛肉粉、长沙原汤粉各有拥趸，清晨的粉店里争论不断。' },
  { id: 'css_la', name: '湖南人的"不怕辣"', icon: '🌶️', desc: '"四川人不怕辣，贵州人辣不怕，湖南人怕不辣。"剁椒、白辣椒、擂辣椒轮番上阵，无辣不欢是刻进湖南人DNA的。' },
  /* ---- 节庆 ---- */
  { id: 'css_liuyang', name: '浏阳焰火大会', icon: '🎆', desc: '世界焰火大赛在浏阳举行，各国高手把夜空当画布。每逢大赛，小城万人空巷，抬头就是满天繁花。' }
);

/* ================= data/cn/huazhong/changsha/changsha.js ================= */
/* ============ 长沙（完全版·分册组装） ============
 * 分册：cs_01地点 / cs_02周边 / cs_03趣事。
 * 叙事主线：湘江橘子洲 / 岳麓千年文脉 / 湖湘红色 / 不夜娱乐之都。
 */
(function () {
  window.TRAVEL_CITIES = window.TRAVEL_CITIES || [];
  window.TRAVEL_CITIES.push({
    id: 'changsha',
    name: '长沙',
    country: '中国',
    cc: 'CN',
    province: '湖南',
    flag: '🇨🇳',
    region: '华中',
    hero: '🌶️',
    desc: '娱乐之都、快乐星城：橘子洲头的焰火，文和友的市井江湖，茶颜悦色排长队，凌晨三点的解放西路依然人声鼎沸。',
    travel: [{ name: '高铁', icon: '🚄', cost: 160 }, { name: '飞机', icon: '✈️', cost: 600 }],
    visa: null,
    spots: (window.CS_SPOTS = window.CS_SPOTS || []),
    souvenirs: (window.CS_GIFTS = window.CS_GIFTS || []),
    stories: (window.CS_STORIES = window.CS_STORIES || []),
  });
})();

/* ================= data/cn/huazhong/jingzhou/jz_01_spots.js ================= */
/* 荆州 分册01：景点圣地（古城墙/楚文化/三国/江汉胜迹） */
window.JZ_SPOTS = window.JZ_SPOTS || [];
window.JZ_SPOTS.push(
  /* ---- 旧条目：古城墙与楚文化（原样保留） ---- */
  { id: 'jingzhou_chengqiang', name: '荆州古城墙', icon: '🧱', price: 27, desc: '中国保存最完好的古城垣之一，周长11公里。城门楼与瓮城完好，骑一辆自行车环城一圈，砖缝里全是三国故事。' },
  { id: 'jingzhou_bowuguan', name: '荆州博物馆', icon: '🏺', price: 0, desc: '西汉男尸"遂先生"沉睡两千多年肌肤仍有弹性，战国丝绸薄如蝉翼。楚秦汉漆器荟萃，免费参观的宝藏馆。' },
  { id: 'jingzhou_guanyu_miao', name: '关帝庙·关公义园', icon: '⛩️', price: 35, desc: '荆州是关公镇守十年的地方。巨型关公圣像曾是世界最大关公像，城内关帝庙香火数百年不断。' },
  { id: 'jingzhou_zhangju', name: '张居正故居', icon: '🏛️', price: 20, desc: '明代改革家、"宰相之杰"张居正的故里宅院。园林清幽，一边逛一边读懂"一条鞭法"背后的万历朝风云。' },
  { id: 'jingzhou_bingma_yong', name: '楚王车马阵', icon: '🐎', price: 60, desc: '"北有兵马俑，南有车马阵"。楚王陵陪葬车马坑规模惊人，四十乘战车列阵地下，气势直逼秦俑。' },
  { id: 'jingzhou_honghu', name: '洪湖生态旅游区', icon: '🛶', price: 80, desc: '"洪湖水浪打浪"唱的地方。乘船穿行万亩荷塘，夏天采莲蓬、看渔撒网，水乡韵味十足。' },
  { id: 'jingzhou_jiuli', name: '荆街夜市', icon: '🏮', price: 0, desc: '古城旁的夜市新地标，灯笼连成河。锅盔、烧烤、糖水铺子一路排开，本地人遛弯的深夜食堂。' },
  /* ---- 新增：城墙地标与园林（jzp_） ---- */
  { id: 'jzp_binyanglou', name: '宾阳楼', icon: '🏯', price: 25, desc: '城墙东门的二层歇山城楼，登楼可俯瞰明代砖墙一路伸进护城河。传说关羽曾在此阅兵点将，瓮城脚下就是旧时车马入城的古道。' },
  { id: 'jzp_huchenghe', name: '护城河环城步道', icon: '🌊', price: 0, desc: '碧波绕城一整圈的护城河如今是市民乐园，柳荫步道连着石拱桥。黄昏看城楼倒影在水面轻轻晃动，像把古城又慢慢看了一遍。' },
  { id: 'jzp_guanyuci', name: '关羽祠', icon: '🛕', price: 20, desc: '国内首座关羽祠，青瓦红墙立在城墙边。堂内关公抚髯端坐，匾额讲尽忠义，香炉青烟袅袅，把镇守荆州十年的故事说给往来客听。' },
  { id: 'jzp_sanguogongyuan', name: '三国公园', icon: '🎭', price: 0, desc: '城西的三国主题园林，水榭亭台多取典故命名。桃园结义塑像立在湖边，孩子们在点将台上追逐奔跑，湖心岛藏着古城最悠闲的下午。' },
  { id: 'jzp_wanshoubata', name: '万寿宝塔', icon: '🗼', price: 15, desc: '江畔明代的万寿宝塔塔身深陷堤面之下七米，塔基埋进江堤，成了全国罕见的"地上塔身"。八面塔壁嵌满汉白玉佛像，檐角风铃被江风摇响。' },
  { id: 'jzp_zhanghuasi', name: '章华寺', icon: '🏯', price: 0, desc: '沙市古刹章华寺紧邻楚章华台旧址，寺内千年古银杏深秋铺金。相传楚灵王筑台曾夸"台高可望云梦"，如今钟鼓声依旧从古台下飘出。' },
  { id: 'jzp_jinancheng', name: '纪南城遗址·楚都郢', icon: '🏺', price: 0, desc: '楚国都城"郢"就在纪南城，二十代楚王在此定都四百余年。如今只剩起伏的土筑城垣与稻田，走在田埂上，脚下或许就是屈原吟过诗的旧街。' },
  /* ---- 新增：郊野与江汉胜迹（jzp_） ---- */
  { id: 'jzp_weishui', name: '洈水风景区', icon: '⛰️', price: 80, desc: '松滋洈水群山环一湖碧水，四百多座小岛星罗棋布。乘船穿行水上森林，登坝顶看亚洲最大人工土坝横锁峡谷，夏天的风里全是草木香气。' },
  { id: 'jzp_fangte', name: '荆州方特东方神画', icon: '🎢', price: 230, desc: '以楚文化与三国为主题的乐园，楚乐大典在水幕光影里开场。坐上"火烧赤壁"动感飞车，再钻进屈原剧场听离骚吟唱，一天根本逛不完。' },
  { id: 'jzp_yangmatou', name: '沙市洋码头文创园', icon: '🚢', price: 0, desc: '老沙市开埠时代的洋码头厂房改成的滨江文创园，红砖仓库里开满书店与咖啡馆。傍晚江面镀金，铁轨与老吊机还在，近代史从这儿起航。' },
  { id: 'jzp_yuanboyuan', name: '荆州园博园', icon: '🌺', price: 40, desc: '纪南文旅区里的楚国园林大观，楚凤与漆器元素藏进亭台水系。各市展园沿水岸铺开，春天郁金香成片，本地人爱来遛弯看花拍照。' },
  { id: 'jzp_taihuiguan', name: '太晖观', icon: '🛕', price: 10, desc: '城郊太晖观有"赛武当"之称，明代三清殿飞檐斗拱气势犹存。石栏望柱上的小兽憨态可掬，晨钟暮鼓里，古柏与残碑说着江汉平原的香火旧事。' },
  { id: 'jzp_jinjiangting', name: '荆江亭', icon: '🌊', price: 0, desc: '沙市江边的荆江分洪纪念亭，万人筑堤的水利壮举刻在碑上。凭栏看荆江九曲回肠东去，船闸与灯塔提醒你，万里长江最险的一段在此驯服。' },
  { id: 'jzp_dasaixiang', name: '沙市大赛巷', icon: '🍢', price: 0, desc: '沙市人的"过早一条街"，早堂面、凉虾、牛肉米粉从清晨排到晌午。油锅滋滋作响，老板一句"七了冇"的招呼，就是最地道的荆沙味。' },
  /* ---- 新增：辖区县市风物（jzp_） ---- */
  { id: 'jzp_qujiawan', name: '瞿家湾·湘鄂西旧址', icon: '🏚️', price: 0, desc: '洪湖岸边的瞿家湾老街，青石板路串起湘鄂西革命旧址的旧门板。贺龙曾在屋檐下开会，墙上标语斑驳，渔民后代讲起赤卫队还会哼两句。' },
  { id: 'jzp_guanyinji', name: '观音矶', icon: '🪨', price: 0, desc: '荆江最险的矶头伸进江心，千百年来洪水都在此打转。矶上望江亭里看船队缓缓爬坡，才懂"万里长江，险在荆江"这句老话的分量。' },
  { id: 'jzp_miluyuan', name: '石首麋鹿保护区', icon: '🦌', price: 0, desc: '长江故道边的石首麋鹿保护区，上千头"四不像"在芦苇荡里成群奔跑。乘观光车看它们涉水吃草，同一条故道里江豚翻身，是野性荆州的名片。' },
  { id: 'jzp_yuancheng', name: '郢城文化园', icon: '🎋', price: 0, desc: '纪南城外的郢城文化园，用现代光影讲楚人"筚路蓝缕"的创业史。漆画与编钟元素布进园林，夜游时有打铁花与水幕楚舞轮番登场，古老又新鲜。' }
);

/* ================= data/cn/huazhong/jingzhou/jz_02_gifts.js ================= */
/* 荆州 分册02：特色周边（过早小吃/荆楚手信/三国文创） */
window.JZ_GIFTS = window.JZ_GIFTS || [];
window.JZ_GIFTS.push(
  /* ---- 旧条目：荆沙小吃与文创（原样保留） ---- */
  { id: 'jingzhou_guokui', name: '公安锅盔', icon: '🫓', tag: '食', type: '美食', price: 8, desc: '炉壁上烤得鼓起大泡的薄饼，梅干菜鲜肉馅咔嚓掉渣。荆州人从小吃到大，两块钱的祖传快乐。' },
  { id: 'jingzhou_yu_gao', name: '荆州鱼糕', icon: '🐟', tag: '食', type: '美食', price: 35, desc: '"吃鱼不见鱼"的楚乡名菜，鱼肉打成茸蒸成糕。弹嫩鲜滑，是荆州年饭桌上不可动摇的头碗。' },
  { id: 'jingzhou_zao_yang', name: '早堂面', icon: '🍜', tag: '食', type: '美食', price: 12, desc: '沙市人天不亮就吃的"过早之王"。碱水面配酥肥肉、大盘鳝鱼丝，汤头用整夜骨头熬出来。' },
  { id: 'jingzhou_longfeng', name: '龙凤饼·八宝饭', icon: '🍚', tag: '食', type: '美食', price: 28, desc: '散饭豆皮八宝饭甜糯油润，龙凤喜饼皮酥馅香。老荆州婚宴上的"体面点心"，如今随时能吃到。' },
  { id: 'jingzhou_pipa', name: '皮条鳝鱼', icon: '🐍', tag: '食', type: '美食', price: 68, desc: '荆州名菜"皮条鳝鱼"，鳝段炸得酥脆挂糖醋汁。造型像皮条得名，一口"咔嚓"停不下来。' },
  { id: 'jingzhou_tangyuan', name: '米圆子', icon: '🍡', tag: '食', type: '美食', price: 8, desc: '米浆搓的小圆子配酒酿蛋花，甜酒香温润。荆州夜宵摊的"暖胃神器"，三块钱一碗。' },
  { id: 'jingzhou_honghu_l莲', name: '洪湖莲蓬·莲子', icon: '🪷', tag: '食', type: '特产', price: 25, desc: '洪湖鲜莲蓬剥着吃清甜带脆，干莲子炖汤粉糯。一汪好水养出的"水中特产"。' },
  { id: 'jingzhou_chu_xiu', name: '楚绣书签', icon: '🧵', tag: '衣', type: '文创', price: 45, desc: '楚文化凤鸟纹样绣上书签与团扇。荆州是楚绣重要传承地，一针一线绣出两千年前的浪漫。' },
  { id: 'jingzhou_qi_wenxue', name: '漆器文创', icon: '🖌️', tag: '衣', type: '文创', price: 60, desc: '楚式漆器复刻的小茶盘、首饰盒，黑红金三色配凤纹。"地下文物看荆州"的颜值担当。' },
  { id: 'jingzhou_sanyuan', name: '三国文创手办', icon: '🗿', tag: '衣', type: '文创', price: 35, desc: '刘备借荆州、关羽大意失荆州——Q版三国人物手办。古城里的"历史盲盒"，一抽一个名场面。' },
  { id: 'jingzhou_hucheng_qixing', name: '古城墙骑行', icon: '🚲', tag: '玩', type: '体验', price: 20, desc: '护城河畔租辆单车，沿11公里城墙根慢骑。一边是历史砖墙、一边是市井烟火，一小时骑完千年。' },
  { id: 'jingzhou_hanchuan', name: '护城河画舫夜游', icon: '⛴️', tag: '行', type: '体验', price: 60, desc: '夜幕下乘画舫绕护城河，城楼灯光倒映水中。听一段荆州花鼓戏，夜风都是古城的味道。' },
  { id: 'jingzhou_huagu', name: '荆州花鼓戏', icon: '🎭', tag: '玩', type: '体验', price: 50, desc: '国家级非遗的地方戏，唱腔土到极致又动人。小剧场里听一折《站花墙》，方言台词笑点密集。' },
  { id: 'jingzhou_minsu', name: '古城民宿一晚', icon: '🏨', tag: '住', type: '住宿', price: 200, desc: '古城墙根下的老宅民宿，推窗见城楼。夜里安静得能听到风穿过垛口，两百块睡进三国。' },
  /* ---- 新增：过早与荆沙味道（jzg_） ---- */
  { id: 'jzg_niuroumifen', name: '荆州牛肉米粉', icon: '🍜', tag: '食', type: '美食', price: 15, desc: '汤用牛骨头熬到发白，细滑的米粉一嗦就是米香。浇头是大块卤牛肉，本地人先喝汤再嗦粉，辣子一勺，整个早晨都亮起来。' },
  { id: 'jzg_baobao_fan', name: '聚珍园散烩八宝饭', icon: '🍚', tag: '食', type: '美食', price: 18, desc: '老字号聚珍园的压轴甜菜，糯米散散地烩开绝不抱团。莲子红枣青红丝铺满，入口甜糯不腻，老荆州称它"散烩八宝"席面一绝。' },
  { id: 'jzg_yuandou', name: '元豆泡糯米', icon: '🍲', tag: '食', type: '美食', price: 12, desc: '沙市人念念不忘的元豆泡糯米，豌豆煮成沙沙浓汤泡进蒸糯米。撒上葱花香菜，一勺连汤带米入口，绵软里全是豆子的清甜香。' },
  { id: 'jzg_liangxia', name: '沙市凉虾', icon: '🍧', tag: '食', type: '饮品', price: 8, desc: '米浆漏进凉水凝成小虾米模样，捞出淋上浓红糖水再添一勺薄荷。冰冰凉凉滑进喉咙，是沙市人顶着烈日也要喝的解暑密码。' },
  { id: 'jzg_honghu_oudai', name: '洪湖藕带', icon: '🥬', tag: '食', type: '特产', price: 30, desc: '初夏从藕塘深处抽出的嫩藕尖，白生生一掐就断。酸辣泡藕带脆得咔咔响，炒肉末或空口吃都开胃，过了六月就老，是时令鲜货。' },
  { id: 'jzg_honghu_lianou', name: '洪湖粉藕', icon: '🪷', tag: '食', type: '特产', price: 45, desc: '九孔洪湖粉藕煨排骨，是江汉平原冬天的仪式。藕段拉丝起沙、汤色奶白，咬一口粉糯化开。真空装带回家，把一碗藕汤寄给远方。' },
  { id: 'jzg_gongan_niurou', name: '公安牛三鲜', icon: '🥘', tag: '食', type: '特产', price: 78, desc: '公安县名菜牛三鲜，牛肉牛杂牛蹄筋一锅炖到软烂。红油翻滚香气直窜，配着公安锅盔蘸汤吃，本地人过冬就靠这一锅扛寒气。' },
  { id: 'jzg_baiyunbian', name: '白云边酒', icon: '🍶', tag: '食', type: '特产', price: 128, desc: '松滋酿的白云边是湖北名酒，"且就洞庭赊月色，将船买酒白云边"正是名字出处。酒体浓酱兼香，荆州人家宴席上常能见到它的身影。' },
  /* ---- 新增：楚文化与三国文创（jzg_） ---- */
  { id: 'jzg_chujian', name: '楚简仿制书简', icon: '🎋', tag: '玩', type: '文创', price: 68, desc: '荆州出土的战国楚简被誉为改写思想史的发现，这套竹简照着郭店楚简的样子制作。麻绳串起烫字竹片，展开就能读几句两千年前的原文。' },
  { id: 'jzg_qingtongqi', name: '楚青铜器纹样书立', icon: '🏺', tag: '玩', type: '文创', price: 88, desc: '荆州博物馆藏的楚式青铜器化作一对书立，凤鸟蟠螭纹在铜色上发亮。立在书架上镇住整排书，也镇住一段两千七百年前的青铜岁月。' },
  { id: 'jzg_chema', name: '车马阵战车模型', icon: '🐎', tag: '玩', type: '文创', price: 96, desc: '熊家冢车马阵的出土战车被做成桌面模型，车舆按文物比例复原。摆在案头，仿佛能听见两千年前楚国战车碾过郢都大道的辘辘声。' },
  { id: 'jzg_chengzhuan', name: '城墙铭文砖摆件', icon: '🧱', tag: '玩', type: '文创', price: 55, desc: '明清修城墙的荆州砖上常压着烧造铭文，这块仿古城砖拓着提调官字样。捧在手里沉甸甸，像捧住一块能够触摸的荆州城历史。' },
  { id: 'jzg_chuxiu_si', name: '楚绣凤鸟丝巾', icon: '🧣', tag: '衣', type: '服饰', price: 140, desc: '荆楚刺绣以凤鸟为魂，这条真丝丝巾上绣着昂首振翅的楚凤。红黑金三色撞得热烈，系在颈间或缠在包带，把楚人的浪漫带出古城。' },
  { id: 'jzg_fangte_piao', name: '方特东方神画门票', icon: '🎟️', tag: '游', type: '体验', price: 230, desc: '一张荆州方特日场门票，看楚乐编钟演出、坐动感车穿越三国战场。白天刷项目晚上等焰火，楚文化与乐园的混搭能从早玩到晚。' }
);

/* ================= data/cn/huazhong/jingzhou/jz_03_stories.js ================= */
/* 荆州 分册03：奇闻趣事（楚文化/三国/古城墙/红色记忆） */
window.JZ_STORIES = window.JZ_STORIES || [];
window.JZ_STORIES.push(
  /* ---- 旧条目：三国与楚地传奇（原样保留） ---- */
  { id: 'jingzhou_story_sanguo', name: '刘备借荆州', icon: '📜', desc: '"刘备借荆州——有借无还"这句歇后语流传千年。荆州是三国争夺最激烈的城，十多个典故都在这里发生。' },
  { id: 'jingzhou_story_dasui', name: '大意失荆州', icon: '⚔️', desc: '关羽北伐襄樊时后方被吕蒙偷袭，败走麦城。"大意失荆州"从此成为轻敌致败的代名词。' },
  { id: 'jingzhou_story_nanshi', name: '西汉男尸两千年不腐', icon: '🧑‍🦳', desc: '凤凰山168号汉墓出土的男尸"遂先生"，距今两千多年皮肤仍有弹性。防腐技术之谜至今吸引研究者。' },
  { id: 'jingzhou_story_yuemi', name: '越王勾践剑的"邻居"', icon: '🗡️', desc: '与越王勾践剑同出的还有吴王夫差矛——吴越争霸的冤家兵器在荆州楚墓"握手"。战国国际局势一目了然。' },
  { id: 'jingzhou_story_honghu', name: '洪湖水浪打浪', icon: '🎵', desc: '经典民歌让洪湖名扬全国。夏天万亩荷塘碧叶接天，游客坐船深处才明白：歌里唱的全是真的。' },
  { id: 'jingzhou_story_guokui', name: '锅盔的"公安"误会', icon: '🫓', desc: '公安锅盔的"公安"是湖北省公安县，不是警察。外地游客第一次听到"公安锅盔"都会愣三秒。' },
  /* ---- 新增：楚文化根脉（jzs_） ---- */
  { id: 'jzs_yuhua', name: '禹划九州始有荆州', icon: '🏺', desc: '大禹治水分天下为九州，荆州正是其一，名字沿用了四千多年。"禹划九州，始有荆州"不只是一句口号，江汉平原自古就是天下要冲。' },
  { id: 'jzs_chu_ding', name: '楚定都郢四百年', icon: '🏛️', desc: '楚文王把都城迁到纪南城，此后二十代楚王守着郢都四百余年。楚人筚路蓝缕从荆山走出，在江汉平原建起南方最大都会，郢都宫阙连云。' },
  { id: 'jzs_quyuan', name: '屈原《哀郢》望故都', icon: '🥀', desc: '秦军攻破郢都那年，流放中的屈原写下《哀郢》，字字都是回望故都的眼泪。这首长诗让楚国旧都的悲怆，成了荆州最早的乡愁。' },
  { id: 'jzs_chujianxing', name: '郭店楚简出土记', icon: '🎋', desc: '1993年郭店一号楚墓挖出八百余枚竹简，上面竟是失传两千多年的道家与儒家抄本。荆州的地下果然埋着图书馆，一锄头下去全是故事。' },
  { id: 'jzs_zhanghua', name: '楚灵王好细腰', icon: '🦚', desc: '楚灵王在章华台广纳纤腰美人，闹出"楚王好细腰，宫中多饿死"的荒唐话。那座穷奢的高台早已湮灭，成语却代代传了下来。' },
  /* ---- 新增：三国与古城墙（jzs_） ---- */
  { id: 'jzs_guanyu_shi', name: '关羽镇守荆州十年', icon: '🗡️', desc: '赤壁之战后关羽独当一面镇守荆州，修城练水军、水淹七军威震华夏。英雄最得意时丢了后方，荆州从此与"大意"二字绑在一起。' },
  { id: 'jzs_huarong', name: '曹操败走华容道', icon: '🤝', desc: '赤壁大火烧了曹操战船，他率残部从华容道夺路而逃。小说里关羽念旧义释曹操，留下千古名场面——荆州古道上从此讲不完一个"义"字。' },
  { id: 'jzs_tiexiang', name: '铁打的荆州', icon: '🧱', desc: '荆州谚语夸城墙是"铁打的"，两千多年里它在战火与洪水中修了又修。砖石缝里砌进江汉平原的黏土与汗水，如今仍是南方保存最好的古城。' },
  { id: 'jzs_wanshou', name: '万寿宝塔越变越矮', icon: '🗼', desc: '明代皇帝为母祈福修起万寿宝塔，谁料几百年后江堤不断加高，塔基被埋进堤身七米深。如今要看塔座得低头俯视，成了江边奇景。' },
  { id: 'jzs_chemazhen', name: '车马阵考古记', icon: '🐎', desc: '熊家冢楚墓揭开的车马坑里，四十乘真车真马整齐列阵地下，规模直逼秦兵马俑。楚王生前多威风，看这阵仗便知郢都当年的气派。' },
  { id: 'jzs_zhangjuzheng', name: '张居正的一条鞭法', icon: '🧮', desc: '万历首辅张居正是荆州江陵人，一条鞭法整顿税制，十年改革给大明续了命。死后虽遭抄家风波，故居却把这位改革家的一生留给了后人。' },
  /* ---- 新增：市井烟火与红色记忆（jzs_） ---- */
  { id: 'jzs_honghu_chiwei', name: '洪湖赤卫队传奇', icon: '🚩', desc: '当年贺龙周逸群到洪湖拉起赤卫队，渔民放下渔网扛起梭镖。芦苇荡里的水上游击战写进经典电影，瞿家湾老墙上的标语至今还红着。' },
  { id: 'jzs_yangmatou', name: '沙市开埠往事', icon: '🚢', desc: '马关条约把沙市辟为商埠，洋行码头沿江一字排开。海关钟声与轮船汽笛响了一个世纪，如今老码头成了文创园，江水依旧日夜东流。' },
  { id: 'jzs_mashan', name: '马山民歌传楚韵', icon: '🎵', desc: '荆州马山的民歌清亮悠扬，据说带着"下里巴人"的楚地遗音。田埂上歇脚的农民张口就唱，民间歌手还把调子唱上了全国舞台。' }
);

/* ================= data/cn/huazhong/jingzhou/jingzhou.js ================= */
/* ============ 湖北·荆州（分册组装版） ============
 * 分册：jz_01地点 / jz_02周边 / jz_03趣事。
 * 主题：楚文化 / 三国 / 古城墙。
 */
(function () {
  window.TRAVEL_CITIES = window.TRAVEL_CITIES || [];
  window.TRAVEL_CITIES.push({
    id: 'jingzhou',
    name: '荆州',
    country: '中国',
    cc: 'CN',
    province: '湖北',
    flag: '🇨🇳',
    region: '华中',
    hero: '🏯',
    desc: '"禹划九州，始有荆州"。三国故事最密集的古城，完好的城墙环着护城河，楚文化在这里埋着整座地下博物馆。',
    travel: [{ name: '高铁', icon: '🚄', cost: 150 }, { name: '汽车', icon: '🚌', cost: 90 }],
    visa: null,
    spots: (window.JZ_SPOTS = window.JZ_SPOTS || []),
    souvenirs: (window.JZ_GIFTS = window.JZ_GIFTS || []),
    stories: (window.JZ_STORIES = window.JZ_STORIES || []),
  });
})();

/* ================= data/cn/huazhong/kaifeng/kf_01_spots.js ================= */
/* 开封 分册01：景点圣地（八朝古都/宋韵水城/清明上河） */
window.KF_SPOTS = window.KF_SPOTS || [];
window.KF_SPOTS.push(
  /* ---- 旧档条目原样沿用 ---- */
  { id: 'kaifeng_qingming', name: '清明上河园', icon: '🎨', price: 120, desc: '把《清明上河图》变成可以走进去的宋城。王员外招婿、包公迎宾、汴河大战实景演出，"大宋沉浸游"。' },
  { id: 'kaifeng_longting', name: '龙亭·天波杨府', icon: '🏛️', price: 45, desc: '六朝皇宫遗址上的龙亭大殿，潘杨二湖映忠奸。天波杨府讲杨家将满门忠烈，菊花展秋天满城。' },
  { id: 'kaifeng_tie', name: '铁塔·繁塔', icon: '🛕', price: 40, desc: '"天下第一塔"铁塔高55米，琉璃砖如铁色千年不倒。繁塔是全国罕见的六角形内六角形佛塔。' },
  { id: 'kaifeng_daxiangguo', name: '大相国寺', icon: '🛕', price: 40, desc: '鲁智深倒拔垂杨柳的地方，北宋皇家寺院。千手千眼观音像整棵银杏雕成，镇寺之宝。' },
  { id: 'kaifeng_gulou', name: '鼓楼夜市·西司夜市', icon: '🏮', price: 0, desc: '千年不熄的夜市灯火，"汴梁夜市从北宋摆到现在"。炒凉粉、羊肉炕馍、杏仁茶一路吃过去。' },
  { id: 'kaifeng_bao', name: '开封府·包公祠', icon: '⚖️', price: 65, desc: '"开封有个包青天"，开封府每天有包公断案演出。铡刀威风凛凛，"包青天"是开封的文化IP。' },
  { id: 'kaifeng_shanxi', name: '山陕甘会馆', icon: '🏛️', price: 30, desc: '清代商人会馆，木雕砖雕石雕"三绝"藏在深巷。一座牌楼七层镂空，"看不见的木匠功"。' },
  /* ---- 新增扩容（主题：八朝古都/宋文化/清明上河图） ---- */
  { id: 'kfp_hanyuan', name: '中国翰园碑林', icon: '🖋️', price: 40, desc: '北部碑林依山叠翠，三千余方刻石从甲骨文排到行草书。亭廊间常有游人摹字拓碑，湖心还可泛舟对诗。' },
  { id: 'kfp_yujie', name: '宋都御街', icon: '🏮', price: 0, desc: '北宋皇宫前的御道按宋代街市复建，朱红牌楼一路排开。华灯初上时簪花汉服穿行其间，直抵龙亭湖夜色。' },
  { id: 'kfp_shudianjie', name: '书店街', icon: '📚', price: 0, desc: '与鼓楼夜市相连的百年书坊街，青砖小楼里古籍与文房四宝俱全。朱漆木门下翻书挑笔，满街都是翰墨香。' },
  { id: 'kfp_wansuishan', name: '万岁山大宋武侠城', icon: '⚔️', price: 100, desc: '依《水浒传》江湖造景的武侠乐园，城墙上演三打祝家庄火攻。实景水战炮声震天，侠客身影在屋脊间飞掠。' },
  { id: 'kfp_xiaosongcheng', name: '汴梁小宋城', icon: '🎪', price: 0, desc: '室内仿宋街市分两层铺开，顶棚彩绘成汴京暮色。百余种小吃沿街现做现卖，戏台杂剧锣鼓不歇。' },
  { id: 'kfp_zhouqiao', name: '州桥及汴河遗址', icon: '🏺', price: 0, desc: '北宋御街与汴河交汇处的州桥，考古掘出精美石壁浮雕。海马瑞兽缠枝祥云，印证了《东京梦华录》的桥市繁华。' },
  { id: 'kfp_daliangmen', name: '开封城墙·大梁门·古马道', icon: '🏯', price: 15, desc: '城北明代城墙层层包砖，大梁门下藏着古马道遗址。顺坡道登上城楼，向北能望见高出城墙的黄河堤。' },
  { id: 'kfp_yanqingguan', name: '延庆观', icon: '⛩️', price: 30, desc: '纪念王重阳的全真祖庭，玉皇阁还是元代原构。砖砌穹顶不用一根梁木，历经水患地震仍端然矗立。' },
  { id: 'kfp_yuhe', name: '大宋御河', icon: '🛶', price: 0, desc: '五公里水街把包公湖、西司湖与龙亭湖串成一线，两岸亭台如画。白天沿柳堤慢走，夜来画舫摇过座座桥洞。' },
  { id: 'kfp_museum', name: '开封市博物馆', icon: '🏛️', price: 0, desc: '新馆展厅里，《开封府题名记》碑上包拯的名字被游人摸出凹痕。大晟编钟与宋代石刻并列，八朝往事一件件讲透。' },
  { id: 'kfp_zhuxian', name: '朱仙镇·启封故园', icon: '🖼️', price: 50, desc: '朱仙镇是木版年画发源地，也是岳飞大捷的故地，启封故园枕着运粮河。作坊里看年画套色印刷，岳飞庙前讲金牌故事。' },
  { id: 'kfp_huanghe', name: '柳园口·黄河悬河', icon: '🌊', price: 0, desc: '黄河在开封段成了地上悬河，大堤下河床高出城区。站柳园口堤顶远望，浊浪滚滚悬在头顶般震撼。' },
  { id: 'kfp_shuanglongxiang', name: '双龙巷', icon: '🐉', price: 0, desc: '传说赵匡胤、赵光义幼年住过此巷，故得名双龙巷。青砖门楼深院依旧，巷口的铜雕重演兄弟登基的旧事。' },
  { id: 'kfp_yuwangtai', name: '禹王台·古吹台', icon: '⛰️', price: 10, desc: '春秋师旷曾在此吹律，故台名古吹台。明清为镇黄河水患奉大禹于此，古柏森森，台下遥望繁塔身影。' },
  { id: 'kfp_bianxihu', name: '汴西湖', icon: '🌅', price: 0, desc: '郑开大道旁的新城大湖，湖岸线绵延数里。黄昏时栈桥看落日熔金，遛弯跑步的人潮把夜色慢慢点亮。' },
  { id: 'kfp_baogongci', name: '包公祠', icon: '⚖️', price: 30, desc: '包公湖畔纪念祠堂，二殿塑包拯黑面长髯坐像。三铡陈列森森，照壁上“清正廉明”四个字最是醒目。' },
  { id: 'kfp_tieta', name: '铁塔公园·开宝寺塔', icon: '🗼', price: 50, desc: '开宝寺塔以赭色琉璃砖垒就，远望如铁铸，故名铁塔。塔身砖雕飞天乐伎活灵活现，登顶能望古都天际线。' },
  { id: 'kfp_fanta', name: '繁塔', icon: '🛕', price: 20, desc: '北宋六角楼阁式塔，原为九层巨构，现仅存三层而通高三十余米。塔身镶满佛像砖，顶部又叠小塔成塔上塔。' }
);

