/* ================= data/cn/xibei/kashi/ks_01_spots.js ================= */
/* 喀什 分册01：景点圣地（丝路古城·巴扎烟火·帕米尔高原） */
window.KS_SPOTS = window.KS_SPOTS || [];
window.KS_SPOTS.push(
  /* ---- 旧档保留 ---- */
  { id: 'kashi_gucheng', name: '喀什古城', icon: '🏘️', price: 0, desc: '活着的千年古城，土黄色小巷像迷宫。开城仪式的歌舞、铜匠铺的敲打声，孩子踢球的巷子全是生活。' },
  { id: 'kashi_aitigaer', name: '艾提尕尔清真寺', icon: '🕌', price: 45, desc: '全国最大清真寺之一，黄墙绿门两座宣礼塔。古尔邦节万人跳萨满舞的广场，平时鸽子成群。' },
  { id: 'kashi_gaotai', name: '高台民居', icon: '🏚️', price: 30, desc: '六百年崖上"悬空"土陶民居群，过街楼层层叠叠。小巷随坡而上，手工作坊藏在转角。' },
  { id: 'kashi_xiangfei', name: '香妃园', icon: '🌺', price: 30, desc: '香妃墓绿色琉璃穹顶，伊斯兰陵墓建筑精品。传说香妃体有异香，园里沙枣花开正应景。' },
  { id: 'kashi_zhongba', name: '中西亚国际贸易市场（东巴扎）', icon: '🛍️', price: 0, desc: '两千年丝路商埠的延续，周日最热闹。地毯、乐器、干果堆积如山，"砍价的天堂"。' },
  { id: 'kashi_panshangu', name: '帕米尔高原·白沙湖一日', icon: '🏔️', price: 300, desc: '沿中巴友谊公路上帕米尔，白沙湖蓝得离谱。慕士塔格峰"冰山之父"雪顶倒映湖中，塔吉克乡民挥手致意。' },
  { id: 'kashi_shicha', name: '百年老茶馆', icon: '🍵', price: 0, desc: '《追风筝的人》取景地，二楼木窗望老街。一壶药茶配馕，老人弹都塔尔，时光在这里打盹。' },
  /* ---- 喀什古城与老城 ---- */
  { id: 'ksp_kaicheng', name: '开城迎宾仪式', icon: '🎺', price: 0, desc: '每天上午十点，东门鼓乐齐鸣，乐手舞者盛装迎客。花帽翻飞，游客被拉进圈里共舞，晨光把千年土墙照得金黄。' },
  { id: 'ksp_gaotaiqiao', name: '高台桥·古城全景', icon: '🌉', price: 0, desc: '站在高台桥望对岸，土黄民居层层叠上崖壁，晾着的花帽与地毯像彩色补丁。黄昏时整座古城镀上蜜色，炊烟从馕坑顶上慢慢散开。' },
  { id: 'ksp_caihongxiang', name: '彩虹巷·布袋巷', icon: '📸', price: 0, desc: '老城深处的彩虹巷与布袋巷，墙面刷成粉彩，悬挂的彩袋与陶罐随风轻晃。钻进转角凹个造型，葡萄藤与花窗都来凑热闹。' },
  { id: 'ksp_jiulongquan', name: '九龙泉', icon: '💧', price: 0, desc: '高台下的九龙泉，传说曾护佑疏勒军民。泉水冬暖夏凉，四季不断，滋养着坡上的石榴树与葡萄架，是古城最温柔的一口活水。' },
  { id: 'ksp_kashimuseum', name: '喀什博物馆', icon: '🏛️', price: 0, desc: '从丝路古币到唐代佛寺遗存，从高台民居模型到艾德莱斯织机，馆里藏着一部西域编年史。逛完再钻老城，处处都能对上号。' },
  /* ---- 巴扎集市 ---- */
  { id: 'ksp_zhiren_bazar', name: '职人巴扎', icon: '🎻', price: 0, desc: '库木代尔瓦扎街两侧，热瓦普、手鼓挂满乐器店，铜匠铺叮当作响。匠人一坐半生錾花敲器，游客带走的每件，都留有手心余温。' },
  { id: 'ksp_hanbazar', name: '汗巴扎夜市', icon: '🏮', price: 0, desc: '入夜的老城街巷灯火通明，烤蛋、缸子肉、烤鸽子的香气缠着青烟往天上飘。沿街小凳一座，几十块钱能从巷口吃到巷尾。' },
  { id: 'ksp_niuyang_bazar', name: '牛羊大巴扎', icon: '🐂', price: 0, desc: '每逢周日，城外尘土漫天，成群的牛、羊、骆驼挤满大集。买家看牙口、捏膘情，袖口里握手就定了价，讨价还价全靠笑和手势。' },
  /* ---- 历史遗迹 ---- */
  { id: 'ksp_pantuocheng', name: '盘橐城·班超纪念园', icon: '🐎', price: 0, desc: '班超纪念园里，定远侯铜像持节远眺疏勒故地。这位东汉名将驻守西域数十年，让丝路南道重归安宁，土台上风声依旧。' },
  { id: 'ksp_yusufu', name: '玉素甫·哈斯·哈吉甫墓', icon: '📖', price: 20, desc: '《福乐智慧》的作者玉素甫长眠喀什城中，绿荫墓园拱拜庄严。这部千年前的劝喻长诗，至今仍被视作维吾尔文化的智慧灯塔。' },
  { id: 'ksp_mahmud', name: '麻赫穆德·喀什噶里墓', icon: '📚', price: 0, desc: '乌帕尔乡的绿坡上，葬着《突厥语大词典》的作者麻赫穆德。这位十一世纪学者踏遍草原河谷，把突厥各部的地图装进一部词典。' },
  { id: 'ksp_shaoche_wanggong', name: '莎车·叶尔羌汗王宫', icon: '🕌', price: 30, desc: '莎车的叶尔羌汗王宫，蓝绿瓷砖拼出繁复花纹，雕花穹顶层层叠叠。在这里坐下听一段十二木卡姆，才算摸到南疆文明的脉搏。' },
  /* ---- 帕米尔高原 ---- */
  { id: 'ksp_kalakul', name: '喀拉库勒湖', icon: '🏞️', price: 0, desc: '帕米尔深处的喀拉库勒湖，慕士塔格雪峰整座沉进湖心。柯尔克孜牧民的毡房升起炊烟，清晨湖面平如镜，风一过碎成满湖银光。' },
  { id: 'ksp_muztag_bingchuan', name: '慕士塔格冰川公园', icon: '🧊', price: 200, desc: '沿中巴友谊公路上行，冰川公园的冰舌垂到脚边。海拔四千多米的风裹着雪粒，指尖摸上幽蓝的冰面，冷得人一下子清醒。' },
  { id: 'ksp_taheman', name: '塔合曼湿地', icon: '🌿', price: 0, desc: '慕士塔格脚下的塔合曼湿地，溪流如银线织出大片草甸。牦牛慢悠悠啃草，毡房炊烟一缕，是高原途中最温柔的歇脚处。' },
  { id: 'ksp_tashikuergan', name: '塔县石头城·金草滩', icon: '🏰', price: 30, desc: '塔什库尔干城边的古石头城，残墙立在风里。山脚下金草滩河流蜿蜒，牛羊如珍珠散落，塔吉克牧歌与雪峰一起铺进画框。' },
  { id: 'ksp_oyitake', name: '奥依塔克红山', icon: '🏜️', price: 0, desc: '去帕米尔路上的奥依塔克，红山被风蚀成宫殿与利刃，山脚白沙如雪。停车望一会儿，随手一拍都是地质教科书的封面。' },
  { id: 'ksp_muji', name: '木吉火山群', icon: '🌋', price: 0, desc: '帕米尔深处的木吉火山群，上百个火山口散在旷野，积水湛蓝如高原之眼。柯尔克孜牧人策马而过，天地空旷得只剩风声与鹰影。' },
  /* ---- 节庆与演艺 ---- */
  { id: 'ksp_aitigaer_square', name: '艾提尕尔广场', icon: '🕊️', price: 0, desc: '艾提尕尔清真寺前的广场从不冷清，孩子追鸽、老人闲坐，卖馕小车叮当经过。礼拜声起时，整条街忽然安静下来，连风都放轻脚步。' },
  { id: 'ksp_mukamu_ye', name: '十二木卡姆演艺之夜', icon: '🎶', price: 120, desc: '夜幕四合，老城演艺厅的萨塔尔琴声一起，歌者唱响十二木卡姆，舞者旋成彩色的风。一壶药茶在手，听尽丝路千年的悲欢。' },
  { id: 'ksp_jinhuyang', name: '泽普金湖杨林', icon: '🍂', price: 40, desc: '叶尔羌河畔的泽普金湖杨林，深秋金黄铺满河湾，水中倒影与游鱼同框。坐上小火车穿行金色长廊，满眼都是被秋天点燃的树。' }
);

/* ================= data/cn/xibei/kashi/ks_02_gifts.js ================= */
/* 喀什 分册02：特色周边（丝路美食/非遗手作/西域风情） */
window.KS_GIFTS = window.KS_GIFTS || [];
