    id: 'hakone',
    name: '箱根',
    country: '日本',
    cc: 'JP',
    flag: '🇯🇵',
    region: '日本·关东',
    hero: '♨️',
    desc: '富士山下的温泉之乡：芦之湖海贼船、大涌谷的黑玉子、强罗公园与雕刻之森，EVA"第三新东京市"的原型地。',
    travel: [{ name: '高铁·新干线', icon: '🚄', cost: 2300 }, { name: '飞机', icon: '✈️', cost: 2500 }],
    visa: { cost: 300, note: '日本单次旅游签证（旅行社代办）' },
    spots: (window.HKN_SPOTS = window.HKN_SPOTS || []),
