/* ================= data/world/asia/JP/kamakura/kam_01_spots.js ================= */
/* 镰仓 分册01：景点圣地（大佛与寺院/海与江之电/古都小巷） */
window.KAM_SPOTS = window.KAM_SPOTS || [];
window.KAM_SPOTS.push(
  /* ---- 大佛与禅寺（沿用原条目） ---- */
  { id: 'kamakura_koukou', name: '镰仓高校前平交道', icon: '🚉', price: 0, desc: '《灌篮高手》OP神场景：电车道口+碧海+少年。江之电经过瞬间，"樱木花道的夏天"具象化。' },
  { id: 'kamakura_daibutsu', name: '镰仓大佛', icon: '🛕', price: 300, desc: '13世纪青铜阿弥陀佛坐像高11.4米，内部可进入。"室内的佛"，抬头看佛的头发纹理。' },
  { id: 'kamakura_tsurugaoka', name: '鹤冈八幡宫', icon: '⛩️', price: 0, desc: '源赖朝建立的武家守护神社，源氏池与舞殿。"镰仓幕府"的心脏，表参道小吃一路。' },
  { id: 'kamakura_hase', name: '长谷寺·紫阳花', icon: '🌸', price: 400, desc: '"紫阳花寺"，六月2500株紫阳花开满山坡。眺望台看相模湾，"镰仓的花寺"。' },
  { id: 'kamakura_enoden', name: '江之电沿线巡礼', icon: '🚃', price: 0, desc: '江之电"极乐寺站""七里滨"都是动漫取景地。车窗里全是海景，"日本最浪漫的铁路"。' },
  { id: 'kamakura_komachi', name: '小町通商店街', icon: '🏮', price: 0, desc: '镰仓名物小吃街：吻仔鱼饭、鸽曲奇、大三巴蛋挞。人形烧"鸠サブレー"是百年伴手礼。' },
  { id: 'kamakura_beach', name: '由比滨·材木座海滩', icon: '🏄', price: 0, desc: '夏季冲浪少年聚集，《灌篮高手》的"海边"就在这。夕阳下沙滩排球，青春气息扑面。' },
  /* ---- 江之岛与海景（新增） ---- */
  { id: 'kamp_enoshima', name: '江之岛', icon: '🌴', price: 0, desc: '坐江之电到"江之岛站"，跨过弁天桥登岛。江岛神社的龙宫与瞭望塔看相模湾日落，白昼看富士、夜晚看镰仓灯火。' },
  { id: 'kamp_shichirigahama', name: '七里滨', icon: '🌊', price: 0, desc: '从稻村崎到小动岬的白色沙滩，太平洋的浪一望无际。黄昏时富士山剪影浮在海面，江之电沿沙滩缓缓摇过。' },
  { id: 'kamp_inamuragasaki', name: '稻村崎·富士view', icon: '🗻', price: 0, desc: '镰仓半岛最突出的海角，传说源赖朝曾在此祭海。天气晴好时能同时看到富士山与伊豆半岛，是拍"湘南绝景"的机位。' },
  { id: 'kamp_zaimokuza', name: '材木座海岸', icon: '🛶', price: 0, desc: '由比滨东侧的小海湾，沙细浪缓适合散步。夏天海边小屋一字排开，独木舟与桨板爱好者在此聚集，日落时天空染成粉橘色。' },
  { id: 'kamp_goryo', name: '御灵神社·道口', icon: '🚋', price: 0, desc: '山手小丘上的神社，门前就是江之电最著名的道口。电车鸣笛穿过树林的瞬间按下快门，是摄影爱好者必守的机位。' },
  { id: 'kamp_dankazura', name: '段葛参道', icon: '🌸', price: 0, desc: '鹤冈八幡宫的参道中段，土堤两侧种满樱花。镰仓时代是为政子而修的路，如今四月花瓣飘成花雨，像一条粉色隧道。' },
  /* ---- 古都禅寺与秘境（新增） ---- */
  { id: 'kamp_engakuji', name: '圆觉寺', icon: '⛩️', price: 300, desc: '北条时宗为追悼蒙古袭来战殁者所建，镰仓五山之一。山门"三解脱门"后是一片苔藓庭院，秋天的红叶与洪钟声最治愈。' },
  { id: 'kamp_kenchoji', name: '建长寺', icon: '🏯', price: 500, desc: '日本最古老禅寺，开山是南宋高僧兰溪道隆。国宝梵钟与法堂的云龙图震撼人心，走在巨大的樟树道里像走进宋代画卷。' },
  { id: 'kamp_hokokuji', name: '报国寺·竹林', icon: '🎋', price: 500, desc: '藏在山谷里的"竹之寺"，庭院里上千株孟宗竹遮天蔽日。坐在本堂喝抹茶听竹叶声，阳光穿过竹缝洒下细碎的光影。' },
  { id: 'kamp_meigetsuin', name: '明月院·圆窗', icon: '🪟', price: 300, desc: '紫阳花寺之一，本堂那扇"悟りの窗"透过圆洞看四季庭院。六月绣球开成蓝海，秋冬则只有一窗枯山水与一枚红叶。' },
  { id: 'kamp_tokeiji', name: '东庆寺·缘切寺', icon: '🗝️', price: 0, desc: '曾经庇护被丈夫抛弃的女性的"缘切寺"，如今以铁线莲花闻名。院内苔藓如绿毯，山门旁的梅雨绣球也开得安静。' },
  { id: 'kamp_myohonji', name: '妙本寺', icon: '🏮', price: 0, desc: '比企谷山的日莲宗古刹，门前石阶被青苔染绿。本堂周围安静得只有鸟鸣，石阶、青枫与苔庭自成一片远离人潮的秘境。' },
  { id: 'kamp_anokokuji', name: '安国论寺', icon: '🌸', price: 0, desc: '藏在住宅区深处的临济宗古寺，春日樱花与杜鹃开满山坡。从寺门能望见海，是为数不多能安静看花的镰仓名所。' },
  /* ---- 古都小巷与文艺（新增） ---- */
  { id: 'kamp_benzaichaya', name: '钱洗弁财天', icon: '⛰️', price: 0, desc: '藏在地下隧道里的财神庙，用山泉洗钱会越洗越旺。洞口的水池边挤满来"洗钱"的游客，据说边洗边许愿效果加倍。' },
  { id: 'kamp_sasukeinari', name: '佐助稻荷神社', icon: '🦊', price: 0, desc: '红色鸟居沿山路密密排开，狐狸像一路微笑。穿行在竹林中像走进宫崎骏的结界，半山腰能俯瞰镰仓市街与远处的海。' },
  { id: 'kamp_bunkakan', name: '镰仓文学馆', icon: '📚', price: 0, desc: '建于大正年间的洋馆，曾是前田侯爵别邸。庭院里的蔷薇与大海同框，馆内收藏川端康成等人的手稿，是文学散步的好去处。' }
);

