/* ================= data/world/asia/JP/okinawa/okn_01_spots.js ================= */
/* 冲绳县 分册01：景点圣地（那霸/首里·本岛中北部·离岛与南部半岛） */
window.OKN_SPOTS = window.OKN_SPOTS || [];
window.OKN_SPOTS.push(
  /* ---- 首里与本部（沿用原条目） ---- */
  { id: 'okinawa_shuri', name: '首里城', icon: '🏯', price: 400, desc: '琉球王国的王宫，赤瓦朱柱融合中日建筑风格。守礼门上的"守礼之邦"匾额，是琉球五百年王城的名片。' },
  { id: 'okinawa_churaumi', name: '美丽海水族馆', icon: '🐋', price: 1900, desc: '"黑潮之海"主水缸里有全球最大级别鲸鲨，水族馆天花板就是一整面巨幕。喂食秀时鲸鲨张嘴的瞬间全场倒吸气。' },
  { id: 'okinawa_kouri', name: '古宇利岛大桥', icon: '🌉', price: 0, desc: '两公里跨海大桥飞越翡翠绿海面，尽头是小岛白沙滩。自驾桥上像开进一幅画，随手拍都是壁纸。' },
  { id: 'okinawa_baise', name: '万座毛', icon: '🌊', price: 0, desc: '海边悬崖上的整片草坪被海风修剪成毛绒绒的"大象鼻"。日落时海天一色，风大到能把烦恼吹走。' },
  { id: 'okinawa_taketomi', name: '竹富岛', icon: '🏝️', price: 2500, desc: '离岛里的"琉球活化石"：白砂路、红瓦屋、石狮子。水牛车带你绕岛一圈，车夫边赶牛边弹三线。' },
  { id: 'okinawa_america', name: '美国村', icon: '🎡', price: 0, desc: '北谷的美式风情街区：摩天轮、加州风餐厅、冲浪店。琉球与美式文化奇妙混搭，落日海滩就在隔壁。' },
  { id: 'okinawa_sefa', name: '斋场御岳', icon: '🙏', price: 200, desc: '琉球最高圣地，没有神殿只有巨岩与绿意。"遥拜地"面向久高岛，古时琉球最高女祭司在此祈祷。' },
  /* ---- 新增·那霸市区与南部 ---- */
  { id: 'oknp_kokusaidori', name: '国际通', icon: '🛍️', price: 0, desc: '那霸最热闹的“奇迹一英里”，土产店、冲绳料理与三线LIVE沿街排开。从县厅一路逛到牧志市场，越夜越亮，海鲜烧烤的香味在路口打转。' },
  { id: 'oknp_naminoue', name: '波上宫与波之上海滩', icon: '⛩️', price: 0, desc: '建在珊瑚礁岩上的朱红神社，石阶直通崖下的天然海滩。那霸市区难得的一片蓝，退潮时礁石间还能捞到小寄居蟹。' },
  { id: 'oknp_tsuboya', name: '壶屋·陶器街', icon: '🏺', price: 0, desc: '那霸的老窑街，壶屋烧在这里烧了三百年。街边店铺摆满泡盛壶与风狮爷，运气好能看到匠人当街拉坯，空气里是温热的土腥味。' },
  { id: 'oknp_peace', name: '平和祈念公园', icon: '🕊️', price: 0, desc: '为冲绳战役建的追悼之地，碑群刻满二十五万死难者姓名。纪念馆的照片与遗物让人沉默，出馆时海风吹来，才觉得和平如此具体。' },
  { id: 'oknp_chinen', name: '知念岬', icon: '🌅', price: 0, desc: '半岛最南端向海伸出的草坡，晴日能望见久高岛浮在蓝线上。清早来这里等日出，海面先染金再透蓝，本地情侣的私藏机位。' },
  { id: 'oknp_oujima', name: '奥武岛·猫岛', icon: '🐱', price: 0, desc: '知念半岛外的小渔岛，猫比居民还多，见人就来蹭腿。渔港的天妇罗摊刚起锅，蹲在路边边喂猫边吃，像回到昭和午后的海边。' },
  { id: 'oknp_senaga', name: '濑长岛', icon: '🏝️', price: 0, desc: '环礁小岛上的纯白村落，人称“琉球圣托里尼”。店里喝咖啡就能看飞机从头顶低空掠过，傍晚夕阳把白墙与海面一起染成蜜糖色。' },
  { id: 'oknp_gyokusendo', name: '玉泉洞', icon: '🪨', price: 1300, desc: '冲绳最大的钟乳洞，开放路段挂满百万支石笋。水滴要上千年才把石头“长高”一厘米，灯光一起，满壁都是时间的手艺。' },
  { id: 'oknp_ryukyumura', name: '琉球王国村', icon: '🎭', price: 1000, desc: '玉泉洞旁的露天博物馆，红瓦古宅里织布、三线与传统染布轮番示范。正午的EISA太鼓舞鼓点震地，游客最后都跳起来跟着挥手。' },
  /* ---- 新增·本岛中北部与离岛 ---- */
  { id: 'oknp_nakijin', name: '今归仁城迹', icon: '🏯', price: 400, desc: '北山王国的王城遗迹，曲线石垣沿山脊绵延四百米。一月寒绯樱沿墙开成粉带，站在残城里，海风里像还有王朝的回声。' },
  { id: 'oknp_katsuren', name: '胜连城迹', icon: '🏰', price: 200, desc: '建在半岛高台上的世界遗产城迹，走下石墙就是无边的太平洋。回程开过“海中道路”，两侧海水清得像车在翡翠上滑行。' },
  { id: 'oknp_zanpa', name: '残波岬', icon: '🗼', price: 300, desc: '读谷村西端的雪白灯塔立在三十米断崖上，浪花常年撞出彩虹。黄昏风大得站不稳，等塔顶红灯亮起，天边正好烧成一片橘。' },
  { id: 'oknp_bise', name: '备濑福木林荫道', icon: '🌴', price: 0, desc: '本部半岛海岸边的百年福木防风林，枝叶搭出清凉隧道。赤脚踩过一旁的白沙滩，树影摇着海风，把夏天调成了慢速播放。' },
  { id: 'oknp_pineapple', name: '名护凤梨园', icon: '🍍', price: 900, desc: '坐上凤梨造型的无人小车逛热带果园，菠萝田与扶桑花开到天边。园里连帽子都是凤梨形状，甜品台全是菠萝味的“黄色宇宙”。' },
  { id: 'oknp_heartrock', name: '古宇利心形岩', icon: '💗', price: 0, desc: '退潮时露出一对拼成心形的礁石，传说是恋人们祈愿的圣地。踩着浅滩走近它，浪花一退一进，连老夫老妻都掏出手机合照。' },
  { id: 'oknp_biosu', name: '比奥斯的丘', icon: '🛶', price: 1000, desc: '名护郊外的亚热带乐园，坐水牛船缓缓穿过红树林水道。池水倒映古木与蕨叶，除了划水声只剩鸟鸣，是岛上最绿的一座片场。' },
  { id: 'oknp_yanbaru', name: '山原原始森林', icon: '🌲', price: 0, desc: '冲绳本岛北部的世界自然遗产，亚热带雨林罩住整片山丘。山原秧鸡与琉球兔在这里独居千万年，踏进苔径像闯入史前小岛。' },
  { id: 'oknp_zamami', name: '座间味岛', icon: '🐢', price: 3000, desc: '庆良间的珊瑚离岛，海水透明到小船像悬在半空。夏天海龟会游到岸边产卵，浮潜几步就能与它同游，小村慢得让人舍不得走。' },
  { id: 'oknp_tokashiki', name: '渡嘉敷岛', icon: '🏖️', price: 3000, desc: '庆良间最大的离岛，阿波连海滩的沙细白如粉。快船三十五分钟就能到，租辆小车环岛，随停随跳进蓝里，是最放松的半天。' }
);

/* ================= data/world/asia/JP/okinawa/okn_02_gifts.js ================= */
/* 冲绳县 分册02：特色周边（琉球美食/南国手信/海岛体验/离岛住宿） */
window.OKN_GIFTS = window.OKN_GIFTS || [];
window.OKN_GIFTS.push(
  /* ---- 琉球美食（沿用原条目） ---- */
  { id: 'okinawa_soba', name: '冲绳荞麦面', icon: '🍜', tag: '食', type: '美食', price: 800, desc: '其实不是荞麦面，是小麦面配软糯五花肉与鱼板。汤头鲣鱼香浓，桌上一罐岛辣椒是隐藏挑战。' },
  { id: 'okinawa_goya', name: '苦瓜炒杂烩', icon: '🥒', tag: '食', type: '美食', price: 900, desc: '岛苦瓜与午餐肉、鸡蛋同炒，微苦回甘。冲绳人长寿饮食的代表菜，配白饭能吃两碗。' },
  { id: 'okinawa_taco_rice', name: '塔可饭', icon: '🍚', tag: '食', type: '美食', price: 800, desc: '塔可碎肉浇在白饭上加番茄生菜，美式墨西哥混血快餐。美军基地文化的"意外遗产"，吃了都说香。' },
  { id: 'okinawa_pork', name: '拉法帖·猪蹄料理', icon: '🍖', tag: '食', type: '美食', price: 2500, desc: '冲绳人"除叫声外全吃"的猪文化代表。猪蹄炖到胶质黏唇，配泡盛酒是本地大爷的最爱。' },
  { id: 'okinawa_souki', name: '香檬汁', icon: '🍋', tag: '食', type: '饮品', price: 400, desc: '岛香檬（シークヮーサー）酸得清爽，兑水或入泡盛。长寿之岛的"维C炸弹"，一喝上头。' },
  { id: 'okinawa_awamori', name: '泡盛', icon: '🍶', tag: '食', type: '饮品', price: 1500, desc: '琉球古法蒸馏米酒，度数高但口感圆润。兑香檬加冰是"冲绳标配"，酒瓶上的岁月标记是"古酒"。' },
  { id: 'okinawa_benimo', name: '红芋挞·雪姬盐', icon: '🍠', tag: '食', type: '特产', price: 800, desc: '紫薯做的红芋挞紫色控必买，"雪盐"饼干用冲绳盐微甜带咸。机场手信区的"紫色风暴"。' },
  { id: 'okinawa_shisa', name: '风狮爷（Shisa）', icon: '🦁', tag: '衣', type: '文创', price: 2000, desc: '屋顶与门口张口的狮子陶偶，一只张嘴一只闭嘴，驱邪纳福。买一对摆家里，琉球门神上岗。' },
  { id: 'okinawa_bingata', name: '红型染布艺', icon: '🎨', tag: '衣', type: '文创', price: 3500, desc: '琉球王族的"红型"染布，热带花鸟配色大胆。做成杯垫、手机壳，一秒入南国。' },
  { id: 'okinawa_snorkel', name: '浮潜·青之洞窟', icon: '🤿', tag: '玩', type: '体验', price: 5000, desc: '真荣田岬的海蚀洞里，阳光穿透水面反射出神秘蓝光。不会游泳也能全程教练带着，鱼群就在脸旁边。' },
  { id: 'okinawa_diving', name: '潜水看海龟', icon: '🐢', tag: '玩', type: '体验', price: 9000, desc: '持证潜水员去庆良间群岛，与海龟同框概率极高。海底的蓝色静谧，上来后话都变少——震撼的。' },
  { id: 'okinawa_parasail', name: '海上拖伞', icon: '🪂', tag: '玩', type: '体验', price: 6000, desc: '快艇把你和降落伞送上五十米高空，俯瞰珊瑚礁分层蓝。海风很大、视野无敌，尖叫会被吹回嘴里。' },
  { id: 'okinawa_eisa', name: '太鼓EISA表演', icon: '🥁', tag: '玩', type: '体验', price: 1200, desc: '琉球传统EISA舞配上太鼓与三线，节奏一响手脚自动打拍。游客也能跟着围圈跳，气氛拉满。' },
  { id: 'okinawa_hotel', name: '海边度假酒店', icon: '🏨', tag: '住', type: '住宿', price: 20000, desc: '恩纳村悬崖边的度假酒店，泳池连着大海。躺在床上听浪，阳台上喝香檬气泡水看日落。' },
  /* ---- 新增·琉球美食与饮品 ---- */
  { id: 'okng_umibudo', name: '海葡萄', icon: '🍇', tag: '食', type: '美食', price: 800, desc: '一串串圆润得像迷你葡萄，蘸酱油醋咬下去“啵啵”爆汁。海水味带甜回甘，是冲绳居酒屋里最抢手的一口绿。' },
  { id: 'okng_sataandagi', name: '炸糖球·萨塔安达基', icon: '🍩', tag: '食', type: '美食', price: 200, desc: '黑糖面糊炸出的冲绳版甜甜圈，外壳脆、内里软。路边小摊现炸最香，热乎乎咬一口，糖浆顺着嘴角流，是庶民甜味。' },
  { id: 'okng_juicy', name: '冲绳蒸饭（ジューシー）', icon: '🍚', tag: '食', type: '美食', price: 600, desc: '猪肉、香菇与胡萝卜同米蒸透的乡土炊饭，鲜味渗进每粒米。路边食堂一碗配汤，落胃程度直追妈妈的手艺。' },
  { id: 'okng_sanpin', name: '香片茶', icon: '🍵', tag: '食', type: '饮品', price: 200, desc: '冲绳人饭桌上的茉莉花茶，几乎家家常备。清爽花香解腻回甘，配金楚糕或冲绳荞麦面，就是最地道的岛上组合。' },
  { id: 'okng_orion', name: '猎户座啤酒（Orion）', icon: '🍺', tag: '食', type: '饮品', price: 500, desc: '冲绳人自己的啤酒品牌，麦香清冽像海风过喉。傍晚屋顶开一瓶冰镇生啤，配苦瓜炒蛋，是这座岛公认的快乐公式。' },
  { id: 'okng_chinsuko', name: '金楚糕', icon: '🍪', tag: '食', type: '特产', price: 500, desc: '琉球王朝就有的传统点心，猪油砂糖烤到沙沙化口。原味、黑糖与盐味各有拥趸，配一杯香片茶能吃出王朝下午茶。' },
  { id: 'okng_shiosai', name: '雪盐（盐屋）', icon: '🧂', tag: '食', type: '特产', price: 600, desc: '宫古岛深海海水晾晒出的盐，细白如雪，咸里带矿物回甘。撒在烤肉、沙拉或甜点上，一小罐就能撑起半间厨房的调味。' },
  { id: 'okng_mozuku', name: '水云醋·海蕴', icon: '🥗', tag: '食', type: '特产', price: 600, desc: '冲绳近海的水云藻加醋腌渍，滑溜溜、酸溜溜，最是开胃。当地人当小菜配塔可饭，被称为海里长出的“长寿前菜”。' },
  /* ---- 新增·南国手信文创 ---- */
  { id: 'okng_ryukyuglass', name: '琉球玻璃杯', icon: '🎐', tag: '衣', type: '文创', price: 3000, desc: '回收玻璃手工吹出的杯碗，气泡与渐层每一件都不同。对着光看，杯壁里像封存着一小片冲绳的海与天空。' },
  { id: 'okng_yachimun', name: '壶屋烧陶器', icon: '🏺', tag: '衣', type: '文创', price: 2500, desc: '那霸壶屋窑的粗陶杯碗，土釉烧出温润的颗粒手感。装香片茶或泡盛都合适，杯沿的窑变落灰，带着冲绳泥土的温度。' },
  { id: 'okng_sanshin', name: '三线（迷你版）', icon: '🪕', tag: '玩', type: '文创', price: 5000, desc: '琉球三弦的迷你摆件，蛇皮琴面配牛角拨片，摆在架子上也有南国气场。真品能学两指扫弦，一拨就是“安里屋”的调子。' },
  { id: 'okng_kariyushi', name: '花衬衫·かりゆし', icon: '👕', tag: '衣', type: '服饰', price: 3000, desc: '冲绳男性连上班、喝喜酒都穿的花衬衫，正式感与度假感兼得。图案从扶桑花到泡盛瓶，套上它，肩膀自动就松了下来。' },
  /* ---- 新增·海岛体验与离岛住宿 ---- */
  { id: 'okng_sanshin_taiken', name: '三线弹奏体验', icon: '🎵', tag: '玩', type: '体验', price: 2500, desc: '老师手把手教你按弦，十分钟就能弹出“安里屋小调”。椰影下指法其实不难，难的是忍住不跟着歌词哼出声音。' },
  { id: 'okng_glass_taiken', name: '琉球玻璃吹制体验', icon: '🥃', tag: '玩', type: '体验', price: 3500, desc: '匠人握着你的手，把烧红的玻璃泡吹成专属杯盏。歪斜与气泡都是手作的证据，冷却后刻上名字，第二天就能带回纪念。' },
  { id: 'okng_minpaku', name: '离岛民宿之夜', icon: '🏡', tag: '住', type: '住宿', price: 9000, desc: '在座间味或渡嘉敷的岛民家住一晚，含早晚餐和房东的真心话。夜里安静到只剩虫鸣与银河，清晨被鸡叫而非闹钟叫醒。' }
);

/* ================= data/world/asia/JP/okinawa/okn_03_stories.js ================= */
/* 冲绳县 分册03：奇闻趣事（琉球信仰/战后记忆/传统工艺/岛上生活） */
window.OKN_STORIES = window.OKN_STORIES || [];
window.OKN_STORIES.push(
  /* ---- 沿用原条目 ---- */
  { id: 'okinawa_story_changshou', name: '长寿之岛的饮食密码', icon: '🥗', desc: '冲绳曾是全球百岁老人密度最高地区之一，苦瓜、豆腐、海藻、猪肉均衡吃法被称为"冲绳膳食"。长寿文化成了岛上的软实力。' },
  { id: 'okinawa_story_shisa', name: '风狮爷的公母之分', icon: '🦁', desc: '张嘴的吸福气、闭嘴的守福气，一对风狮爷各司其职。岛上房顶、路口、学校门口都有，风格从呆萌到凶悍任选。' },
  { id: 'okinawa_story_mekong', name: '琉球王国的"万国津梁"', icon: '⛵', desc: '琉球王国自称"万国津梁"（四海桥梁），靠朝贡贸易富甲一方。首里城里的钟铭至今写着这份开放与骄傲。' },
  { id: 'okinawa_story_kokuba', name: '黑潮之海的鲸鲨', icon: '🐋', desc: '美丽海水族馆人工饲养鲸鲨，游客隔着玻璃与七米巨鱼对视。馆方说：看它游一圈，胜过看十部海洋纪录片。' },
  { id: 'okinawa_story_hanabi', name: '离岛的慢船', icon: '⛴️', desc: '渡嘉敷岛慢船单程两小时，甲板上能睡一觉。离岛游客多是本地家庭，这种"慢"正是冲绳的疗愈配方。' },
  { id: 'okinawa_story_onami', name: '台风天的"休岛"', icon: '🌀', desc: '冲绳每年夏秋都要迎接几个台风，机场一关全岛放假。民宿老板说：台风天最有冲绳味——大家围炉吃泡盛等风走。' },
  /* ---- 新增·琉球信仰与岛的历史 ---- */
  { id: 'okns_eisa', name: '盂兰盆的EISA舞', icon: '🥁', desc: '旧历盂兰盆节前后，冲绳年轻人组成队伍打太鼓跳EISA，一路送祖灵回海。鼓声与唱念响到深夜，是全岛最燃的夏日仪式。' },
  { id: 'okns_niraikanai', name: 'ニライカナイ，海那边的乐土', icon: '🌊', desc: '琉球信仰相信神明住在海那边的“ニライカナイ”，每年驾浪而来赐下丰收。面向东方祈福的仪式，让每一道海浪都像神的脚步。' },
  { id: 'okns_kijimuna', name: 'キジムナー，榕树精灵', icon: '🌳', desc: '传说榕树下住着红发小鬼キジムナー，爱恶作剧却也重义气。岛上有什么解释不清的怪事，冲绳人一句“准是精灵闹的”就翻篇。' },
  { id: 'okns_higanzakura', name: '一月就开的寒绯樱', icon: '🌸', desc: '日本最早的樱花在冲绳，每年一月从本部一路开到那霸近郊。吊钟形的粉红花朵挂满枝头，比东京的春天整整早了两个月。' },
  { id: 'okns_shurijo_fire', name: '首里城的那场火', icon: '🔥', desc: '2019年深夜，首里城正殿与南北殿在火灾中损毁。两年后重建工程动工，守礼门先行恢复金红，全岛都等着那座王城回家。' },
  { id: 'okns_okinawasen', name: '慰灵之日，冲绳战', icon: '🕊️', desc: '冲绳战役让岛上约四分之一的居民失去性命，6月23日被定为“慰灵之日”。糸满的平和祈念公园里，石碑上的名字在海风中沉默。' },
  { id: 'okns_kokusai', name: '国际通，从焦土到一英里', icon: '🛍️', desc: '战后那霸几乎成焦土，人们聚在今天的国际通一带摆摊求生。从美军时代的黑市到观光大道，这条路每一步都刻着冲绳人的韧性。' },
  /* ---- 新增·传统工艺与音乐 ---- */
  { id: 'okns_glass', name: '空瓶吹出的琉球玻璃', icon: '🎐', desc: '战后美军基地的汽水瓶没人要，冲绳匠人把它们熔了吹成杯碗。蓝绿的气泡与歪斜的杯口意外走红，成了南国最抢手的手信。' },
  { id: 'okns_tsuboya_kama', name: '壶屋烧的三百年窑火', icon: '🏺', desc: '琉球王国时期，全岛的陶器几乎都出自那霸壶屋的窑场。如今旧窑火还在烧，年轻匠人接过土与火的配方，守住这座岛的粗陶脾气。' },
  { id: 'okns_bingata_kings', name: '红型，王族的调色盘', icon: '🎨', desc: '红型是琉球王族的礼服染布工艺，型纸与颜料全取天然。扶桑、凤凰与流水纹配色浓烈，藏着海岛宫廷最骄傲的审美巅峰。' },
  { id: 'okns_sanshin', name: '一把三线，装下乡愁', icon: '🪕', desc: '三线由萨摩传入的三弦演变而来，琉球人却弹出自己的魂。海外移民聚会上，一句“岛呗”响起，冲绳人总是先笑后湿眼眶。' },
  { id: 'okns_awamori_koji', name: '泡盛与黑麹菌', icon: '🍶', desc: '泡盛用泰国香米配黑麹发酵再蒸馏，新酒辛辣、陈年转柔。陶瓮上标记年份的“古酒”越老越贵，是冲绳人酿给时间喝的酒。' },
  { id: 'okns_karate', name: '空手道，从琉球走向奥运', icon: '🥋', desc: '空手的前身是琉球的“唐手”，冲绳人把徒手格斗揉成一套武道。2020年它首次登上奥运，家乡人笑着调侃：全世界都来交学费了。' },
  /* ---- 新增·岛上新生活 ---- */
  { id: 'okns_yuirail', name: 'ゆいレール，那霸的天空', icon: '🚈', desc: '冲绳唯一的铁道是那霸单轨电车，从机场直通首里城脚下。车厢掠过民宅屋顶与珊瑚海，本地人笑称它是“最悠闲的空中看台”。' },
  { id: 'okns_yanbaru_bird', name: '山原的珍稀住民', icon: '🦜', desc: '世界自然遗产やんばる的密林里，住着不会飞的山原秧鸡与琉球长尾鼠。它们在孤悬的海岛上独自演化千年，成了“仅此一家”的冲绳限定。' },
  { id: 'okns_uchinaguchi', name: 'めんそーれ，冲绳话', icon: '🗣️', desc: '冲绳方言叫“うちなーぐち”，一句“めんそーれ”就是“欢迎光临”。年轻一代说得少了，如今咖啡店与课本都在努力复兴它。' }
);

/* ================= data/world/asia/JP/okinawa/okinawa.js ================= */
/* ============ 日本·冲绳县（完全版·分册组装） ============
 * 分册：okn_01景点 / okn_02周边 / okn_03趣事。
 * 叙事主线：那霸与首里 / 本岛中北部 / 离岛与南部半岛。
 */
(function () {
  window.TRAVEL_CITIES = window.TRAVEL_CITIES || [];
  window.TRAVEL_CITIES.push({
    id: 'okinawa',
    name: '冲绳县',
    country: '日本',
    cc: 'JP',
    flag: '🇯🇵',
    region: '日本·冲绳',
    hero: '🐠',
    desc: '日本最南端的群岛天堂：珊瑚礁泻湖蓝得发光，琉球文化带着南国松弛感，一颗香檬配一碗冲绳荞麦面就是海岛日常。',
    travel: [{ name: '飞机', icon: '✈️', cost: 2400 }, { name: '邮轮', icon: '🛳️', cost: 3200 }],
    visa: { cost: 300, note: '日本单次旅游签证（旅行社代办）' },
    spots: (window.OKN_SPOTS = window.OKN_SPOTS || []),
    souvenirs: (window.OKN_GIFTS = window.OKN_GIFTS || []),
    stories: (window.OKN_STORIES = window.OKN_STORIES || [])
  });
})();

/* ================= data/world/asia/JP/osaka/osa_01_spots.js ================= */
/* 大阪府 分册01：景点圣地（天下厨房/水都大阪/城与史/关西近郊） */
window.OSA_SPOTS = window.OSA_SPOTS || [];
window.OSA_SPOTS.push(
  /* ---- 天下厨房与闹市（沿用原条目） ---- */
  { id: 'osaka_doutonbori', name: '道顿堀', icon: '🏮', price: 0, desc: '巨型霓虹招牌的怪兽电寸场：格力高跑者、蟹道乐大螃蟹。河边一边啃章鱼烧一边看灯，大阪夜色的正确打开方式。' },
  { id: 'osaka_kuromon', name: '黑门市场', icon: '🐟', price: 0, desc: '"大阪的厨房"，一百多家摊位现开海胆、现烤和牛。边走边吃是默认规则，摊主招呼声比商品还热。' },
  { id: 'osaka_shinsaibashi', name: '心斋桥筋商店街', icon: '🛍️', price: 0, desc: '600米带顶棚的购物长廊，药妆店密度全日本第一。从潮牌到百年老铺，走完腿已软、袋已满。' },
  { id: 'osaka_tsutenkaku', name: '通天阁·新世界', icon: '🗼', price: 900, desc: '大阪的"埃菲尔铁塔"，下层是老式居酒屋与串炸店。塔顶的福神"Billiken"摸脚许愿，据说愿望会实现。' },
  { id: 'osap_hozenji', name: '法善寺横丁', icon: '⛩️', price: 0, desc: '石板小路上的不动明王被游客泼水披满青苔，旁边"夫妇善哉"红豆汤一碗两人份。夜里灯笼亮起最有江户味。' },
  { id: 'osap_doguyasuji', name: '千日前道具屋筋', icon: '🔪', price: 0, desc: '料理道具一条街，章鱼烧铁板、御好烧铲、巨型食品模型铺满橱窗。厨师与主妇都来这里"进货"。' },
  { id: 'osap_tsuruhashi', name: '鹤桥·烧肉一条街', icon: '🥩', price: 0, desc: '大阪的烤肉圣地，韩式与日式烧肉店隔街对望。炭火味从傍晚飘到深夜，性价比高到扶墙出。' },
  { id: 'osap_amerikamura', name: '美国村', icon: '🎸', price: 0, desc: '难波旁的年轻人街区，二手古着、livehouse与涂鸦墙。三角公园聚集着奇装异服的大阪青年。' },
  { id: 'osap_tenjinbashi', name: '天神桥筋商店街', icon: '🏮', price: 0, desc: '全长2.6公里的日本最长商店街，从生活杂货到章鱼烧应有尽有。逛到底正好走到大阪天满宫。' },
  /* ---- 大阪城与水都（沿用原条目） ---- */
  { id: 'osaka_castle', name: '大阪城天守阁', icon: '🏯', price: 600, desc: '丰臣秀吉的"太阁之城"，白墙绿瓦配金色虎纹装饰。护城河与巨石城墙气势仍在，顶层俯瞰大阪全景。' },
  { id: 'osap_rekishi', name: '大阪历史博物馆', icon: '🏛️', price: 0, desc: '建在难波宫遗址旁的玻璃大楼，底层直接透视千年前宫殿。从古坟时代讲到现代，大阪的前世今生一层看完。' },
  { id: 'osap_shitennoji', name: '四天王寺', icon: '🛕', price: 0, desc: '圣德太子于公元593年创建，日本最古老的官寺之一。中心伽蓝保留飞鸟时代布局，每月集市香火热闹。' },
  { id: 'osap_nakanoshima', name: '中之岛·堂岛川', icon: '🏛️', price: 0, desc: '夹在两条河中间的"水都之岛"，大阪市中央公会堂与中之岛图书馆红砖典雅。河畔慢跑，水都的温柔都在风里。' },
  { id: 'osap_nambapark', name: '难波公园', icon: '🌿', price: 0, desc: '商场上盖的空中花园，层层退台种满绿植。走上去像爬一座绿色的山，城市与公园在这里重叠。' },
  { id: 'osap_zoheikyoku', name: '造币局·樱花通道', icon: '🌸', price: 0, desc: '大阪造币局每年春天只开放一周"樱花通道"，几百种珍稀樱树一路开满。预约制下依然挤满全城看花人。' },
  { id: 'osap_tenmangu', name: '大阪天满宫', icon: '⛩️', price: 0, desc: '供奉学问之神菅原道真，七月天神祭是大阪夏季最盛大的祭典。考生考前必来求"学问守"。' },
  /* ---- 现代地标（沿用原条目） ---- */
  { id: 'osaka_usj', name: '日本环球影城', icon: '🎢', price: 8600, desc: '哈利波特魔法世界、马里奥园区、侏罗纪漂流。黄油啤酒无酒精但够甜，排队两小时喊一声"值得"。' },
  { id: 'osap_umeda', name: '梅田蓝天大厦·空中庭园', icon: '🏙️', price: 0, desc: '两座高楼顶层相连的"空中庭园"，透明回廊悬在四十层高空。傍晚看大阪城方向的日落，是梅田的浪漫。' },
  { id: 'osap_abenoharukas', name: '阿倍野HARUKAS300', icon: '🗼', price: 1800, desc: '日本最高摩天楼顶层的空中回廊，三百米高度三百六十度看关西。玻璃地板吓腿软，夜景比通天阁更璀璨。' },
  { id: 'osap_kaiyukan', name: '大阪海游馆', icon: '🐋', price: 2000, desc: '世界最大级水族馆，中央大水槽养着鲸鲨。从环太平洋的"天保山海岸"一路走到深海，孩子眼睛都看直了。' },
  { id: 'osap_banpaku', name: '万博纪念公园·太阳之塔', icon: '🌞', price: 0, desc: '1970年大阪万博的象征，冈本太郎的太阳之塔如今依然昂首。园内公园与美术馆，日本人童年的远足记忆。' },
  { id: 'osap_nakazakicho', name: '中崎町', icon: '☕', price: 0, desc: '昭和老民房改造的文艺街区，古着店、喫茶店藏在小巷里。不赶时间的话，找一家百年町屋坐一下午。' },
  /* ---- 近郊与趣学 ---- */
  { id: 'osap_ikeda', name: '池田·日清泡面博物馆', icon: '🍜', price: 0, desc: '世界上第一碗方便面的发明地。亲手做一碗"鸡汤拉面"，画自己的杯面包装，大人小孩都玩得不想走。' },
  { id: 'osap_minoh', name: '箕面·瀑布与红叶', icon: '🍁', price: 0, desc: '大阪近郊的森林山谷，箕面瀑布落差三十三米。秋天红叶配瀑布，冬天还能尝限定"红叶天妇罗"。' },
  { id: 'osaka_sumiyoshi', name: '住吉大社', icon: '⛩️', price: 0, desc: '日本住吉造神社的总本社，倒立石"反桥"陡得让人手脚并用。求航海平安千年香火不断。' }
);

/* ================= data/world/asia/JP/osaka/osa_02_gifts.js ================= */
/* 大阪府 分册02：特色周边（粉もん名物/大阪商人/球团应援/市井体验） */
window.OSA_GIFTS = window.OSA_GIFTS || [];
window.OSA_GIFTS.push(
  /* ---- 粉もん与街头味（沿用原条目） ---- */
  { id: 'osaka_takoyaki', name: '章鱼烧', icon: '🐙', tag: '食', type: '美食', price: 600, desc: '铁盘翻飞转出金黄圆球，章鱼块烫嘴、柴鱼片跳舞。外脆内流心，大阪的"灵魂街头小吃"。' },
  { id: 'osaka_okonomiyaki', name: '御好烧', icon: '🥞', tag: '食', type: '美食', price: 1200, desc: '"想加啥加啥"的铁板煎饼，木鱼花在热饼上跳舞。摊主拿两把小铲"咔咔"分割，仪式感满分。' },
  { id: 'osaka_kushikatsu', name: '串炸', icon: '🍢', tag: '食', type: '美食', price: 1200, desc: '裹糠深炸的肉串蔬菜串，蘸酱一口一个。铁规：酱料池公用、禁止回蘸！桌上写着"二次蘸酱禁止"。' },
  { id: 'osaka_kani', name: '蟹道乐螃蟹宴', icon: '🦀', tag: '食', type: '美食', price: 12000, desc: '巨型雪蟹从刺身到烤蟹、蟹肉釜饭一蟹六吃。门口的机械大螃蟹是合影地标，吃蟹是"到此一游"的正式手续。' },
  { id: 'osaka_ikayaki', name: '大阪烧鱿鱼饼', icon: '🦑', tag: '食', type: '美食', price: 500, desc: '街头铁板现压的鱿鱼薄饼刷甜酱油。边走边吃、纸托接汁，是大阪人从小练的技能。' },
  { id: 'osaka_ramen_ish', name: '吃倒太郎', icon: '🍙', tag: '食', type: '美食', price: 800, desc: '松屋式的"倒灶"文化：便宜大碗吃到扶墙。大阪话"kuidaore"（吃到破产）是这座城市给吃货的勋章。' },
  { id: 'osag_551', name: '551蓬莱·豚まん', icon: '🥟', tag: '食', type: '美食', price: 600, desc: '大阪站台人手一袋的猪肉包，皮松肉香汁水足。刚出炉烫手，出差大阪的第一口犒劳。' },
  { id: 'osag_kitsuneudon', name: 'きつねうどん', icon: '🍜', tag: '食', type: '美食', price: 500, desc: '关西风的高汤乌冬，上面卧一片吸满汤汁的油豆腐。汤清味浓，大阪人的胃就这样被温柔接住。' },
  { id: 'osag_sujikon', name: 'すじこん煮込み', icon: '🍲', tag: '食', type: '美食', price: 800, desc: '牛筋与魔芋在关东煮里咕嘟一晚，甜咸入味。深夜居酒屋来一杯配啤酒，是大阪的下町犒赏。' },
  { id: 'osag_takosen', name: 'たこせん', icon: '🍘', tag: '食', type: '美食', price: 400, desc: '章鱼烧压进脆饼里的街边零食，一口章鱼一口饼。边走边"咔哧"，大阪街头的高性价比快乐。' },
  { id: 'osaka_sake', name: '日本酒·啤酒工厂', icon: '🍺', tag: '食', type: '饮品', price: 1000, desc: '朝日、麒麟工厂参观免费试饮。大阪人喝酒不矜持，"干杯"一声整条居酒屋街都会回头。' },
  { id: 'osag_highball', name: '立ち飲みハイボール', icon: '🥃', tag: '食', type: '饮品', price: 400, desc: '站着喝的威士忌苏打，大阪的"立ち飲み"文化。一杯气泡冲上天灵盖，店家的下酒小菜随便拿。' },
  { id: 'osag_ebisen', name: '大阪えびせんべい', icon: '🍤', tag: '食', type: '特产', price: 500, desc: '整只虾烤进米饼里，香脆带鲜。千日前名物，一袋接一袋停不下手，配茶正好。' },
  { id: 'osag_dashikombu', name: '出汁昆布套装', icon: '🍥', tag: '食', type: '特产', price: 1000, desc: '关西高汤的灵魂是昆布出汁。买一包利尻昆布回家，味噌汤立刻有大阪的味道。' },
  /* ---- 大阪手信与文创（沿用原条目+新增） ---- */
  { id: 'osaka_glico', name: '格力高跑者周边', icon: '🏃', tag: '衣', type: '文创', price: 1500, desc: '招牌跑者姿态做成钥匙扣、T恤、年轮蛋糕盒。学跑者同款举手姿势拍照，是道顿堀的打卡宪法。' },
  { id: 'osaka_banpaku', name: '万博纪念品·沙漏', icon: '⏳', tag: '衣', type: '文创', price: 1500, desc: '1970世博会"太阳之塔"文创与吹气玩偶。大阪人对外来文化的热情，五十年前就已经"世界级"。' },
  { id: 'osag_tigers', name: '阪神虎应援周边', icon: '🐯', tag: '玩', type: '文创', price: 2000, desc: '甲子园球场外的阪神虎毛巾与吉祥物。大阪人赢球要跳道顿堀，输球就低头回家——虎迷最诚实。' },
  { id: 'osag_kinnotora', name: '大阪城·金の虎钥匙扣', icon: '🗝️', tag: '玩', type: '文创', price: 1200, desc: '天守阁屋脊的金色虎形装饰做成钥匙扣。把太阁之城的威风挂进钥匙串。' },
  { id: 'osag_billiken', name: '通天阁·ビリケン御守', icon: '👣', tag: '玩', type: '文创', price: 1000, desc: '福神 Billiken 的迷你御守，先许愿再摸脚。挂在包上，走到哪好运跟到哪。' },
  /* ---- 市井体验与住宿（沿用原条目+新增） ---- */
  { id: 'osaka_subway', name: '大阪地铁一日券', icon: '🚇', tag: '行', type: '体验', price: 800, desc: '御堂筋线纵贯南北，大阪地铁报站自带大阪腔。一天坐遍梅田、难波、天王寺，路痴也容易迷路成精。' },
  { id: 'osaka_ferris', name: '天保山摩天轮', icon: '🎡', tag: '玩', type: '体验', price: 800, desc: '曾经的世界最大摩天轮，四色车厢里有透明地板款。转到顶端能望见明石海峡大桥和机场跑道。' },
  { id: 'osaka_taiko', name: '太鼓达人游戏机', icon: '🥁', tag: '玩', type: '体验', price: 200, desc: '游戏中心的两根鼓棒，敲一局太鼓达人。大阪人打鼓手速与方言一样快，围观者自动鼓掌。' },
  { id: 'osag_takoyakijc', name: '章鱼烧手作体验', icon: '👨‍🍳', tag: '玩', type: '体验', price: 2000, desc: '跟着店主打转章鱼烧，翻面时机全凭手感。自己那锅歪七扭八，老板笑说"大阪人不在乎长相"。' },
  { id: 'osag_chickenramen', name: '日清杯面DIY', icon: '🍜', tag: '玩', type: '体验', price: 500, desc: '在泡面发明纪念馆亲手压制一包"鸡汤拉面"，再画专属杯身。出锅那刻，发明家的快乐你懂了。' },
  { id: 'osag_bunraku', name: '文乐·人形净琉璃观剧', icon: '🎎', tag: '玩', type: '体验', price: 3000, desc: '国立文乐剧场看人形净琉璃，三味线、太夫与操偶师三位一体。大阪的传统，比想象中更带劲儿。' },
  { id: 'osag_yoshimoto', name: '吉本新喜剧观览', icon: '🎤', tag: '玩', type: '体验', price: 3000, desc: 'なんばグランド花月看吉本艺人现场漫才与舞台剧。大阪人把笑当成正经事，全场笑得前仰后合。' },
  { id: 'osaka_hotel', name: '难波商务酒店', icon: '🏨', tag: '住', type: '住宿', price: 10000, desc: '三平米精致小房，洗漱品齐全、便利店楼下。大阪住宿性价比之王，出门就是美食街。' }
);

/* ================= data/world/asia/JP/osaka/osa_03_stories.js ================= */
/* 大阪府 分册03：奇闻趣事（太阁之城/商都大阪/粉もん文化/祭典笑点） */
window.OSA_STORIES = window.OSA_STORIES || [];
window.OSA_STORIES.push(
  /* ---- 沿用原条目 ---- */
  { id: 'osaka_story_kuidaore', name: '"吃到破产"的城市', icon: '🍽️', desc: '大阪话"kuidaore"意为"吃到破产"，是这座城给吃货的骄傲称号。大阪人看到好吃的，第一反应不是拍照，是冲上去。' },
  { id: 'osaka_story_glico', name: '格力高跑者的"挥手学"', icon: '🏃', desc: '道顿堀跑者霓虹牌换了六代，姿势始终是双手举起的胜利造型。游客拍照必须学这个手势，算是暗号。' },
  { id: 'osaka_story_zhashi', name: '串炸"禁止回蘸"', icon: '🚫', desc: '公用蘸酱池里不许把咬过的串再放回去，是百年铁规。违反会被店员温柔提醒，被同桌朋友无情嘲笑。' },
  { id: 'osaka_story_yunishiki', name: '大阪人自来熟', icon: '🗣️', desc: '排队的大阪大爷会主动跟你唠十分钟家常，商店街摊主见人就喊"来尝尝嘛"。东京人内敛、大阪人自来熟，是日本公认南北差异。' },
  { id: 'osaka_story_billiken', name: '摸脚的福神', icon: '🦶', desc: '通天阁的福神 Billiken 是"会带来好运的神"，先许愿再摸它的脚。一百年来它的脚底被摸得锃亮。' },
  { id: 'osaka_story_tanaka', name: '霓虹灯牌的"怪兽电寸场"', icon: '💡', desc: '道顿堀的蟹道乐机械蟹会挥钳、河豚灯笼会鼓气。大阪人不满足于灯牌，直接把店铺招牌做成了机械动物园。' },
  /* ---- 太阁之城与历史 ---- */
  { id: 'osas_taiko', name: '丰臣秀吉与大阪城', icon: '🏯', desc: '太阁丰臣秀吉以大阪城为据点一统天下，"太阁之城"盛极一时。大坂之阵后城池尽毁，如今的天守阁是后人重建的模样。' },
  { id: 'osas_ishigaki', name: '大阪城的巨石石垣', icon: '🪨', desc: '护城河畔的巨石石垣有的重达上百吨，当年各地大名被征来"普请"运石。石头上还能找到各藩的刻印。' },
  { id: 'osas_shitennoji', name: '四天王寺与圣德太子', icon: '🛕', desc: '圣德太子为弘扬佛法而建四天王寺，布局照搬中国伽蓝。这里是大阪历史的地标，比大阪城古老一千多年。' },
  { id: 'osas_shonin', name: '商人的大阪', icon: '💹', desc: '江户时代大阪是"天下的厨房"，米市与商行云集。商人讲规矩、算得精，连笑都带着生意经——"笑う門には福来る"。' },
  { id: 'osas_dotonbori_geki', name: '道顿堀曾是剧场街', icon: '🎭', desc: '江户末期的道顿堀是剧场与芝居町，中座、浪花座一字排开。后来剧场落幕，霓虹与美食接棒成了新的主角。' },
  { id: 'osas_bunraku', name: '文乐与净琉璃', icon: '🎎', desc: '人形净琉璃（文乐）在大阪被奉为传统艺术，太夫的唱念与三味线催人泪下。联合国非遗，大阪的"心的戏剧"。' },
  { id: 'osas_chikinramen', name: '方便面诞生在大阪', icon: '🍜', desc: '安藤百福在池田的自家后院发明了第一碗鸡汤拉面，日清泡面博物馆就建在原址。全世界夜宵的起点，是阪神间的小屋。' },
  /* ---- 市井笑点 ---- */
  { id: 'osas_hougen', name: '大阪话与"マクド"', icon: '🗣️', desc: '大阪人说麦当劳叫"マクド"，章鱼烧店叫"たこやき"。关西腔抑扬顿挫，问路像听落语，笑点全在语尾。' },
  { id: 'osas_okonomi', name: '粉もん的王国', icon: '🥞', desc: 'お好み焼き、たこ焼き、串カツ都是从大阪发祥的"粉もん"（面粉系）食物。大阪人坚信：面粉与铁板，是最幸福的材料。' },
  { id: 'osas_shinsekai', name: '新世界的下町魂', icon: '🏮', desc: '新世界是大阪最老的平民区之一，串炸店与柏青哥挤在通天阁下。物价便宜、人情热络，是"真正的下町大阪"。' },
  { id: 'osas_minami_kita', name: '南与北：难波与梅田', icon: '🗺️', desc: '大阪人把难波一带叫"南"（ミナミ）、梅田叫"北"（キタ）。年轻人混南、白领聚北，两个中心撑起整座城的活力。' },
  { id: 'osas_rakugo', name: '上方落语的笑', icon: '🎙️', desc: '落语分东京与上方两派，大阪上方落语更带市井烟火气。笑福亭、桂派的寄席（落语场）至今满座，笑声是大阪的特产。' },
  { id: 'osas_kuidaore_taro', name: '吃倒太郎与看板文化', icon: '🤖', desc: '道顿堀的"くいだおれ太郎"敲锣娃娃是店门吉祥物鼻祖，如今博物馆里还有他。大阪的招牌文化，先逗笑你再说。' },
  /* ---- 祭典与花火 ---- */
  { id: 'osas_tenjin', name: '天神祭的船上渡御', icon: '⛴️', desc: '天神祭是大阪夏季最大祭典，百艘彩船顺堂岛川而下，夜里奉纳花火照亮水面。大阪人的夏天，从天神祭开始。' },
  { id: 'osas_danji', name: '岸和田だんじり祭', icon: '🎪', desc: '大阪府岸和田的"山车祭"，几吨重的彩车在窄巷里疾驰急转。拉车大汉喊着号子，看的人捏一把汗又热血沸腾。' },
  { id: 'osas_sakura_tsuyu', name: '造币局樱花通道', icon: '🌸', desc: '造币局旁的樱花道每年只开一周，种着罕见的"红手毬""郁金樱"。关西人春天等这条通道，比等樱前线还心急。' }
);

