/* ================= data/world/asia/JP/saitama/sta_01_spots.js ================= */
/* 埼玉 分册01：景点圣地（小江户川越/秩父长瀞/行田古坟/都市与丘陵山野） */
window.STA_SPOTS = window.STA_SPOTS || [];
window.STA_SPOTS.push(
  /* ---- 沿用原条目（原样保留） ---- */
  { id: 'saitama_kasukabe', name: '春日部·蜡笔小新巡礼', icon: '🖍️', price: 0, desc: '野原一家"住在"春日部。车站小新涂装、双叶幼稚园原型、"小新桥"，全城都是小新。' },
  { id: 'saitama_chichibu', name: '秩父·长瀞', icon: '🏞️', price: 0, desc: '秩父夜祭（12月）与芝樱之丘（4月）。长瀞岩畳漂流，"东京人的秘境"。' },
  { id: 'saitama_tetsudo', name: '大宫铁道博物馆', icon: '🚆', price: 1000, desc: '火车迷圣地：新干线驾驶模拟器。蒸汽机车转车台演示，"铁道宅的天国"。' },
  { id: 'saitama_kawagoe', name: '川越·小江户', icon: '🏮', price: 0, desc: '"小江户"藏造老街与时间之钟。喜多院五百罗汉，"穿越江户"的近郊一日。' },
  { id: 'saitama_omiya', name: '大宫盆栽村·冰川神社', icon: '🌳', price: 0, desc: '世界级盆栽美术馆，百年松柏微缩山水。冰川神社"缘结石"，风铃祭夏天限定。' },
  { id: 'saitama_hikawa2', name: '羊山公园芝樱之丘', icon: '🌸', price: 0, desc: '四月十万株芝樱铺成粉色地毯。望整片"粉海"配秩父群山，"春天限定"。' },
  { id: 'saitama_rail', name: '铁道模型咖啡·铁立食', icon: '☕', price: 500, desc: '铁道主题咖啡店，模型火车绕店穿行。立食荞麦面"新干线上同款"。' },
  /* ---- 小江户·川越（扩容） ---- */
  { id: 'stap_kawagoe_kashiya', name: '川越·菓子屋横丁', icon: '🍬', price: 0, desc: '“江户味”的点心横丁藏在老街一角，米果、豆子糖与现烤红薯饼挤满窄巷。边走边尝，川越的甜从这条巷子开始。' },
  { id: 'stap_kawagoe_kitain', name: '川越·喜多院', icon: '🏯', price: 0, desc: '天台宗古刹喜多院香火绵延数百年，五百罗汉石像或笑或怒，神情个个不同。从江户城移筑而来的客殿，还留着德川家光的起居痕迹。' },
  /* ---- 秩父·长瀞的山与川（扩容） ---- */
  { id: 'stap_chichibu_mitsumine', name: '秩父·三峰神社', icon: '⛩️', price: 0, desc: '藏在秩父群山深处的灵峰神社，参道尽头立着罕见的“三柱鸟居”。山雾缭绕之间，狼形的石像默默守护着登山人。' },
  { id: 'stap_chichibu_jinja', name: '秩父·番场通夜祭舞台', icon: '🏮', price: 0, desc: '秩父夜祭以秩父神社前番场町为中心，屋台与笠鉾在路口轰轰对撞。平日安静的城下町，祭典夜里万头攒动、吆喝震天。' },
  { id: 'stap_nagatoro_hodosan', name: '长瀞·宝登山', icon: '🚡', price: 800, desc: '乘坐箱型缆车登上宝登山，山脚到山顶一路越过长瀞溪谷。早春蜡梅开成金黄一片，山顶神社前还能远眺秩父连山。' },
  { id: 'stap_nagatoro_momiji', name: '长瀞·月之石红叶公园', icon: '🍁', price: 0, desc: '深秋的长瀞是关东知名赏枫地，月之石红叶公园内枫树层层叠叠。红叶映着溪谷流水，日落前最是剔透好看。' },
  /* ---- 行田·水城与古坟（扩容） ---- */
  { id: 'stap_gyoda_oshiro', name: '行田·忍城与古代莲', icon: '🏰', price: 0, desc: '《傀儡之城》原型的忍城，曾是“水攻”也难破的坚城。城下池中夏晨“古代莲”纷纷绽放，粉白花朵衬着水城倒影，如梦如幻。' },
  { id: 'stap_gyoda_kofun', name: '行田·埼玉古坟群', icon: '🏺', price: 0, desc: '关东规模数一数二的古坟群散布在田间，稻荷山古坟出土的铁剑铭文贵为国宝。登上丸墓山古坟，田野与远山尽收眼底。' },
  /* ---- 埼玉市·新都心（扩容） ---- */
  { id: 'stap_iwatsuki_doll', name: '岩槻·人形之町', icon: '🎎', price: 0, desc: '日本市售人形约四成出自岩槻，町内工房、资料馆与小店连成散步路线。看职人为雏人形描眉点唇，传统的手艺都在这几笔里。' },
  { id: 'stap_saitama_superarena', name: '埼玉超级竞技场', icon: '🎤', price: 0, desc: '埼玉新都心的超大型多功能竞技场，开演唱会时可容纳数万人。舞台灯光一开，关东乐迷便从车站涌向这片“演出宇宙”。' },
  /* ---- 丘陵与山野（扩容） ---- */
  { id: 'stap_tokorozawa_totoro', name: '所泽·龙猫之森', icon: '🌳', price: 0, desc: '狭山丘陵还留着动画里的杂木林与水田，市民成立基金会买地护林。沿着散步道走，春有新绿、秋有芒草，好像随时能遇见龙猫。' },
  { id: 'stap_hanno_moomin', name: '饭能·姆明谷公园', icon: '🏰', price: 1800, desc: '北欧童话“姆明谷”落在饭能宫泽湖畔，蓝顶小屋、森林步道与湖面栈道一气呵成。坐上园内小火车，走进姆明一家的日常。' },
  { id: 'stap_hidaka_kinchakuda', name: '日高·巾着田彼岸花', icon: '🌺', price: 0, desc: '高丽川把河滩环成“巾着”形状，秋分前后彼岸花红毯般铺满草地。赤红花海配着流水与树影，是关东独有的秋季奇观。' },
  { id: 'stap_kasukabe_fuji', name: '春日部·牛岛之藤', icon: '🌸', price: 0, desc: '千年紫藤垂下串串花穗，开时如紫色瀑布倾泻，香气弥漫整片藤架。春末这场限定花期，让春日部一时人潮涌动。' },
  { id: 'stap_saitama_stadium', name: '埼玉体育场2002', icon: '⚽', price: 0, desc: '为日韩世界杯兴建的椭圆球场，如今是浦和红钻的主场。比赛日“红色海洋”声浪惊人，平日也可参加球场见学路线。' },
  { id: 'stap_yoshimi_hyakuana', name: '吉见·吉见百穴', icon: '🕳️', price: 0, desc: '古坟时代的横穴墓群如蜂巢般嵌在丘陵崖壁，大小洞穴层层排列。爬上崖顶，关东平原的田畴与远山一路在脚下展开。' },
  { id: 'stap_fukaya_eiichi', name: '深谷·涩泽荣一故里', icon: '🏛️', price: 0, desc: '深谷是“日本资本主义之父”涩泽荣一的出生地，生家与纪念馆保存完好。印上新万元钞的荣一像，让这座小城多了许多朝圣客。' },
  { id: 'stap_tobu_zoo', name: '宫代·东武动物公园', icon: '🦁', price: 2000, desc: '动物园加游乐园的复合型公园，稀有动物与过山车同场。白狮、水豚还有大象表演，一家人能在这里玩上一整天。' },
  { id: 'stap_kumagaya_shoten', name: '熊谷·妻沼圣天堂', icon: '✨', price: 0, desc: '妻沼圣天山欢喜院被称作“埼玉的日光东照宫”，圣天堂的极彩色雕刻与金箔华丽繁复。这座国宝小堂，藏着江户匠人的炫技之作。' }
);

