/* ================= data/world/asia/JP/sendai/snd_01_spots.js ================= */
/* 日本·仙台 分册01：景点圣地（青叶城与伊达家/松岛与三陆湾/温泉名汤/东北乡土） */
window.SND_SPOTS = window.SND_SPOTS || [];
window.SND_SPOTS.push(
  /* ---- 原档沿用条目 ---- */
  { id: 'sendai_matsushima', name: '松岛', icon: '⛵', price: 1500, desc: '日本三景之一，260余座岛屿铺满松绿色海湾。游船穿岛，圆通院与五大堂，"松岛浮舟"经典画面。' },
  { id: 'sendai_zuihoden', name: '瑞凤殿', icon: '🏯', price: 600, desc: '伊达政宗陵寝，桃山风格极尽奢华。古殿毁于战火后重建，夜枫点灯如金焰。' },
  { id: 'sendai_castle', name: '青叶城迹', icon: '⛰️', price: 0, desc: '伊达政宗居城遗址，政宗骑马铜像俯瞰仙台平原。夜景灯光，"杜都"的夜。' },
  { id: 'sendai_jozenji', name: '定禅寺通·勾当台', icon: '🌳', price: 0, desc: '榉树大道，夏天青叶祭、冬天光之页面。爵士咖啡与酒吧，"仙台的香榭丽舍"。' },
  { id: 'sendai_osaki', name: '多贺城·大崎八幡宫', icon: '⛩️', price: 0, desc: '大崎八幡宫是政宗下令建造的国宝，权现造黑金配色。".defaults 桃山艺术"巅峰。' },
  { id: 'sendai_aoba', name: '秋保温泉·作并温泉', icon: '♨️', price: 1500, desc: '仙台近郊两大道后，"日本三名汤"之一秋保。磊磊峡红叶与瀑布温泉。' },
  { id: 'sendai_zunda', name: '毛豆泥体验·仙台朝市', icon: '🌱', price: 0, desc: '仙台朝市"东北的厨房"，70家店挤在小巷。zunda 毛豆泥麻糬绿得可爱，现捣现吃。' },
  /* ---- 青叶城与伊达家（新增） ---- */
  { id: 'sndp_hirose', name: '广濑川·榴冈公园', icon: '🏞️', price: 0, desc: '广濑川穿城而过，两岸樱榉把仙台染成“杜之都”。黄昏河堤钓竿与散步客相伴，回望青叶城灯光渐亮，风里有草木香。' },
  { id: 'sndp_aobamuseum', name: '仙台市博物馆', icon: '🏛️', price: 0, desc: '青叶山脚的市博物馆珍藏着伊达家传宝刀与政宗公甲胄。馆前骑马铜像眺望全城，先看文物再登城迹，才算读懂独眼龙的一生。' },
  { id: 'sndp_zuiganji', name: '瑞巌寺', icon: '🏮', price: 700, desc: '政宗下令兴建的临济宗古刹，国宝本堂内狩野派壁画金碧辉煌。参道穿过千年杉林通往海湾，松岛“静”的一面都在这里。' },
  { id: 'sndp_miyagibijutsu', name: '宫城县美术馆', icon: '🖼️', price: 0, desc: '广濑川畔的美术馆收藏佐藤忠良雕刻与仙台藩古美术。坐在临河咖啡座远眺青叶城，艺术、绿意与河景在午后慢慢合流。' },
  { id: 'sndp_daikannon', name: '仙台大观音', icon: '🗿', price: 0, desc: '高一百米的白色观音立在西郊，乘电梯登顶可眺太平洋与仙台平原。各层设佛教美术展示，游客不多，本地人常来祈愿，安静得出奇。' },
  { id: 'sndp_kokubuncho', name: '国分町', icon: '🌃', price: 0, desc: '仙台最热闹的夜之街，数百家居酒屋与酒吧挤在方格街区里。华灯初上炭火香飘，烤串配地酒，是东北之夜最地道的打开方式。' },
  /* ---- 神社名汤与山岳（新增） ---- */
  { id: 'sndp_shiogamajinja', name: '盐灶神社', icon: '⛩️', price: 0, desc: '东北总镇守，长石阶直通山顶拜殿，可眺盐釜湾与松岛群岛。每年七月盐灶港祭，彩船竞渡的海上行列是东北夏日名场面。' },
  { id: 'sndp_shiroishijo', name: '白石城', icon: '🏯', price: 0, desc: '伊达家重臣片仓小十郎的居城，天守平成时代依古图复原，白壁洁净。城下保留武家屋敷与街门，雪后银装更有奥州小城的味道。' },
  { id: 'sndp_narukoonsen', name: '鸣子温泉乡', icon: '♨️', price: 1000, desc: '鸣子温泉泉质多样，自古是东北疗养胜地，也是こけし木偶的故乡。宿一晚老温泉，泡汤后逛木偶工房，看匠人一刀刀削出笑脸。' },
  { id: 'sndp_narukokyo', name: '鸣子峡', icon: '🍁', price: 0, desc: '大谷川切出的V形深谷，红叶季从见晴台俯瞰铁桥最壮观。步道沿溪缓缓下降，深秋满谷红叶如火烧，入冬则覆上厚厚白雪。' },
  { id: 'sndp_zaookama', name: '藏王·御釜', icon: '🌋', price: 0, desc: '藏王连峰火山口湖“御釜”，湖水随光线在祖母绿与蓝绿间变色。环湖步道终年云雾翻涌，是宫城与山形交界的神秘地标。' },
  { id: 'sndp_akiuotaki', name: '秋保大瀑布', icon: '💧', price: 0, desc: '高五十五米的白练垂入碧潭，入选“日本瀑布百选”。旁有观瀑台与吊桥，新绿、红叶、冰瀑四季不同，和秋保温泉可排成一日。' },
  /* ---- 海湾与海港活力（新增） ---- */
  { id: 'sndp_uminomori', name: '仙台海洋之森水族馆', icon: '🐬', price: 2000, desc: '仙台港边的海水馆把松岛湾当天然布景，海豚与海狮表演人气很高。触摸池、企鹅散步适合亲子，回程顺道在港口看日落。' },
  { id: 'sndp_isokaze', name: '石卷·女川复兴海岸', icon: '🌊', price: 0, desc: '海啸重创的三陆沿岸重新生长，石卷保留震灾纪念与重建堤防。建筑师坂茂设计的木造女川站，已成为当地人“回家”的温暖之门。' },
  { id: 'sndp_rakuten', name: '乐天金鹫主场·宫城球场', icon: '⚾', price: 1800, desc: '东北职棒唯一主场，夏夜白色应援棒海随节奏起伏。看台卖牛舌便当与毛豆泥冰品，一场球赛把仙台味道与棒球热情一次看够。' }
);

