window.SZO_GIFTS.push(
  /* ---- 沿用原条目 ---- */
  { id: 'shizuoka_unagi', name: '清水金枪鱼饭', icon: '🍣', tag: '食', type: '美食', price: 2000, desc: '清水港直供金枪鱼盖饭与煮金枪鱼。"鲔鱼之乡"的骄傲，樱虾天妇罗同吃。' },
  { id: 'shizuoka_sakuraebi', name: '由比樱虾', icon: '🍤', tag: '食', type: '特产', price: 1200, desc: '樱虾"海之樱花"，生食甜如虾糖。樱虾釜饭与天妇罗，由比港限定。' },
  { id: 'shizuoka_unagi_pie', name: '鳗鱼派', icon: '🥧', tag: '食', type: '特产', price: 800, desc: '"夜里的鳗鱼派"国民点心，加鳗鱼粉的甜酥饼。静冈手信之王。' },
  { id: 'shizuoka_tea', name: '静冈茶', icon: '🍵', tag: '食', type: '特产', price: 1500, desc: '日本最大产茶县，"深蒸し茶"浓香。茶田与富士山同框的产地，茶园民宿可体验采摘。' },
  { id: 'shizuoka_oden', name: '静冈关东煮（黑关东煮）', icon: '🍢', tag: '食', type: '美食', price: 500, desc: '墨鱼汁染黑的串串，"黑关东煮"。青叶关东煮横丁，本地夜宵。' },
  { id: 'shizuoka_wasanbon', name: '安倍川饼', icon: '🍡', tag: '食', type: '美食', price: 300, desc: '烤麻糬裹黄豆粉红糖，安倍川畔茶屋名物。"东海道的味道"。' },
  { id: 'shizuoka_chibi', name: '小丸子周边', icon: '👧', tag: '衣', type: '文创', price: 1000, desc: '小丸子玩偶、花轮同学徽章、野口笔袋。清水限定，"童年杀"。' },
  { id: 'shizuoka_fuji', name: '富士山文创', icon: '🗻', tag: '衣', type: '文创', price: 1200, desc: '富士山杯（倒酒成山）、赤富士挂画。"静冈看到的富士山"文创。' },
  { id: 'shizuoka_tea_ride', name: '茶园采摘体验', icon: '🌱', tag: '玩', type: '体验', price: 2000, desc: '茶田摘一芽两叶，炒茶品尝。坐着看富士山喝茶，"茶农的一天"。' },
  { id: 'shizuoka_onsen2', name: '热海温泉街巡汤', icon: '♨️', tag: '玩', type: '体验', price: 1500, desc: '热海七汤巡礼，"来宫神社+温泉馒头"。海景温泉旅馆看日出。' },
  { id: 'shizuoka_ferry', name: '骏河湾渡轮', icon: '⛴️', tag: '行', type: '体验', price: 1800, desc: '清水→土肥的海上航线，船上望富士山。"海上富士"的经典视角。' },
  { id: 'shizuoka_minsu', name: '茶田民宿', icon: '🏨', tag: '住', type: '住宿', price: 8000, desc: '茶园环绕的民宿，露台正对富士山。清晨采茶人已在田间。' },
  /* ---- 静冈味道（新增） ---- */
  { id: 'szog_yakisoba', name: '富士宫炒面', icon: '🍜', tag: '食', type: '美食', price: 600, desc: '富士宫街头的灵魂炒面，蒸粗面加猪油渣在铁板翻飞。淋上特制酱汁再撒木鱼花，锅气十足是平民名物。' },
  { id: 'szog_maguro_sushi', name: '金枪鱼握寿司', icon: '🍣', tag: '食', type: '美食', price: 2500, desc: '清水港直送的金枪鱼，赤身与大腹片片油亮。师傅现切现捏，醋饭微温鱼鲜化开，是静冈人最骄傲的一贯。' },
  { id: 'szog_cha_parfait', name: '静冈茶芭菲', icon: '🍨', tag: '食', type: '美食', price: 1000, desc: '深蒸茶的翠绿做成冰淇淋、蛋糕与茶冻层层叠叠。茶田旁的咖啡店端出一杯，微苦与奶甜在舌尖握手言和。' },
  { id: 'szog_wasabizuke', name: '山葵渍', icon: '🥒', tag: '食', type: '特产', price: 1000, desc: '静冈清流养大的本山葵，磨泥辛香直冲鼻腔。用酒粕渍成的山葵渍微呛回甘，配茶泡饭或白饭都格外开胃。' },
  { id: 'szog_sakuraebi_senbei', name: '樱虾煎饼', icon: '🍘', tag: '食', type: '特产', price: 700, desc: '整只粉红樱虾压进米饼烘烤，咔嚓一声虾香满口。由比港老铺现烤的香气飘满巷子，是最粉嫩的静冈手信。' },
  { id: 'szog_mikan', name: '静冈柑橘礼盒', icon: '🍊', tag: '食', type: '特产', price: 1000, desc: '伊豆半岛与滨名湖畔的蜜柑，冬日满山挂起橙色小灯笼。皮薄多汁，剥开一瓣亮晶晶，甜里一点酸最解腻。' },
  /* ---- 手信与文创（新增） ---- */
  { id: 'szog_tenugui_fuji', name: '富士手拭巾', icon: '🧣', tag: '衣', type: '服饰', price: 900, desc: '棉布上手绘富士山、茶田与骏河湾的四季图案。当发带、裹便当或作桌旗，一方手巾把静冈的蓝白带回家。' },
  { id: 'szog_bamboo', name: '骏河竹千筋细工', icon: '🎋', tag: '玩', type: '文创', price: 2000, desc: '细如发丝的竹丝编出几何格纹，是静冈传统工艺的名片。茶托、香盒件件手工，匠人一天只做得了几只。' },
  { id: 'szog_goshuin', name: '富士山御朱印帐', icon: '📖', tag: '闻', type: '文创', price: 1500, desc: '封面印着富士山与朱红鸟居的御朱印帐，附浅间大社社纹。登山前请一册，走遍静冈神社把回忆一枚枚盖满。' },
  /* ---- 体验与住宿（新增） ---- */
  { id: 'szog_wasabi_farm', name: '山葵田见学', icon: '🥾', tag: '游', type: '体验', price: 1000, desc: '赤脚踩进清冽的泽田，听农人讲山葵爱净水的脾气。现磨现吃一整根，辛味冲上脑门的瞬间，山水都有了滋味。' },
  { id: 'szog_izu_pottery', name: '伊豆高原陶艺手作', icon: '🎨', tag: '游', type: '体验', price: 3000, desc: '伊豆高原的窑场开着陶艺课，拉坯手捏任你发挥。烧成后寄回家里，杯沿留着火山土的粗粝，喝水便想起伊豆。' },
  { id: 'szog_shizutetsu', name: '静铁电车一日券', icon: '🚋', tag: '行', type: '体验', price: 700, desc: '新静冈到清水的老式电车，木椅与叮当声满是昭和味。摇摇晃晃穿过茶田老街，富士山时而在窗外探出头。' },
  { id: 'szog_oigawa_sl', name: '大井川蒸汽火车', icon: '🚂', tag: '行', type: '体验', price: 1800, desc: '黑头火车突突开过茶田溪谷，汽笛一响煤烟扑鼻。木椅车厢吱呀作响，窗外景致如老电影般一格格后退。' },
  { id: 'szog_deep_fishing', name: '骏河湾深海钓鱼', icon: '🎣', tag: '玩', type: '体验', price: 6000, desc: '骏河湾深逾千米，渔船上放线直探海底。金目鲷瞪着大眼出水的那一刻，整船人的欢呼比海鸥声还响亮。' },
  { id: 'szog_onsen_ryokan', name: '修善寺温泉旅馆', icon: '🛁', tag: '住', type: '住宿', price: 30000, desc: '桂川边的老铺旅馆，露天风吕正对竹林溪声。夕食是伊豆山海旬味，泡完汤穿浴衣散步，最像静冈的夜晚。' }
);

/* ================= data/world/asia/JP/shizuoka/szo_03_stories.js ================= */
/* 静冈 分册03：奇闻趣事（沿用原条目/富士山与茶/开国与文学/伊豆物语） */
window.SZO_STORIES = window.SZO_STORIES || [];
window.SZO_STORIES.push(
  /* ---- 沿用原条目 ---- */
  { id: 'shizuoka_story_chibimaruko2', name: '小丸子的"清水记忆"', icon: '👧', desc: '樱桃子笔下的清水市：爷爷的任性、花轮的贵气。她故乡的樱桃小丸子主题馆，全是最真实的场景。' },
  { id: 'shizuoka_story_hagoromo', name: '天女羽衣的传说', icon: '🧚', desc: '渔民拾得羽衣，天女无法回天。三保松原的"羽衣之松"传了千年，能剧《羽衣》的舞台。' },
  { id: 'shizuoka_story_ieyasu', name: '家康的"第二次人生"', icon: '🏯', desc: '德川家康把将军位让给秀忠后定居骏府，"大御所政治"。骏府城是他的"退休俱乐部"。' },
  { id: 'shizuoka_story_tea2', name: '静冈茶的"山地魔法"', icon: '🍵', desc: '静冈产茶面积日本第一，山地雾气是秘诀。"深蒸し"工艺让茶汤更浓绿。' },
  { id: 'shizuoka_story_fuji_view', name: '看富士山最好的地方', icon: '🗻', desc: '静冈人说："富士山是我们的"。三保松原、岩本山公园、茶田，"三面富士"各有美法。' },
  { id: 'shizuoka_story_blackoden', name: '黑关东煮的"墨汁秘密"', icon: '🍢', desc: '静冈关东煮用墨鱼汁染黑汤底，"黑色的深夜美食"。老铺几十年不换汤，"越黑越醇"。' },
  /* ---- 富士山与信仰 ---- */
  { id: 'szos_fuji_summit', name: '富士山顶的"私有地"', icon: '🗻', desc: '富士山顶约三千三百六十五米以上，其实是浅间大社的私有地。登山季数十万人，都踩在"别人家的屋顶"上看日出。' },
  { id: 'szos_sengen_faith', name: '浅间大社的火山女神', icon: '🌋', desc: '富士信仰供奉木花开耶姬，传说她于火焰中产子以证清白。为镇住富士的火气，全日本才有了上千座浅间神社。' },
  { id: 'szos_ieyasu_kunozan', name: '家康的久能山长眠', icon: '⛩️', desc: '家康病逝于骏府城，遗命葬于能望见富士的久能山。一年后灵柩迁往日光，山上的社殿仍守望着骏河湾的晨光。' },
  /* ---- 开国与文学 ---- */
  { id: 'szos_blackship', name: '黑船开国下田', icon: '🚢', desc: '一八五四年佩里的黑船泊进下田港，隔着海滩双方好奇张望。条约在了仙寺签下，开国的风从这里吹遍整个日本。' },
  { id: 'szos_odoriko', name: '川端康成的伊豆舞女', icon: '👣', desc: '青年川端康成独自翻越天城峠，偶遇巡游卖艺的舞女。一段同行的朦胧情愫化作《伊豆的舞女》，山道从此有诗意。' },
  /* ---- 茶与山海名物 ---- */
  { id: 'szos_makinohara', name: '旧武士开茶田', icon: '🍃', desc: '废藩后失去俸禄的旧武士，把荒凉的牧之原开成茶田。一把锄头一垄新绿，静冈"茶业王国"的底子就此打牢。' },
  { id: 'szos_wasabi', name: '山葵为何爱静冈', icon: '💧', desc: '山葵只肯在流动清泉里扎根，静冈的山涧泽田恰好养它。据说栽培山葵的始祖地，就在安倍川上游的有东木。' },
  { id: 'szos_sakuraebi', name: '由比的樱色小虾', icon: '🍤', desc: '世界罕见的大群樱虾，只在骏河湾深处群游。粉红虾身像漂在海底的樱花，捕捞季连渔港的灯火都染成樱色。' },
  { id: 'szos_abekawa_mochi', name: '家康吃过的安倍川饼', icon: '🍡', desc: '传说家康在安倍川畔歇脚，茶屋端上滚了黄豆粉的团子。他问这叫何物，店家随口答"安倍川饼"，一传就是四百年。' },
  { id: 'szos_satta_ukiyoe', name: '广重笔下的萨埵峠', icon: '🖼️', desc: '《东海道五十三次》里的"由比"画的就是萨埵峠望富士。江户人隔着版画惊叹的风景，如今在旧道上原样等你看。' },
  /* ---- 伊豆物语 ---- */
  { id: 'szos_toro_rice', name: '登吕的弥生稻田', icon: '🏺', desc: '两千年前的弥生人在这里插秧织布，一场洪水埋住了整个村落。出土的木锄与土器，还原了教科书里的稻作黎明。' },
  { id: 'szos_shuzenji_raid', name: '修禅寺里的将军末路', icon: '⚔️', desc: '镰仓二代将军源赖家被废后幽居伊豆，最终在修禅寺遇害。古刹钟声里藏着权斗的血色，本地人却说这里的水最养人。' },
  { id: 'szos_izu_volcanic', name: '伊豆曾是座岛', icon: '🌏', desc: '千万年前伊豆还是太平洋上的火山岛，随板块漂移撞上本州。碰撞的余波留下温泉与悬崖，让半岛成了地质博物馆。' },
  { id: 'szos_oigawa_sl', name: '大井川的蒸汽列车', icon: '🚂', desc: '大正末年为了运送木材而开通的铁路，如今是观光蒸汽列车。煤烟、汽笛与木椅车厢，载着人们驶回昭和的车站。' }
);

