/* ================= data/world/europe/GB/london/gb_03_stories.js ================= */
/* 伦敦 分册03：奇闻趣事（Mind the Gap/乌鸦/雨/免费博物馆/披头士/卫兵扑克脸） */
window.GB_STORIES = window.GB_STORIES || [];
window.GB_STORIES.push(
  /* ---- 原档沿用条目 ---- */
  { id: 'london_story_mind', name: '"Mind the Gap"的百年广播', icon: '🚇', desc: '伦敦地铁这句"小心空隙"喊了一百多年，甚至有人专门录下老伴的录音循环播放。英式浪漫藏在站台里。' },
  { id: 'london_story_crow', name: '伦敦塔的乌鸦传说', icon: '🐦‍⬛', desc: '传说乌鸦飞走王国就会倒塌，于是塔里养着六只"官方乌鸦"，有专属饲养员，翅膀还会定期修剪。' },
  { id: 'london_story_rain', name: '伦敦的"四季一天"', icon: '🌦️', desc: '伦敦一天能经历晴雨雾风，本地人出门永远带伞。"不是雨大，是伞小"成了伦敦人的自嘲。' },
  { id: 'london_story_free', name: '免费的博物馆哲学', icon: '🏛️', desc: '大英博物馆、国家美术馆全部免费，靠"建议捐赠"运营。伦敦人说：文化是公共财产，不该设门槛。' },
  { id: 'london_story_beatles', name: ' Abbey Road 的斑马线', icon: '🎸', desc: '披头士专辑封面的过马路斑马线成了朝圣地，游客排着队模仿四人行走。斑马线旁的录音棚还在营业。' },
  { id: 'london_story_queen', name: '卫兵的"扑克脸"', icon: '👑', desc: '红衣卫兵面对游客做鬼脸、挡路挑逗都纹丝不动。据说绷不住笑的卫兵会被加练，扑克脸是职业素养。' },
  /* ---- 皇室与历史 ---- */
  { id: 'gbs_1066', name: '1066 黑斯廷斯与诺曼底', icon: '⚔️', desc: '1066 年诺曼底公爵威廉征服英格兰，伦敦塔从此成为皇室堡垒。"英国历史的转折点"。' },
  { id: 'gbs_tudor', name: '都铎王朝的亨利八世', icon: '👑', desc: '亨利八世为休妻与罗马决裂，创立英国国教。六位王后两位被砍头，"英国历史上最多戏的国王"。' },
  { id: 'gbs_queen_vic', name: '维多利亚与"日不落帝国"', icon: '👸', desc: '1837-1901 年在位的维多利亚女王，大英帝国版图最大。"日不落帝国"统治全球 1/4 人口。' },
  { id: 'gbs_queen_now', name: '伊丽莎白二世与王室"现代"', icon: '👑', desc: '1952-2022 年在位的伊丽莎白二世，见证英国从帝国到英联邦。温莎城堡的圣乔治礼拜堂是她的长眠地。' },
  /* ---- 大英帝国与殖民 ---- */
  { id: 'gbs_empire', name: '大英博物馆的"藏品争议"', icon: '🏛️', desc: '罗塞塔石碑、帕特农雕塑、非洲木雕都来自殖民掠夺。近年希腊、埃及要求归还"文明的大账本"。' },
  { id: 'gbs_londonderry', name: '爱尔兰与北爱问题', icon: '☘️', desc: '1916 年复活节起义、1921 年爱尔兰独立。北爱至今是"英国唯一边境争议"。' },
  /* ---- 工业革命与现代化 ---- */
  { id: 'gbs_steam', name: '瓦特与蒸汽机', icon: '⚙️', desc: '1769 年瓦特改良蒸汽机，工业革命从英国曼彻斯特起步。世界从此走向"机器时代"。' },
  { id: 'gbs_tube', name: '1863 全球第一条地铁', icon: '🚇', desc: '伦敦大都会线 1863 年开通，全球第一条地铁。使用蒸汽机车把路面交通搬到地下。' },
  { id: 'gbs_wwi', name: '一战与"失去的一代"', icon: '🕯️', desc: '1914-1918 年英国阵亡 90 万人，整整一代英国青年阵亡。威斯敏斯特教堂的"无名战士墓"是他们的纪念。' },
  /* ---- 文学与艺术 ---- */
  { id: 'gbs_shakespeare', name: '莎士比亚的环球剧场', icon: '🎭', desc: '莎翁 1599 年在泰晤士河南岸建环球剧场，原址重建后 1997 年重开。夏季演出还是"木结构露天剧场"。' },
  { id: 'gbs_dickens', name: '狄更斯的伦敦', icon: '📚', desc: '狄更斯在伦敦写了《雾都孤儿》《双城记》。他的伦敦有雾有童工，"工业革命的社会剖面"。' },
  { id: 'gbs_potter', name: '比得兔与湖区', icon: '🐰', desc: '波特小姐 1902 年在湖区写《比得兔》。英国"儿童文学"的开山鼻祖，至今仍授权全球玩具与绘本。' },
  /* ---- 现代英国 ---- */
  { id: 'gbs_finance', name: '金融城与"伦敦金"', icon: '💷', desc: '伦敦金融城面积仅一平方英里，全球外汇交易的 40% 在这里完成。劳埃德保险公司、伦敦证券交易所，"全球金融心跳"。' },
  { id: 'gbs_brexit', name: '2020 英国脱欧', icon: '🇬🇧', desc: '2020 年 1 月 31 日英国正式脱离欧盟，47 年欧盟成员身份结束。英镑短期跌到 1985 年水平。' },
  /* ---- 体育与文化 ---- */
  { id: 'gbs_wimbledon', name: '温布尔登与草莓奶油', icon: '🍓', desc: '温网 1877 年起，草地网球与草莓奶油是"英伦夏季"。中央球场紧张到"针掉都听见"。' },
  { id: 'gbs_football', name: '现代足球的"英格兰起源"', icon: '⚽', desc: '1863 年英格兰足球协会成立，现代足球规则从此诞生。阿森纳、切尔西、热刺都在伦敦。' },
  /* ---- 风俗与生活 ---- */
  { id: 'gbs_queen_birthday', name: '英国双"国庆日"', icon: '🎉', desc: '6 月第二个周六是"国王生日阅兵"，8 月最后一个周末是"夏季节日 bank holiday"。"英国假日的双轨制"。' },
  { id: 'gbs_pirate', name: 'BBC 与英伦口音的"世界输出"', icon: '📡', desc: 'BBC 创立于 1922 年，标准英音是全球的语言标杆。《神探夏洛克》《唐顿庄园》输出"英伦文化"。' }
);

